INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C1','sci',3,2,'u2',1,'지구의 다양한 모습 — 지구의 육지와 바다에는 사막, 북극의 빙하, 고래가 사는 바다, 강, 호수, 들판, 갯벌처럼 다양한 모습이 있음 · 달 표면처럼 지구 밖의 모습은 오늘 떠올리는 지구의 모습이 아님 · 장소마다 볼 수 있는 모습이 다름(빙하-북극곰, 갯벌-게·짱뚱어, 사막-모래 언덕)',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C2','sci',3,2,'u2',1,'다른 그림 찾기 방법과 태도 — 두 그림 (가)·(나)를 장소마다 하나씩 견주어 다른 부분을 찾음 · 찾으면 찾은 장소를 말해 알려 줌 · 구역을 나누어 함께 찾고, 친구 생각이 달라도 존중함 · 이기고 지는 놀이가 아니라 지구의 모습을 함께 살펴보는 놀이',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C3','sci',3,2,'u2',2,'공기를 느낄 수 있는 상황 — 공기는 눈에 보이지 않지만 우리 주변 어디에나 있음 · 비눗방울 안을 공기가 채움 · 연, 바람개비, 돛단배는 바람을 받아 움직이고, 숨 쉬기·풍선 불기는 숨으로, 부채질은 바람을 일으켜 공기를 느낌 · 열기구·패러글라이딩을 하는 곳에도 공기가 있음',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C4','sci',3,2,'u2',2,'대기 — 지구를 둘러싸고 있는 공기를 대기라고 함 · 바람이 불 때, 숨을 쉴 때 대기를 느낄 수 있음 · 대기가 없으면 숨을 쉴 수 없음',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C5','sci',3,2,'u2',3,'육지와 바다 — 땅으로 이루어진 곳이 육지, 물로 덮여 있는 곳이 바다 · 육지에서는 산, 들, 강, 계곡, 사막, 빙하 등 다양한 모습을 볼 수 있음 · 우주에서 본 지구가 여러 색인 것은 다양한 모습이 있기 때문',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C6','sci',3,2,'u2',3,'붙임쪽지로 육지와 바다 넓이 견주기 — 지구본 칸마다 육지가 절반이 넘으면 육지 붙임쪽지, 바다가 절반이 넘으면 바다 붙임쪽지를 겹치지 않게 붙임 · 붙임쪽지가 더 많이 필요할수록 더 넓은 곳 · 개수는 모둠마다 달라도 바다가 육지보다 넓다는 결과는 같음',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C7','sci',3,2,'u2',3,'육지의 물과 바닷물 — 지구의 물은 육지의 물과 바닷물로 나눔 · 육지의 물은 강, 호수, 계곡, 빙하 등에서 찾고 바다에는 바닷물이 있음 · 지구의 물은 대부분 바닷물이라 우리가 쓸 수 있는 육지의 물은 적어 아껴 써야 함',ARRAY['[4과06-01] 지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C8','sci',3,2,'u2',4,'육지의 물과 바닷물을 가열하는 실험 방법과 안전 — 두 물을 같은 양씩 증발 접시에 담고 끓임쪽(물이 갑자기 끓어오르지 않게 넣는 돌이나 유리 조각)을 넣어 물이 없어질 때까지 가열함 · 실험 재료는 맛보지 않음 · 보안경과 면장갑을 쓰고, 증발 접시는 집게로 옮기며, 핫플레이트는 전원을 끈 뒤에도 뜨거움',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C9','sci',3,2,'u2',4,'바닷물의 특징 — 육지의 물은 가열해도 남는 물질이 없지만 바닷물은 하얗고 거칠거칠하며 냄새가 없는 물질이 남음 · 남는 물질의 대부분은 소금 · 바닷물은 소금이 녹아 있어 짠맛이 나고 사람이 마시거나 농사를 짓는 데 알맞지 않음',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C10','sci',3,2,'u2',5,'지형과 바닷가 지형의 특징 — 땅의 생김새를 지형이라고 함 · 바닷가에서는 가파른 절벽, 바위에 구멍이 뚫려 물이 지나가는 동굴, 고운 흙이나 모래가 넓게 펼쳐진 모래사장, 진흙이 보이고 색이 어두운 갯벌 등을 볼 수 있음',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C11','sci',3,2,'u2',5,'바닷가 지형 조사·분류·공유 — 스마트 기기나 여행 사진으로 바닷가 지형을 조사함 · 바위로 이루어진 지형(절벽·동굴)과 모래나 흙으로 이루어진 지형(모래사장·갯벌)으로 나눌 수 있음 · 네 가지 외에도 바닷가 지형이 더 있음 · 사진을 나눌 때 비방하는 댓글을 달지 않고 친구 생각을 존중함',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C12','sci',3,2,'u2',6,'밀물과 썰물 — 바닷물이 바다에서 육지 쪽으로 밀려 들어오는 것이 밀물, 육지에서 바다 쪽으로 빠져나가는 것이 썰물 · 밀물 때 바닷물의 높이가 높아지고 썰물 때 낮아짐 · 바닷물의 높이는 시간에 따라 달라짐',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C13','sci',3,2,'u2',6,'밀물·썰물 모형과 바닷가 모습 — 모형에서 밀물 때는 모래사장의 표지판이 잠기고 바닷길이 사라지며, 썰물 때는 표지판과 바닷길이 드러남 · 바닷길이 드러난 썰물 때 걸어서 섬에 갈 수 있음 · 파도가 잠깐 밀려왔다 쓸려 나가는 것과 달리 밀물과 썰물은 일정 시간 동안 이어짐',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C14','sci',3,2,'u2',7,'갯벌의 뜻과 우리나라 갯벌 — 갯벌은 밀물 때 바닷물에 잠기고 썰물 때 바닷물 밖으로 드러나는 땅 · 우리나라 갯벌은 밀물과 썰물 때 바닷물의 높이 차가 큰 서해안과 남해안에 주로 있고, 높이 차가 작은 동해안에서는 찾아보기 어려움 · 칠게, 갯지렁이, 바지락, 낙지, 알락꼬리마도요, 퉁퉁마디가 삶',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C15','sci',3,2,'u2',7,'갯벌의 역할(가치) — 조개, 게 등 다양한 생물의 터전 · 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 하고 갯벌 생물이 오염 물질을 분해함 · 철새와 물고기가 알을 낳고 새끼를 기르기 좋은 환경 · 홍수나 태풍의 피해를 줄여 줌 · 게와 지렁이가 굴을 파 신선한 공기가 드나들어 갯벌이 썩지 않음',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C16','sci',3,2,'u2',7,'갯벌 보전 — 갯벌은 우리에게 많은 도움을 주는 소중한 땅이라 잘 보전해야 함 · 쓰레기를 함부로 버리지 않고 체험 때 생물을 함부로 잡지 않음 · 갯벌은 바닷물이 드나드는 곳이라 오염된 갯벌을 울타리로 막아도 바다 전체를 오염시킬 수 있음 · 갯벌의 가치를 알림',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C17','sci',3,2,'u2',8,'갯벌 보전 홍보 자료 만들기 — 기름 유출 사고 같은 문제 상황 → 계획서(해결 방법·역할 나누기·넣고 싶은 내용·보완할 점) → 만들기 → 소통하기 · 홍보 자료에는 갯벌의 가치와 보전의 필요성, 우리가 할 일을 담음 · 가져온 자료는 출처를 밝힘 · 다른 모둠 자료는 잘 듣고 잘한 점을 칭찬하며 보완할 점은 함께 고침 · 화려한 꾸밈보다 가치와 필요성이 잘 드러나는 것이 중요',ARRAY['[4과06-03] 밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득·홍보한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C18','sci',3,2,'u2',9,'바다에서 얻는 먹을거리와 해조류 — 바다는 살아가는 데 필요한 자원을 많이 줌 · 게, 조개 같은 식량과 김, 미역, 다시마 같은 해조류를 얻음 · 해조류는 화장품이나 건강식품의 재료로도 쓰임',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u2-C19','sci',3,2,'u2',9,'바다에서 얻는 소금·마실 물·전기 — 바닷물을 끌어 들여 논처럼 만든 염전에서 바닷물을 햇빛에 두어 소금을 얻음(우리나라 염전은 서해안에 많음) · 바닷물을 이용 가능한 물로 바꾸는 기술은 물 부족 문제 해결에 도움 · 파도가 치는 힘이나 밀물과 썰물의 차이로 환경 오염 걱정이 없는 전기를 만듦 · 해양 공학자, 해양 연구원이 바다를 연구함',ARRAY['[4과06-02] 바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X01','sci',3,'u2',ARRAY['SC3-2-u2-C1']::text[],'달 표면처럼 지구 밖의 모습을 지구의 모습으로 여기거나, 지구에 한두 가지 모습만 있다고 여긴다','지구의 다양한 모습') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X02','sci',3,'u2',ARRAY['SC3-2-u2-C1']::text[],'장소와 그곳에서 볼 수 있는 모습을 잘못 잇는다(빙하에 게와 짱뚱어, 사막에 북극곰 등)','빙하 · 갯벌 · 사막') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X03','sci',3,'u2',ARRAY['SC3-2-u2-C2']::text[],'두 그림을 견준 결과를 뒤바꾸거나 한 그림만 보고 다른 부분을 말한다','장소마다 하나씩 견주어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X04','sci',3,'u2',ARRAY['SC3-2-u2-C2']::text[],'다른 그림 찾기 방법과 태도를 잘못 안다(먼저 크게 외치기, 혼자만 알기, 정답만 가리키기, 이기고 지는 놀이로 여기기 등)','찾은 장소를 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X05','sci',3,'u2',ARRAY['SC3-2-u2-C3','SC3-2-u2-C4']::text[],'공기는 눈에 보이지 않으니 없다고 여기거나 비눗방울 속이 비어 있다고 여긴다','보이지 않아도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X06','sci',3,'u2',ARRAY['SC3-2-u2-C3']::text[],'공기는 하늘이나 바람 부는 곳처럼 정해진 곳에만 있다고 여긴다','어디에나 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X07','sci',3,'u2',ARRAY['SC3-2-u2-C3']::text[],'공기를 느끼는 경험을 잘못 고르거나(컵에 담긴 물 등), 바람을 받아 움직이는 것과 숨으로 느끼는 것을 뒤바꾼다','바람 · 숨 · 부채') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X08','sci',3,'u2',ARRAY['SC3-2-u2-C4']::text[],'대기의 뜻을 잘못 안다(바람, 구름, 바다, 우주 등으로)','지구를 둘러싼 공기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X09','sci',3,'u2',ARRAY['SC3-2-u2-C4']::text[],'대기가 없어도 우리 생활에 아무 변화가 없다고 여긴다','숨을 쉴 수 있게 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X10','sci',3,'u2',ARRAY['SC3-2-u2-C5']::text[],'육지와 바다의 뜻을 뒤바꾸거나 육지의 모습(강, 계곡, 빙하 등)을 바다로 여긴다','땅 · 물로 덮인 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X11','sci',3,'u2',ARRAY['SC3-2-u2-C5','SC3-2-u2-C6']::text[],'육지에 볼 수 있는 모습이 더 많으니 육지가 바다보다 넓다고 여긴다','바다가 더 넓어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X12','sci',3,'u2',ARRAY['SC3-2-u2-C6']::text[],'붙임쪽지 활동 방법을 잘못 안다(절반 기준을 뒤바꾸기, 겹쳐 붙이기, 개수가 모든 모둠에서 같아야 한다고 여기기 등)','절반이 넘는 쪽으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X13','sci',3,'u2',ARRAY['SC3-2-u2-C6']::text[],'붙임쪽지 결과를 거꾸로 읽는다(적게 붙인 곳이 넓다, 개수로는 알 수 없다 등)','많이 붙인 곳이 넓어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X14','sci',3,'u2',ARRAY['SC3-2-u2-C7']::text[],'육지의 물과 바닷물이 있는 곳을 뒤바꾼다(강·호수를 바닷물로, 바다에서 육지의 물을 찾는 등)','강 · 호수 · 계곡 · 빙하') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X15','sci',3,'u2',ARRAY['SC3-2-u2-C7','SC3-2-u2-C9']::text[],'지구의 물은 대부분 육지의 물이라고 여기거나 쓸 수 있는 물이 많아 아끼지 않아도 된다고 여긴다','대부분이 바닷물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X16','sci',3,'u2',ARRAY['SC3-2-u2-C8']::text[],'실험 재료를 맛보거나 안전 약속을 지키지 않는다(맨손으로 옮기기, 전원을 끈 바로 뒤 만지기, 보안경 안 쓰기 등)','맛보지 않기 · 집게 · 보안경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X17','sci',3,'u2',ARRAY['SC3-2-u2-C8']::text[],'끓임쪽의 쓰임이나 실험 방법을 잘못 안다(두 물을 같은 방법으로 가열하지 않기 등)','같은 양 · 같은 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X18','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'육지의 물도 가열하면 남는 물질이 있다고 여기거나, 바닷물에서 남는 물질이 없다고 여긴다','바닷물만 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X19','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'남은 물질의 관찰 결과(색깔·촉감·냄새)를 잘못 안다','하얗고 거칠거칠') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X20','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'바닷물이 짠 까닭을 잘못 안다(모래, 흙, 설탕 등)','소금이 녹아 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X21','sci',3,'u2',ARRAY['SC3-2-u2-C9']::text[],'바닷물을 그대로 마시거나 농사에 써도 된다고 여긴다','마시기에 알맞지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X22','sci',3,'u2',ARRAY['SC3-2-u2-C10']::text[],'지형의 뜻을 잘못 안다(날씨, 바닷물, 대기 등으로)','땅의 생김새') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X23','sci',3,'u2',ARRAY['SC3-2-u2-C10']::text[],'바닷가 지형의 특징을 뒤바꾼다(절벽에 구멍, 갯벌이 가파름, 모래사장 색이 어두움 등)','가파른 · 구멍 · 모래 · 진흙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X24','sci',3,'u2',ARRAY['SC3-2-u2-C10','SC3-2-u2-C11']::text[],'바닷가 지형은 정해진 몇 가지뿐이라고 여기거나 사막처럼 바닷가가 아닌 곳의 모습을 바닷가 지형으로 여긴다','네 가지 외에도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X25','sci',3,'u2',ARRAY['SC3-2-u2-C11']::text[],'바위로 이루어진 지형과 모래나 흙으로 이루어진 지형을 잘못 가른다','바위 · 모래나 흙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X26','sci',3,'u2',ARRAY['SC3-2-u2-C11']::text[],'지형을 조사하고 나눌 때 태도를 잘못 안다(비방하는 댓글, 관계없는 검색, 장난 등)','존중해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X27','sci',3,'u2',ARRAY['SC3-2-u2-C12']::text[],'밀물과 썰물의 뜻을 뒤바꾼다','밀려 들어오면 밀물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X28','sci',3,'u2',ARRAY['SC3-2-u2-C12']::text[],'밀물·썰물 때 바닷물의 높이 변화를 뒤바꾼다','밀물 때 높아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X29','sci',3,'u2',ARRAY['SC3-2-u2-C13']::text[],'표지판·바닷길 같은 바닷가 모습을 밀물·썰물 때와 잘못 잇는다(걸어서 섬에 가는 때를 밀물로 등)','썰물 때 길이 드러나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X30','sci',3,'u2',ARRAY['SC3-2-u2-C13']::text[],'파도가 밀려왔다 쓸려 나가는 것을 밀물·썰물과 같은 것으로 여긴다','파도는 잠깐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X31','sci',3,'u2',ARRAY['SC3-2-u2-C12','SC3-2-u2-C13']::text[],'바닷물의 높이는 언제나 같다고 여긴다','시간에 따라 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X32','sci',3,'u2',ARRAY['SC3-2-u2-C14']::text[],'갯벌의 뜻을 잘못 안다(언제나 잠긴 땅, 언제나 드러난 땅, 바위 지형 등)','잠기고 드러나는 땅') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X33','sci',3,'u2',ARRAY['SC3-2-u2-C14']::text[],'우리나라 갯벌이 있는 곳과 그 까닭을 잘못 안다(동해안에 많다, 바닷물이 짜서 등)','서해안 · 남해안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X34','sci',3,'u2',ARRAY['SC3-2-u2-C14']::text[],'갯벌에 사는 생물을 잘못 알거나 갯벌에는 생물이 살지 않는다고 여긴다','칠게 · 바지락 · 낙지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X35','sci',3,'u2',ARRAY['SC3-2-u2-C15']::text[],'갯벌의 역할을 잘못 안다(쓸모없다, 땅을 오염시킨다, 바닷물을 짜게 한다 등)','생물의 터전 · 깨끗한 바다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X36','sci',3,'u2',ARRAY['SC3-2-u2-C15']::text[],'갯벌에서 일어나는 일과 그 좋은 점을 잘못 잇는다(굴 파기 → 썩지 않음 등)','하는 일과 좋은 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X37','sci',3,'u2',ARRAY['SC3-2-u2-C16']::text[],'갯벌을 해치는 행동을 괜찮다고 여긴다(생물을 마음껏 잡기, 쓰레기 버리기 등)','함부로 잡지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X38','sci',3,'u2',ARRAY['SC3-2-u2-C16']::text[],'오염된 갯벌은 울타리로 막아 두면 괜찮다고 여긴다','바닷물이 드나들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X39','sci',3,'u2',ARRAY['SC3-2-u2-C17']::text[],'홍보 자료의 내용과 만드는 과정을 잘못 안다(화려한 꾸밈이 가장 중요, 가치와 필요성 빠뜨리기, 계획·역할 없이 만들기, 출처 안 밝히기 등)','가치와 보전의 필요성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X40','sci',3,'u2',ARRAY['SC3-2-u2-C17']::text[],'다른 모둠 자료를 살필 때 비난하거나 자기 모둠 자랑만 하고, 보완할 점을 함께 고칠 방법 없이 말한다','잘한 점 먼저 · 함께 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X41','sci',3,'u2',ARRAY['SC3-2-u2-C18']::text[],'바다에서 얻는 자원은 물고기 같은 먹을거리뿐이라고 여긴다','전기 · 소금 · 물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X42','sci',3,'u2',ARRAY['SC3-2-u2-C18']::text[],'해조류를 잘못 가르거나(조개·게를 해조류로) 해조류의 쓰임을 먹을거리로만 안다','김 · 미역 · 다시마') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X43','sci',3,'u2',ARRAY['SC3-2-u2-C19']::text[],'바다 자원과 얻는 방법을 잘못 잇는다(소금을 파도로, 전기를 햇빛으로, 염전을 동해안으로 등)','소금은 햇빛, 전기는 바닷물의 움직임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u2-X44','sci',3,'u2',ARRAY['SC3-2-u2-C19']::text[],'바다에서 얻는 전기와 바닷물을 바꾸는 기술의 좋은 점, 바다를 연구하는 사람을 잘못 안다','친환경 · 물 부족 · 해양 연구원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#1','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',1,'mc','auto','지구에서 볼 수 있는 모습이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u2-X01']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C1","difficulty":1,"kind":"mc","stem":"지구에서 볼 수 있는 모습이 아닌 것은 무엇인가요?","options":[{"t":"달 표면의 둥근 구덩이","correct":true},{"t":"사막의 모래 언덕","mis":"SC3-2-u2-X01"},{"t":"북극의 빙하","mis":"SC3-2-u2-X01"},{"t":"고래가 사는 바다","mis":"SC3-2-u2-X01"}],"explanation":["지구의 모습만 떠올려요.","달은 지구 밖에 있어요.","달 표면의 구덩이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#2','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',1,'sa','auto','북극곰이 사는, 얼음이 두껍게 쌓인 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C1","difficulty":1,"kind":"sa","stem":"북극곰이 사는, 얼음이 두껍게 쌓인 곳을 두 글자로 쓰세요.","answer":["빙하"],"explanation":["북극을 떠올려요.","얼음이 쌓여 있어요.","빙하예요."],"mis":"SC3-2-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#3','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C2',1,'ox','auto','다른 그림을 찾으면 찾은 장소를 말해 친구에게 알려 줘요.',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C2","difficulty":1,"kind":"ox","stem":"다른 그림을 찾으면 찾은 장소를 말해 친구에게 알려 줘요.","answer":"O","reason_options":[{"t":"친구들도 함께 찾을 수 있기 때문에","correct":true},{"t":"먼저 찾은 사람이 앞서는 놀이이기 때문에","mis":"SC3-2-u2-X04"}],"mis":"SC3-2-u2-X04","explanation":["함께하는 놀이예요.","장소를 말해 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#4','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',1,'mc','auto','진흙이 펼쳐져 있고 게와 짱뚱어를 볼 수 있는 곳은 어디인가요?',ARRAY['SC3-2-u2-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C1","difficulty":1,"kind":"mc","stem":"진흙이 펼쳐져 있고 게와 짱뚱어를 볼 수 있는 곳은 어디인가요?","options":[{"t":"갯벌","correct":true},{"t":"사막","mis":"SC3-2-u2-X02"},{"t":"빙하","mis":"SC3-2-u2-X02"},{"t":"들판","mis":"SC3-2-u2-X02"}],"explanation":["진흙을 떠올려요.","게가 살아요.","갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#5','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',2,'match','auto','장소와 그곳에서 볼 수 있는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C1","difficulty":2,"kind":"match","stem":"장소와 그곳에서 볼 수 있는 모습을 알맞게 이으세요.","pairs":[{"l":"빙하","r":"북극곰"},{"l":"갯벌","r":"게와 짱뚱어"},{"l":"사막","r":"모래 언덕"}],"mis":"SC3-2-u2-X02","explanation":["장소를 하나씩 떠올려요.","얼음 위에는 북극곰이에요.","빙하-북극곰, 갯벌-게, 사막-모래 언덕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#6','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C2',2,'mc','auto','두 그림 견주기 기록에서 (나)에만 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X03']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"mc","stem":"두 그림 견주기 기록에서 (나)에만 있는 것은 무엇인가요?","options":[{"t":"호수","correct":true},{"t":"강 위의 돌","mis":"SC3-2-u2-X03"},{"t":"파도가 치는 모습","mis":"SC3-2-u2-X03"},{"t":"아무것도 없다","mis":"SC3-2-u2-X03"}],"explanation":["(가)와 (나)를 견줘요.","호수 줄을 읽어요.","(나)에만 호수가 있어요."],"asset":{"type":"passage","lines":["강 — (가) 강 위에 돌이 있어요. (나) 강 위에 돌이 없어요.","호수 — (가) 호수가 없어요. (나) 호수가 있어요.","모래사장 — (가) 파도가 쳐요. (나) 진흙이 펼쳐진 갯벌이 보여요.","모래사장 뒤 — (가) 산이 없어요. (나) 산이 있어요."],"title":"두 그림 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#7','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C2',2,'mc','auto','다른 그림 찾기를 할 때 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"mc","stem":"다른 그림 찾기를 할 때 알맞은 방법은 무엇인가요?","options":[{"t":"친구와 구역을 나누어 함께 찾는다","correct":true},{"t":"혼자만 알고 말하지 않는다","mis":"SC3-2-u2-X04"},{"t":"친구보다 먼저 크게 외친다","mis":"SC3-2-u2-X04"},{"t":"정답만 손가락으로 가리킨다","mis":"SC3-2-u2-X04"}],"explanation":["함께 찾는 놀이예요.","구역을 나눠요.","함께 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#8','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C1',2,'blank','auto','「지구의 육지와 바다에는 (    )이 있어요.」 빙하, 사막, 갯벌도 그 가운데 하나예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X01']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C1","difficulty":2,"kind":"blank","stem":"「지구의 육지와 바다에는 (    )이 있어요.」 빙하, 사막, 갯벌도 그 가운데 하나예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"다양한 모습","correct":true},{"t":"한 가지 모습","mis":"SC3-2-u2-X01"},{"t":"달의 모습","mis":"SC3-2-u2-X01"},{"t":"우주의 모습","mis":"SC3-2-u2-X01"}],"explanation":["빙하, 사막, 갯벌을 떠올려요.","여러 가지예요.","다양한 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#9','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C2',2,'ox','auto','다른 그림 찾기는 가장 먼저 찾은 사람이 앞서는 놀이예요.',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"ox","stem":"다른 그림 찾기는 가장 먼저 찾은 사람이 앞서는 놀이예요.","answer":"X","reason_options":[{"t":"지구의 모습을 함께 살펴보는 놀이이기 때문에","correct":true},{"t":"빨리 찾아야 잘한 것이기 때문에","mis":"SC3-2-u2-X04"}],"mis":"SC3-2-u2-X04","explanation":["놀이의 목적을 떠올려요.","함께 살펴봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_basic#10','sci',3,2,'u2','L01','g3_2_sci_u2_L01_basic','lesson_basic','SC3-2-u2-C2',3,'mc','auto','두 그림 견주기 기록에서 「모래사장 뒤」를 견준 결과로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X03']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C2","difficulty":3,"kind":"mc","stem":"두 그림 견주기 기록에서 「모래사장 뒤」를 견준 결과로 알맞은 것은 무엇인가요?","options":[{"t":"(가)에는 산이 없고 (나)에는 산이 있다","correct":true},{"t":"(가)에는 산이 있고 (나)에는 산이 없다","mis":"SC3-2-u2-X03"},{"t":"(가)와 (나) 모두 산이 있다","mis":"SC3-2-u2-X03"},{"t":"(가)와 (나) 모두 산이 없다","mis":"SC3-2-u2-X03"}],"explanation":["마지막 줄을 읽어요.","(가)는 없어요.","(나)에만 산이 있어요."],"asset":{"type":"passage","lines":["강 — (가) 강 위에 돌이 있어요. (나) 강 위에 돌이 없어요.","호수 — (가) 호수가 없어요. (나) 호수가 있어요.","모래사장 — (가) 파도가 쳐요. (나) 진흙이 펼쳐진 갯벌이 보여요.","모래사장 뒤 — (가) 산이 없어요. (나) 산이 있어요."],"title":"두 그림 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#1','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C1',2,'sa','auto','모래 언덕을 볼 수 있는 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C1","difficulty":2,"kind":"sa","stem":"모래 언덕을 볼 수 있는 곳을 두 글자로 쓰세요.","answer":["사막"],"explanation":["모래가 쌓여 있어요.","물이 적은 곳이에요.","사막이에요."],"mis":"SC3-2-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#2','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C2',2,'mc','auto','두 그림 견주기 기록에서 (가)에만 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X03']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"mc","stem":"두 그림 견주기 기록에서 (가)에만 있는 것은 무엇인가요?","options":[{"t":"강 위의 돌","correct":true},{"t":"호수","mis":"SC3-2-u2-X03"},{"t":"모래사장 뒤의 산","mis":"SC3-2-u2-X03"},{"t":"진흙이 펼쳐진 갯벌","mis":"SC3-2-u2-X03"}],"explanation":["(가)를 먼저 봐요.","(나)에는 없어요.","강 위의 돌이에요."],"asset":{"type":"passage","lines":["강 — (가) 강 위에 돌이 있어요. (나) 강 위에 돌이 없어요.","호수 — (가) 호수가 없어요. (나) 호수가 있어요.","모래사장 — (가) 파도가 쳐요. (나) 진흙이 펼쳐진 갯벌이 보여요.","모래사장 뒤 — (가) 산이 없어요. (나) 산이 있어요."],"title":"두 그림 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#3','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C2',3,'error','auto','다른 그림 찾기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C2","difficulty":3,"kind":"error","stem":"다른 그림 찾기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「찾으면 친구보다 먼저 크게 외쳐야 해.」","correct":true,"mis_target":"SC3-2-u2-X04"},{"t":"친구 나 — 「구역을 나누어 함께 찾자.」","mis":"SC3-2-u2-X04"},{"t":"친구 다 — 「친구 생각이 나와 달라도 존중해.」","mis":"SC3-2-u2-X04"}],"explanation":["함께하는 놀이예요.","장소를 말해 줘요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#4','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C1',3,'mc','auto','지구에서 볼 수 있는 모습끼리만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X01']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C1","difficulty":3,"kind":"mc","stem":"지구에서 볼 수 있는 모습끼리만 묶은 것은 무엇인가요?","options":[{"t":"폭포, 빙하, 갯벌","correct":true},{"t":"폭포, 달의 구덩이, 사막","mis":"SC3-2-u2-X01"},{"t":"우주의 별, 바다, 들판","mis":"SC3-2-u2-X01"},{"t":"달 표면, 빙하, 호수","mis":"SC3-2-u2-X01"}],"explanation":["하나씩 따져요.","달은 지구 밖이에요.","폭포, 빙하, 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#5','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C1',3,'mc','auto','진흙이 펼쳐진 갯벌에서 볼 수 있는 생물은 무엇인가요?',ARRAY['SC3-2-u2-X02']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C1","difficulty":3,"kind":"mc","stem":"진흙이 펼쳐진 갯벌에서 볼 수 있는 생물은 무엇인가요?","options":[{"t":"게와 짱뚱어","correct":true},{"t":"북극곰","mis":"SC3-2-u2-X02"},{"t":"낙타","mis":"SC3-2-u2-X02"},{"t":"펭귄","mis":"SC3-2-u2-X02"}],"explanation":["진흙 땅을 떠올려요.","작은 생물이에요.","게와 짱뚱어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#6','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C2',3,'match','auto','찾은 다른 그림과 찾은 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C2","difficulty":3,"kind":"match","stem":"찾은 다른 그림과 찾은 곳을 알맞게 이으세요.","pairs":[{"l":"파도가 치는 모습","r":"모래사장 쪽"},{"l":"강 위의 돌","r":"강 쪽"},{"l":"모래 언덕의 모습","r":"사막 쪽"}],"mis":"SC3-2-u2-X03","explanation":["찾은 곳을 함께 말해요.","파도는 모래사장이에요.","돌은 강, 모래 언덕은 사막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#7','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C2',3,'mc','auto','「(나)에만 있는 것인가요?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X03']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C2","difficulty":3,"kind":"mc","stem":"「(나)에만 있는 것인가요?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"호수, 모래사장 뒤의 산, 갯벌","correct":true},{"t":"강 위의 돌, 호수, 갯벌","mis":"SC3-2-u2-X03"},{"t":"파도가 치는 모습, 산, 호수","mis":"SC3-2-u2-X03"},{"t":"강 위의 돌, 파도가 치는 모습","mis":"SC3-2-u2-X03"}],"explanation":["(나) 쪽만 봐요.","돌과 파도는 (가)예요.","호수, 산, 갯벌이에요."],"asset":{"type":"passage","lines":["강 — (가) 강 위에 돌이 있어요. (나) 강 위에 돌이 없어요.","호수 — (가) 호수가 없어요. (나) 호수가 있어요.","모래사장 — (가) 파도가 쳐요. (나) 진흙이 펼쳐진 갯벌이 보여요.","모래사장 뒤 — (가) 산이 없어요. (나) 산이 있어요."],"title":"두 그림 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#8','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C2',4,'mc','auto','친구에게 다른 그림을 알려 주는 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C2","difficulty":4,"kind":"mc","stem":"친구에게 다른 그림을 알려 주는 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「모래사장 쪽을 봐. (가)는 파도가 치는데 (나)는 갯벌이 보여.」","correct":true},{"t":"「나 벌써 다 찾았다! 내가 일등이야.」","mis":"SC3-2-u2-X04"},{"t":"「여기!」 하고 정답만 가리킨다","mis":"SC3-2-u2-X04"},{"t":"「알려 주면 재미없으니 비밀이야.」","mis":"SC3-2-u2-X04"}],"explanation":["찾은 곳을 말해요.","무엇이 다른지도 말해요.","모래사장 쪽 설명이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#9','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C1',4,'mc','auto','「오늘은 지구에서 볼 수 있는 모습만 떠올려요.」 이 약속에 맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X01','SC3-2-u2-X02']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C1","difficulty":4,"kind":"mc","stem":"「오늘은 지구에서 볼 수 있는 모습만 떠올려요.」 이 약속에 맞게 말한 것은 무엇인가요?","options":[{"t":"「북극의 빙하와 고래가 사는 바다가 떠올라.」","correct":true},{"t":"「달 표면의 구덩이가 떠올라.」","mis":"SC3-2-u2-X01"},{"t":"「지구에는 바다 한 가지 모습만 있어.」","mis":"SC3-2-u2-X01"},{"t":"「빙하에서는 게와 짱뚱어가 살아.」","mis":"SC3-2-u2-X02"}],"explanation":["지구의 모습이에요.","장소와 모습도 맞아야 해요.","빙하와 바다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L01_challenge#10','sci',3,2,'u2','L01','g3_2_sci_u2_L01_challenge','lesson_challenge','SC3-2-u2-C2',4,'essay','teacher','두 그림 견주기 기록을 보고 다른 그림 두 가지를 찾은 곳과 함께 쓰고, 친구와 함께 찾을 때 지킬 약속 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C2","difficulty":4,"kind":"essay","stem":"두 그림 견주기 기록을 보고 다른 그림 두 가지를 찾은 곳과 함께 쓰고, 친구와 함께 찾을 때 지킬 약속 한 가지를 쓰세요.","answer_guide":{"answer":"예: 강 쪽에서 (가)에는 강 위에 돌이 있는데 (나)에는 돌이 없다. 모래사장 쪽에서 (가)는 파도가 치는데 (나)는 갯벌이 보인다. 친구와 구역을 나누어 찾고, 찾으면 찾은 곳을 말해 알려 준다.","scoring_points":["다른 그림 두 가지를 썼는가","찾은 곳을 함께 썼는가","함께 찾을 때 지킬 약속을 썼는가"]},"explanation":["기록을 읽어요.","찾은 곳을 함께 써요.","약속을 써요."],"asset":{"type":"passage","lines":["강 — (가) 강 위에 돌이 있어요. (나) 강 위에 돌이 없어요.","호수 — (가) 호수가 없어요. (나) 호수가 있어요.","모래사장 — (가) 파도가 쳐요. (나) 진흙이 펼쳐진 갯벌이 보여요.","모래사장 뒤 — (가) 산이 없어요. (나) 산이 있어요."],"title":"두 그림 견주기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#1','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C4',1,'mc','auto','지구를 둘러싸고 있는 공기를 무엇이라고 하나요?',ARRAY['SC3-2-u2-X08']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C4","difficulty":1,"kind":"mc","stem":"지구를 둘러싸고 있는 공기를 무엇이라고 하나요?","options":[{"t":"대기","correct":true},{"t":"바람","mis":"SC3-2-u2-X08"},{"t":"구름","mis":"SC3-2-u2-X08"},{"t":"바다","mis":"SC3-2-u2-X08"}],"explanation":["지구 주위를 떠올려요.","공기가 둘러싸요.","대기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#2','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',1,'sa','auto','비눗방울 안을 가득 채우고 있는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C3","difficulty":1,"kind":"sa","stem":"비눗방울 안을 가득 채우고 있는 것을 두 글자로 쓰세요.","answer":["공기"],"explanation":["비눗방울이 둥글어요.","속이 비어 있지 않아요.","공기예요."],"mis":"SC3-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#3','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',1,'ox','auto','공기는 눈에 보이지 않지만 우리 주변에 있어요.',ARRAY['SC3-2-u2-X05']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C3","difficulty":1,"kind":"ox","stem":"공기는 눈에 보이지 않지만 우리 주변에 있어요.","answer":"O","reason_options":[{"t":"바람이 불 때, 숨을 쉴 때 공기를 느낄 수 있기 때문에","correct":true},{"t":"눈에 보이지 않는 것은 없는 것이기 때문에","mis":"SC3-2-u2-X05"}],"mis":"SC3-2-u2-X05","explanation":["바람을 떠올려요.","느낄 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#4','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',1,'mc','auto','공기를 느낄 수 있는 경험이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u2-X07']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C3","difficulty":1,"kind":"mc","stem":"공기를 느낄 수 있는 경험이 아닌 것은 무엇인가요?","options":[{"t":"컵에 물이 담겨 있는 것을 본다","correct":true},{"t":"연을 날린다","mis":"SC3-2-u2-X07"},{"t":"바람개비를 돌린다","mis":"SC3-2-u2-X07"},{"t":"부채로 바람을 일으킨다","mis":"SC3-2-u2-X07"}],"explanation":["바람이 부는지 봐요.","공기가 움직이나요?","컵에 담긴 물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#5','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',2,'match','auto','모습과 그렇게 움직이는 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"match","stem":"모습과 그렇게 움직이는 까닭을 알맞게 이으세요.","pairs":[{"l":"연","r":"바람에 하늘 높이 떠요"},{"l":"바람개비","r":"바람에 빙글빙글 돌아요"},{"l":"돛단배","r":"바람을 받아 바다 위를 나아가요"}],"mis":"SC3-2-u2-X07","explanation":["셋 다 바람을 받아요.","돌면 바람개비예요.","뜨면 연, 나아가면 돛단배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#6','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',2,'mc','auto','숨을 쉬거나 불어서 공기를 느끼는 경험은 무엇인가요?',ARRAY['SC3-2-u2-X07']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"mc","stem":"숨을 쉬거나 불어서 공기를 느끼는 경험은 무엇인가요?","options":[{"t":"풍선 불기","correct":true},{"t":"연날리기","mis":"SC3-2-u2-X07"},{"t":"바람개비 돌리기","mis":"SC3-2-u2-X07"},{"t":"돛단배 타기","mis":"SC3-2-u2-X07"}],"explanation":["입으로 해요.","숨을 불어 넣어요.","풍선 불기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#7','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C4',2,'blank','auto','「공기는 눈에 보이지 않지만 (    ) 주위를 둘러싸고 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X08','SC3-2-u2-X06']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C4","difficulty":2,"kind":"blank","stem":"「공기는 눈에 보이지 않지만 (    ) 주위를 둘러싸고 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"지구","correct":true},{"t":"달","mis":"SC3-2-u2-X08"},{"t":"구름","mis":"SC3-2-u2-X08"},{"t":"비행기","mis":"SC3-2-u2-X06"}],"explanation":["대기를 떠올려요.","우리가 사는 곳이에요.","지구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#8','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',2,'ox','auto','공기는 비행기가 나는 높은 하늘에만 있어요.',ARRAY['SC3-2-u2-X06']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"ox","stem":"공기는 비행기가 나는 높은 하늘에만 있어요.","answer":"X","reason_options":[{"t":"공기는 우리 주변 어디에나 있기 때문에","correct":true},{"t":"땅 가까이에는 공기가 없기 때문에","mis":"SC3-2-u2-X06"}],"mis":"SC3-2-u2-X06","explanation":["교실을 떠올려요.","숨을 쉬어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#9','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C4',2,'mc','auto','지구에 대기가 없다면 어떤 일이 일어날까요?',ARRAY['SC3-2-u2-X09']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C4","difficulty":2,"kind":"mc","stem":"지구에 대기가 없다면 어떤 일이 일어날까요?","options":[{"t":"숨을 쉴 수 없다","correct":true},{"t":"아무 변화가 없다","mis":"SC3-2-u2-X09"},{"t":"바람이 더 세게 분다","mis":"SC3-2-u2-X09"},{"t":"연을 더 높이 날릴 수 있다","mis":"SC3-2-u2-X09"}],"explanation":["숨을 쉴 때 무엇이 필요한가요?","공기가 필요해요.","숨을 쉴 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_basic#10','sci',3,2,'u2','L02','g3_2_sci_u2_L02_basic','lesson_basic','SC3-2-u2-C3',3,'mc','auto','공기를 느낄 수 있는 곳을 그린 그림에 붙임딱지를 붙이려고 해요. 가장 알맞게 붙인 것은 무엇인가요?',ARRAY['SC3-2-u2-X06','SC3-2-u2-X05']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C3","difficulty":3,"kind":"mc","stem":"공기를 느낄 수 있는 곳을 그린 그림에 붙임딱지를 붙이려고 해요. 가장 알맞게 붙인 것은 무엇인가요?","options":[{"t":"연, 바람개비, 돛단배뿐 아니라 그림 전체에 붙여도 된다","correct":true},{"t":"바람개비에만 붙인다","mis":"SC3-2-u2-X06"},{"t":"하늘에만 붙인다","mis":"SC3-2-u2-X06"},{"t":"공기는 보이지 않으니 아무 데도 붙이지 않는다","mis":"SC3-2-u2-X05"}],"explanation":["공기는 어디에 있나요?","어디에나 있어요.","그림 전체에 붙여도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#1','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C4',2,'sa','auto','지구를 둘러싸고 있는 공기를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C4","difficulty":2,"kind":"sa","stem":"지구를 둘러싸고 있는 공기를 두 글자로 쓰세요.","answer":["대기"],"explanation":["지구 주위의 공기예요.","대◯예요.","대기예요."],"mis":"SC3-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#2','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C3',2,'mc','auto','바람을 받아 움직이는 것은 무엇인가요?',ARRAY['SC3-2-u2-X07']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"mc","stem":"바람을 받아 움직이는 것은 무엇인가요?","options":[{"t":"돛단배","correct":true},{"t":"숨 쉬기","mis":"SC3-2-u2-X07"},{"t":"풍선 불기","mis":"SC3-2-u2-X07"},{"t":"컵에 담긴 물","mis":"SC3-2-u2-X07"}],"explanation":["바람을 떠올려요.","돛이 바람을 받아요.","돛단배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#3','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C3',3,'error','auto','공기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X05','SC3-2-u2-X07','SC3-2-u2-X06']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C3","difficulty":3,"kind":"error","stem":"공기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「비눗방울 안은 텅 비어 있어.」","correct":true,"mis_target":"SC3-2-u2-X05"},{"t":"친구 가 — 「연이 하늘 높이 뜨는 것은 바람 때문이야.」","mis":"SC3-2-u2-X07"},{"t":"친구 다 — 「숨을 쉴 때도 공기를 느낄 수 있어.」","mis":"SC3-2-u2-X06"}],"explanation":["비눗방울 안을 떠올려요.","공기가 채우고 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#4','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C3',3,'mc','auto','공기를 느낀 경험에서 바람을 받아 움직인 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X07']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C3","difficulty":3,"kind":"mc","stem":"공기를 느낀 경험에서 바람을 받아 움직인 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉡, ㉣","mis":"SC3-2-u2-X07"},{"t":"㉠, ㉡","mis":"SC3-2-u2-X07"},{"t":"㉢, ㉣","mis":"SC3-2-u2-X07"}],"explanation":["바람개비와 돛단배를 봐요.","풍선과 손바닥은 숨이에요.","㉠, ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 바람개비가 빙글빙글 돌았어요.","㉡ 풍선을 불어 크게 만들었어요.","㉢ 돛단배가 바다 위를 나아갔어요.","㉣ 손바닥에 입으로 바람을 불었어요."],"title":"공기를 느낀 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#5','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C4',3,'mc','auto','「대기」를 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u2-X08']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C4","difficulty":3,"kind":"mc","stem":"「대기」를 바르게 설명한 것은 무엇인가요?","options":[{"t":"지구를 둘러싸고 있는 공기","correct":true},{"t":"하늘에 떠 있는 구름","mis":"SC3-2-u2-X08"},{"t":"지구를 덮고 있는 바닷물","mis":"SC3-2-u2-X08"},{"t":"지구 밖의 우주","mis":"SC3-2-u2-X08"}],"explanation":["공기예요.","지구를 둘러싸요.","지구를 둘러싼 공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#6','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C3',3,'match','auto','공기를 느낀 경험과 느낀 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C3","difficulty":3,"kind":"match","stem":"공기를 느낀 경험과 느낀 방법을 알맞게 이으세요.","pairs":[{"l":"연날리기","r":"바람을 받아 움직여요"},{"l":"숨 쉬기","r":"숨으로 느껴요"},{"l":"부채질","r":"부채로 바람을 일으켜요"}],"mis":"SC3-2-u2-X07","explanation":["바람을 받는 것을 찾아요.","숨은 내가 쉬어요.","부채는 바람을 일으켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#7','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C3',3,'mc','auto','눈을 감고 부채로 얼굴에 바람을 일으켰더니 시원했어요. 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X06','SC3-2-u2-X05']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C3","difficulty":3,"kind":"mc","stem":"눈을 감고 부채로 얼굴에 바람을 일으켰더니 시원했어요. 알 수 있는 것은 무엇인가요?","options":[{"t":"공기는 눈에 보이지 않지만 느낄 수 있다","correct":true},{"t":"부채 가까이에만 공기가 있다","mis":"SC3-2-u2-X06"},{"t":"공기는 보여야만 느낄 수 있다","mis":"SC3-2-u2-X05"},{"t":"눈을 감으면 공기가 없어진다","mis":"SC3-2-u2-X05"}],"explanation":["눈을 감았어요.","그래도 시원해요.","보이지 않아도 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#8','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C3',4,'mc','auto','공기를 느낀 경험 ㉠~㉣을 모두 설명할 수 있는 말은 무엇인가요?',ARRAY['SC3-2-u2-X06','SC3-2-u2-X05']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C3","difficulty":4,"kind":"mc","stem":"공기를 느낀 경험 ㉠~㉣을 모두 설명할 수 있는 말은 무엇인가요?","options":[{"t":"공기는 눈에 보이지 않지만 우리 주변 어디에나 있다","correct":true},{"t":"공기는 바람이 부는 바닷가에만 있다","mis":"SC3-2-u2-X06"},{"t":"공기는 풍선 속에만 있다","mis":"SC3-2-u2-X06"},{"t":"공기는 보이지 않으니 없는 것과 같다","mis":"SC3-2-u2-X05"}],"explanation":["넷 다 공기를 느꼈어요.","장소가 달라요.","어디에나 있어요."],"asset":{"type":"passage","lines":["㉠ 바람개비가 빙글빙글 돌았어요.","㉡ 풍선을 불어 크게 만들었어요.","㉢ 돛단배가 바다 위를 나아갔어요.","㉣ 손바닥에 입으로 바람을 불었어요."],"title":"공기를 느낀 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#9','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C4',4,'mc','auto','「공기가 지구를 둘러싸고 있어서 우리가 숨을 쉴 수 있어.」 이 말과 가장 관계있는 낱말은 무엇인가요?',ARRAY['SC3-2-u2-X08','SC3-2-u2-X07','SC3-2-u2-X05']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C4","difficulty":4,"kind":"mc","stem":"「공기가 지구를 둘러싸고 있어서 우리가 숨을 쉴 수 있어.」 이 말과 가장 관계있는 낱말은 무엇인가요?","options":[{"t":"대기","correct":true},{"t":"구름","mis":"SC3-2-u2-X08"},{"t":"바람개비","mis":"SC3-2-u2-X07"},{"t":"비눗방울","mis":"SC3-2-u2-X05"}],"explanation":["지구를 둘러싼 공기예요.","숨과 이어져요.","대기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L02_challenge#10','sci',3,2,'u2','L02','g3_2_sci_u2_L02_challenge','lesson_challenge','SC3-2-u2-C4',4,'essay','teacher','우리 주변에서 공기를 느낄 수 있는 경험 두 가지를 쓰고, 이 경험으로 알 수 있는 공기의 특징과 「대기」의 뜻을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C4","difficulty":4,"kind":"essay","stem":"우리 주변에서 공기를 느낄 수 있는 경험 두 가지를 쓰고, 이 경험으로 알 수 있는 공기의 특징과 「대기」의 뜻을 쓰세요.","answer_guide":{"answer":"예: 바람개비가 바람에 빙글빙글 돌 때, 풍선을 불어 부풀릴 때 공기를 느낄 수 있다. 공기는 눈에 보이지 않지만 우리 주변 어디에나 있다. 지구를 둘러싸고 있는 공기를 대기라고 한다.","scoring_points":["공기를 느낀 경험 두 가지를 썼는가","공기는 보이지 않지만 주변에 있음을 썼는가","대기의 뜻을 바르게 썼는가"]},"explanation":["경험을 떠올려요.","공기의 특징을 써요.","대기의 뜻을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#1','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C5',1,'mc','auto','땅으로 이루어진 곳을 무엇이라고 하나요?',ARRAY['SC3-2-u2-X10','SC3-2-u2-X08','SC3-2-u2-X14']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C5","difficulty":1,"kind":"mc","stem":"땅으로 이루어진 곳을 무엇이라고 하나요?","options":[{"t":"육지","correct":true},{"t":"바다","mis":"SC3-2-u2-X10"},{"t":"대기","mis":"SC3-2-u2-X08"},{"t":"호수","mis":"SC3-2-u2-X14"}],"explanation":["땅을 떠올려요.","산과 들이 있어요.","육지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#2','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C5',1,'sa','auto','물로 덮여 있는 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C5","difficulty":1,"kind":"sa","stem":"물로 덮여 있는 곳을 두 글자로 쓰세요.","answer":["바다"],"explanation":["물로 덮여 있어요.","고래가 살아요.","바다예요."],"mis":"SC3-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#3','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C6',1,'ox','auto','지구 표면에서 바다는 육지보다 넓어요.',ARRAY['SC3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C6","difficulty":1,"kind":"ox","stem":"지구 표면에서 바다는 육지보다 넓어요.","answer":"O","reason_options":[{"t":"지구본에 바다 붙임쪽지를 더 많이 붙였기 때문에","correct":true},{"t":"육지에 산, 들, 사막처럼 모습이 더 많기 때문에","mis":"SC3-2-u2-X11"}],"mis":"SC3-2-u2-X11","explanation":["붙임쪽지를 떠올려요.","바다가 더 많았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
