INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#5','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C5',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C5","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"육지","r":"땅으로 이루어진 곳"},{"l":"바다","r":"물로 덮여 있는 곳"},{"l":"대기","r":"지구를 둘러싼 공기"}],"mis":"SC3-2-u2-X10","explanation":["땅과 물로 나눠요.","대기는 공기예요.","육지-땅, 바다-물, 대기-공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#6','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C6',2,'mc','auto','지구본에 붙임쪽지를 붙일 때, 한 칸에 육지가 절반이 넘으면 어떻게 하나요?',ARRAY['SC3-2-u2-X12']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C6","difficulty":2,"kind":"mc","stem":"지구본에 붙임쪽지를 붙일 때, 한 칸에 육지가 절반이 넘으면 어떻게 하나요?","options":[{"t":"육지 붙임쪽지를 붙인다","correct":true},{"t":"바다 붙임쪽지를 붙인다","mis":"SC3-2-u2-X12"},{"t":"두 장을 겹쳐 붙인다","mis":"SC3-2-u2-X12"},{"t":"아무것도 붙이지 않는다","mis":"SC3-2-u2-X12"}],"explanation":["더 많이 차지한 쪽이에요.","육지가 절반이 넘어요.","육지 붙임쪽지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#7','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C5',2,'mc','auto','육지에서 볼 수 있는 모습끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X10']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C5","difficulty":2,"kind":"mc","stem":"육지에서 볼 수 있는 모습끼리 묶은 것은 무엇인가요?","options":[{"t":"산, 들, 사막","correct":true},{"t":"산, 바다, 들","mis":"SC3-2-u2-X10"},{"t":"바다, 강, 계곡","mis":"SC3-2-u2-X10"},{"t":"사막, 바다, 빙하","mis":"SC3-2-u2-X10"}],"explanation":["땅에 있는 것을 찾아요.","바다는 빼요.","산, 들, 사막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
