INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_basic#10','sci',3,2,'u2','L03','g3_2_sci_u2_L03_basic','lesson_basic','SC3-2-u2-C6',3,'mc','auto','지구본 붙임쪽지 결과에서 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X12','SC3-2-u2-X13']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C6","difficulty":3,"kind":"mc","stem":"지구본 붙임쪽지 결과에서 알 수 있는 것은 무엇인가요?","options":[{"t":"두 모둠 모두 바다 붙임쪽지가 더 많으니 바다가 육지보다 넓다","correct":true},{"t":"두 모둠의 개수가 다르니 실험을 잘못했다","mis":"SC3-2-u2-X12"},{"t":"육지 붙임쪽지가 적으니 육지가 더 넓다","mis":"SC3-2-u2-X13"},{"t":"붙임쪽지 개수로는 아무것도 알 수 없다","mis":"SC3-2-u2-X13"}],"explanation":["두 모둠을 다 봐요.","바다가 더 많아요.","바다가 넓어요."],"asset":{"type":"passage","lines":["모둠 가 — 육지 붙임쪽지 18장 · 바다 붙임쪽지 52장","모둠 나 — 육지 붙임쪽지 23장 · 바다 붙임쪽지 47장"],"title":"지구본 붙임쪽지 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
