INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#3','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C6',3,'error','auto','붙임쪽지 활동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X12']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C6","difficulty":3,"kind":"error","stem":"붙임쪽지 활동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우리 모둠 개수가 옆 모둠과 다르니 잘못한 거야.」","correct":true,"mis_target":"SC3-2-u2-X12"},{"t":"친구 가 — 「붙임쪽지는 겹치지 않게 붙여.」","mis":"SC3-2-u2-X12"},{"t":"친구 나 — 「바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙여.」","mis":"SC3-2-u2-X12"}],"explanation":["개수는 모둠마다 달라요.","결과는 같아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
