INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#5','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C7',3,'mc','auto','육지의 물을 찾을 수 있는 곳끼리만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X14']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C7","difficulty":3,"kind":"mc","stem":"육지의 물을 찾을 수 있는 곳끼리만 묶은 것은 무엇인가요?","options":[{"t":"강, 호수, 계곡, 빙하","correct":true},{"t":"강, 바다, 호수","mis":"SC3-2-u2-X14"},{"t":"바다, 계곡","mis":"SC3-2-u2-X14"},{"t":"사막, 들, 산","mis":"SC3-2-u2-X14"}],"explanation":["육지에 있는 물이에요.","바다는 빼요.","강, 호수, 계곡, 빙하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#6','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C5',3,'match','auto','지구 표면의 모습과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C5","difficulty":3,"kind":"match","stem":"지구 표면의 모습과 알맞은 설명을 이으세요.","pairs":[{"l":"사막","r":"육지에서 볼 수 있어요"},{"l":"물로 덮여 있는 곳","r":"바다예요"},{"l":"계곡","r":"육지의 물을 찾을 수 있어요"}],"mis":"SC3-2-u2-X10","explanation":["사막은 땅이에요.","물로 덮인 곳은 바다예요.","계곡에는 물이 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#7','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C6',3,'mc','auto','지구본 한 칸에 바다가 절반이 넘고 육지가 조금 있어요. 어떻게 붙여야 하나요?',ARRAY['SC3-2-u2-X12']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C6","difficulty":3,"kind":"mc","stem":"지구본 한 칸에 바다가 절반이 넘고 육지가 조금 있어요. 어떻게 붙여야 하나요?","options":[{"t":"바다 붙임쪽지를 한 장 붙인다","correct":true},{"t":"육지 붙임쪽지를 한 장 붙인다","mis":"SC3-2-u2-X12"},{"t":"육지와 바다 붙임쪽지를 겹쳐 붙인다","mis":"SC3-2-u2-X12"},{"t":"육지가 조금이라도 있으니 붙이지 않는다","mis":"SC3-2-u2-X12"}],"explanation":["더 많이 차지한 쪽이에요.","바다가 절반이 넘어요.","바다 붙임쪽지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#8','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C5',4,'mc','auto','우주에서 본 지구가 파란색, 갈색, 초록색, 하얀색 등 여러 가지 색으로 보이는 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X01','SC3-2-u2-X10']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C5","difficulty":4,"kind":"mc","stem":"우주에서 본 지구가 파란색, 갈색, 초록색, 하얀색 등 여러 가지 색으로 보이는 까닭은 무엇인가요?","options":[{"t":"지구 표면에 바다, 사막, 들, 빙하 등 다양한 모습이 있기 때문에","correct":true},{"t":"지구에 물감을 칠했기 때문에","mis":"SC3-2-u2-X01"},{"t":"햇빛의 색이 자꾸 바뀌기 때문에","mis":"SC3-2-u2-X01"},{"t":"바닷물의 색이 곳마다 모두 다르기 때문에","mis":"SC3-2-u2-X10"}],"explanation":["지구 표면을 떠올려요.","모습이 여러 가지예요.","다양한 모습 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#9','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C6',4,'mc','auto','지구본 붙임쪽지 결과를 보고 육지와 바다의 넓이를 바르게 견준 말은 무엇인가요?',ARRAY['SC3-2-u2-X13','SC3-2-u2-X12']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C6","difficulty":4,"kind":"mc","stem":"지구본 붙임쪽지 결과를 보고 육지와 바다의 넓이를 바르게 견준 말은 무엇인가요?","options":[{"t":"「두 모둠 모두 바다 쪽이 훨씬 많아. 바다가 육지보다 넓어.」","correct":true},{"t":"「모둠 나는 육지가 더 많으니 육지가 넓어.」","mis":"SC3-2-u2-X13"},{"t":"「개수가 모둠마다 다르니 알 수 없어.」","mis":"SC3-2-u2-X12"},{"t":"「모둠 가만 바르게 붙였어.」","mis":"SC3-2-u2-X12"}],"explanation":["두 모둠을 다 읽어요.","바다가 더 많아요.","바다가 넓어요."],"asset":{"type":"passage","lines":["모둠 가 — 육지 붙임쪽지 18장 · 바다 붙임쪽지 52장","모둠 나 — 육지 붙임쪽지 23장 · 바다 붙임쪽지 47장"],"title":"지구본 붙임쪽지 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L03_challenge#10','sci',3,2,'u2','L03','g3_2_sci_u2_L03_challenge','lesson_challenge','SC3-2-u2-C6',4,'essay','teacher','지구본 붙임쪽지 결과를 보고 지구 표면의 육지와 바다 넓이를 견주어 쓰고, 두 모둠의 개수가 달라도 괜찮은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C6","difficulty":4,"kind":"essay","stem":"지구본 붙임쪽지 결과를 보고 지구 표면의 육지와 바다 넓이를 견주어 쓰고, 두 모둠의 개수가 달라도 괜찮은 까닭을 쓰세요.","answer_guide":{"answer":"예: 두 모둠 모두 바다 붙임쪽지가 육지 붙임쪽지보다 많으므로 지구 표면에서 바다가 육지보다 넓다. 칸을 나누고 붙이는 방법이 모둠마다 조금씩 달라 개수는 달라질 수 있지만, 바다가 더 많다는 결과는 같다.","scoring_points":["바다가 육지보다 넓다고 썼는가","붙임쪽지 개수를 근거로 들었는가","개수가 달라도 괜찮은 까닭을 썼는가"]},"explanation":["결과를 읽어요.","넓이를 견줘요.","까닭을 써요."],"asset":{"type":"passage","lines":["모둠 가 — 육지 붙임쪽지 18장 · 바다 붙임쪽지 52장","모둠 나 — 육지 붙임쪽지 23장 · 바다 붙임쪽지 47장"],"title":"지구본 붙임쪽지 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#1','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C9',1,'mc','auto','바닷물에서 짠맛이 나는 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X20']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C9","difficulty":1,"kind":"mc","stem":"바닷물에서 짠맛이 나는 까닭은 무엇인가요?","options":[{"t":"소금이 녹아 있어서","correct":true},{"t":"설탕이 녹아 있어서","mis":"SC3-2-u2-X20"},{"t":"모래가 섞여 있어서","mis":"SC3-2-u2-X20"},{"t":"흙이 가라앉아 있어서","mis":"SC3-2-u2-X20"}],"explanation":["남은 하얀 물질을 떠올려요.","대부분 소금이에요.","소금이 녹아 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#2','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C8',1,'sa','auto','물이 갑자기 끓어오르지 않도록 넣는 작은 돌이나 유리 조각을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C8","difficulty":1,"kind":"sa","stem":"물이 갑자기 끓어오르지 않도록 넣는 작은 돌이나 유리 조각을 세 글자로 쓰세요.","answer":["끓임쪽"],"explanation":["증발 접시에 넣어요.","끓◯◯이에요.","끓임쪽이에요."],"mis":"SC3-2-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#3','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C8',1,'ox','auto','두 물을 구별하려고 실험 재료를 맛보아도 돼요.',ARRAY['SC3-2-u2-X16']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C8","difficulty":1,"kind":"ox","stem":"두 물을 구별하려고 실험 재료를 맛보아도 돼요.","answer":"X","reason_options":[{"t":"실험 재료는 맛보지 않는 것이 안전 약속이기 때문에","correct":true},{"t":"맛을 보면 가장 빨리 구별할 수 있기 때문에","mis":"SC3-2-u2-X16"}],"mis":"SC3-2-u2-X16","explanation":["안전 약속을 떠올려요.","맛보지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#4','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C9',1,'mc','auto','바닷물을 가열했을 때 증발 접시에 남은 물질의 색깔은 무엇인가요?',ARRAY['SC3-2-u2-X19']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C9","difficulty":1,"kind":"mc","stem":"바닷물을 가열했을 때 증발 접시에 남은 물질의 색깔은 무엇인가요?","options":[{"t":"하얀색","correct":true},{"t":"검은색","mis":"SC3-2-u2-X19"},{"t":"파란색","mis":"SC3-2-u2-X19"},{"t":"빨간색","mis":"SC3-2-u2-X19"}],"explanation":["남은 물질을 떠올려요.","소금 같아요.","하얀색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#5','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C9',2,'match','auto','남은 물질을 관찰한 방법과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"match","stem":"남은 물질을 관찰한 방법과 결과를 알맞게 이으세요.","pairs":[{"l":"눈으로 본 색깔","r":"하얀색이에요"},{"l":"손으로 만진 느낌","r":"거칠거칠해요"},{"l":"코로 맡은 냄새","r":"아무 냄새가 나지 않아요"}],"mis":"SC3-2-u2-X19","explanation":["눈, 손, 코로 나눠요.","색깔은 하얀색이에요.","느낌은 거칠거칠, 냄새는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#6','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C8',2,'mc','auto','가열 실험에서 안전한 행동은 무엇인가요?',ARRAY['SC3-2-u2-X16']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C8","difficulty":2,"kind":"mc","stem":"가열 실험에서 안전한 행동은 무엇인가요?","options":[{"t":"보안경과 면장갑을 쓰고 가열한다","correct":true},{"t":"증발 접시를 맨손으로 옮긴다","mis":"SC3-2-u2-X16"},{"t":"전원을 끄자마자 핫플레이트를 만진다","mis":"SC3-2-u2-X16"},{"t":"끓는 증발 접시에 얼굴을 가까이 댄다","mis":"SC3-2-u2-X16"}],"explanation":["안전 약속을 떠올려요.","눈과 손을 지켜요.","보안경과 면장갑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#7','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C9',2,'mc','auto','육지의 물을 증발 접시에 담아 물이 없어질 때까지 가열하면 어떻게 되나요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X17']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"mc","stem":"육지의 물을 증발 접시에 담아 물이 없어질 때까지 가열하면 어떻게 되나요?","options":[{"t":"남는 물질이 없다","correct":true},{"t":"하얀 소금이 많이 남는다","mis":"SC3-2-u2-X18"},{"t":"검은 모래가 남는다","mis":"SC3-2-u2-X18"},{"t":"물이 줄지 않는다","mis":"SC3-2-u2-X17"}],"explanation":["육지의 물 접시를 떠올려요.","아무것도 없어요.","남는 물질이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#8','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C9',2,'blank','auto','「바닷물을 가열하고 남는 물질의 대부분은 (    )이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X20','SC3-2-u2-X19']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"blank","stem":"「바닷물을 가열하고 남는 물질의 대부분은 (    )이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"소금","correct":true},{"t":"설탕","mis":"SC3-2-u2-X20"},{"t":"모래","mis":"SC3-2-u2-X20"},{"t":"밀가루","mis":"SC3-2-u2-X19"}],"explanation":["짠맛을 떠올려요.","하얀 물질이에요.","소금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#9','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C9',2,'ox','auto','바닷물은 농사를 짓는 데 그대로 쓸 수 있어요.',ARRAY['SC3-2-u2-X21']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"ox","stem":"바닷물은 농사를 짓는 데 그대로 쓸 수 있어요.","answer":"X","reason_options":[{"t":"바닷물에는 소금이 많이 녹아 있기 때문에","correct":true},{"t":"바닷물은 육지의 물보다 많기 때문에","mis":"SC3-2-u2-X21"}],"mis":"SC3-2-u2-X21","explanation":["바닷물에 녹아 있는 것을 떠올려요.","소금이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_basic#10','sci',3,2,'u2','L04','g3_2_sci_u2_L04_basic','lesson_basic','SC3-2-u2-C8',3,'mc','auto','육지의 물과 바닷물을 가열해 견줄 때 꼭 지켜야 할 것은 무엇인가요?',ARRAY['SC3-2-u2-X17','SC3-2-u2-X16']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C8","difficulty":3,"kind":"mc","stem":"육지의 물과 바닷물을 가열해 견줄 때 꼭 지켜야 할 것은 무엇인가요?","options":[{"t":"두 증발 접시에 같은 양의 물을 담아 같은 방법으로 가열한다","correct":true},{"t":"바닷물만 가열하고 육지의 물은 그냥 둔다","mis":"SC3-2-u2-X17"},{"t":"한 접시에만 끓임쪽을 넣는다","mis":"SC3-2-u2-X17"},{"t":"맛을 보고 나서 가열한다","mis":"SC3-2-u2-X16"}],"explanation":["두 물을 견줘요.","똑같이 해야 해요.","같은 양, 같은 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#1','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C9',2,'sa','auto','바닷물을 가열하고 남은 물질의 대부분은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"sa","stem":"바닷물을 가열하고 남은 물질의 대부분은 무엇인가요? 두 글자로 쓰세요.","answer":["소금"],"explanation":["짠맛이 나요.","하얀 물질이에요.","소금이에요."],"mis":"SC3-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#2','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C8',2,'mc','auto','가열한 증발 접시를 옮길 때 쓰는 것은 무엇인가요?',ARRAY['SC3-2-u2-X16']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C8","difficulty":2,"kind":"mc","stem":"가열한 증발 접시를 옮길 때 쓰는 것은 무엇인가요?","options":[{"t":"증발 접시 집게","correct":true},{"t":"맨손","mis":"SC3-2-u2-X16"},{"t":"휴지 한 장","mis":"SC3-2-u2-X16"},{"t":"종이컵","mis":"SC3-2-u2-X16"}],"explanation":["접시가 뜨거워요.","손으로 잡지 않아요.","집게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#3','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C9',3,'mc','auto','두 물 가열 실험 기록에서 바닷물을 가열한 접시와 그렇게 생각한 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X17']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"mc","stem":"두 물 가열 실험 기록에서 바닷물을 가열한 접시와 그렇게 생각한 까닭은 무엇인가요?","options":[{"t":"접시 ㉡ — 하얀 물질이 남았기 때문에","correct":true},{"t":"접시 ㉠ — 남은 물질이 없기 때문에","mis":"SC3-2-u2-X18"},{"t":"접시 ㉡ — 물이 없어졌기 때문에","mis":"SC3-2-u2-X17"},{"t":"두 접시 모두 — 둘 다 물이 없어졌기 때문에","mis":"SC3-2-u2-X18"}],"explanation":["남은 물질을 봐요.","㉡에 하얀 물질이 있어요.","㉡이 바닷물이에요."],"asset":{"type":"passage","lines":["접시 ㉠ — 물이 없어질 때까지 가열했더니 남은 물질이 없어요.","접시 ㉡ — 물이 없어질 때까지 가열했더니 하얀 물질이 남았어요.","㉡에 남은 물질 — 거칠거칠하고 아무 냄새가 나지 않아요."],"title":"두 물 가열 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#4','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C9',3,'error','auto','두 물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X17','SC3-2-u2-X21']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"error","stem":"두 물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「육지의 물을 가열해도 소금이 남아.」","correct":true,"mis_target":"SC3-2-u2-X18"},{"t":"친구 나 — 「가열하면 두 물 모두 끓어.」","mis":"SC3-2-u2-X17"},{"t":"친구 다 — 「바닷물은 사람이 마시기에 알맞지 않아.」","mis":"SC3-2-u2-X21"}],"explanation":["육지의 물 접시를 떠올려요.","남은 것이 없어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#5','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C9',3,'mc','auto','「두 물 모두에 해당하나요?」로 나누었을 때 ⭕ 쪽에 들어가는 것은 무엇인가요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X21']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"mc","stem":"「두 물 모두에 해당하나요?」로 나누었을 때 ⭕ 쪽에 들어가는 것은 무엇인가요?","options":[{"t":"계속 가열하면 물이 없어진다","correct":true},{"t":"가열하면 하얀 물질이 남는다","mis":"SC3-2-u2-X18"},{"t":"소금 때문에 짠맛이 난다","mis":"SC3-2-u2-X18"},{"t":"사람이 마시기에 알맞지 않다","mis":"SC3-2-u2-X21"}],"explanation":["두 물에 모두 일어나는 일이에요.","셋은 바닷물만이에요.","물이 없어지는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#6','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C8',3,'match','auto','실험 약속과 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C8","difficulty":3,"kind":"match","stem":"실험 약속과 그 까닭을 알맞게 이으세요.","pairs":[{"l":"보안경을 써요","r":"물질이 튀어도 눈을 지켜요"},{"l":"증발 접시를 집게로 옮겨요","r":"뜨거운 접시에 데지 않아요"},{"l":"끓임쪽을 넣어요","r":"물이 갑자기 끓어오르지 않아요"}],"mis":"SC3-2-u2-X16","explanation":["약속마다 까닭이 있어요.","집게는 뜨거워서예요.","끓임쪽은 갑자기 끓지 않게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#7','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C9',3,'mc','auto','농사를 지을 때 바닷물 대신 육지의 물을 써야 하는 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X20','SC3-2-u2-X21']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"mc","stem":"농사를 지을 때 바닷물 대신 육지의 물을 써야 하는 까닭은 무엇인가요?","options":[{"t":"바닷물에는 소금이 많이 녹아 있기 때문에","correct":true},{"t":"바닷물은 색깔이 파랗기 때문에","mis":"SC3-2-u2-X20"},{"t":"바닷물에는 모래만 들어 있기 때문에","mis":"SC3-2-u2-X20"},{"t":"바닷물을 써도 괜찮지만 멀어서","mis":"SC3-2-u2-X21"}],"explanation":["바닷물에 녹아 있는 것이에요.","소금이 많아요.","그래서 육지의 물을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#8','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C7',4,'mc','auto','지구의 물에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X15','SC3-2-u2-X21']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C7","difficulty":4,"kind":"mc","stem":"지구의 물에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"지구의 물은 대부분 바닷물이라, 우리가 쓸 수 있는 육지의 물은 적어 아껴 써야 한다","correct":true},{"t":"지구의 물은 대부분 육지의 물이다","mis":"SC3-2-u2-X15"},{"t":"바닷물을 그대로 마시면 되니 물을 아낄 필요가 없다","mis":"SC3-2-u2-X21"},{"t":"육지의 물이 바닷물보다 훨씬 많다","mis":"SC3-2-u2-X15"}],"explanation":["지구의 물은 대부분 무엇인가요?","바닷물이에요.","육지의 물은 아껴 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#9','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C8',4,'mc','auto','두 물을 마시지 않고 구별하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X16','SC3-2-u2-X17']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C8","difficulty":4,"kind":"mc","stem":"두 물을 마시지 않고 구별하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"두 물을 같은 양씩 증발 접시에 담아 가열하고 남는 물질이 있는지 견준다","correct":true},{"t":"두 물을 조금씩 맛본다","mis":"SC3-2-u2-X16"},{"t":"두 물의 색깔만 눈으로 본다","mis":"SC3-2-u2-X17"},{"t":"한 물만 가열해 본다","mis":"SC3-2-u2-X17"}],"explanation":["맛보지 않아요.","가열해요.","남는 물질을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L04_challenge#10','sci',3,2,'u2','L04','g3_2_sci_u2_L04_challenge','lesson_challenge','SC3-2-u2-C9',4,'essay','teacher','두 물 가열 실험 기록을 보고 어느 접시가 바닷물인지 쓰고, 그 까닭과 바닷물의 특징을 육지의 물과 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C9","difficulty":4,"kind":"essay","stem":"두 물 가열 실험 기록을 보고 어느 접시가 바닷물인지 쓰고, 그 까닭과 바닷물의 특징을 육지의 물과 견주어 쓰세요.","answer_guide":{"answer":"예: 접시 ㉡이 바닷물이다. 바닷물을 가열하면 육지의 물과 달리 하얗고 거칠거칠한 물질이 남는데, 그 대부분은 소금이기 때문이다. 바닷물은 소금이 녹아 있어 짠맛이 나고 사람이 마시거나 농사를 짓는 데 쓰기에 알맞지 않다.","scoring_points":["바닷물인 접시를 바르게 골랐는가","남은 물질을 근거로 들었는가","바닷물의 특징을 육지의 물과 견주어 썼는가"]},"explanation":["접시를 골라요.","남은 물질을 근거로 들어요.","두 물을 견줘요."],"asset":{"type":"passage","lines":["접시 ㉠ — 물이 없어질 때까지 가열했더니 남은 물질이 없어요.","접시 ㉡ — 물이 없어질 때까지 가열했더니 하얀 물질이 남았어요.","㉡에 남은 물질 — 거칠거칠하고 아무 냄새가 나지 않아요."],"title":"두 물 가열 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#1','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',1,'mc','auto','땅의 생김새를 무엇이라고 하나요?',ARRAY['SC3-2-u2-X22']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C10","difficulty":1,"kind":"mc","stem":"땅의 생김새를 무엇이라고 하나요?","options":[{"t":"지형","correct":true},{"t":"날씨","mis":"SC3-2-u2-X22"},{"t":"대기","mis":"SC3-2-u2-X22"},{"t":"바닷물","mis":"SC3-2-u2-X22"}],"explanation":["절벽, 동굴을 떠올려요.","땅이 생긴 모습이에요.","지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#2','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',1,'sa','auto','바위에 구멍이 뚫려 있고 그곳으로 물이 지나가는 지형을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C10","difficulty":1,"kind":"sa","stem":"바위에 구멍이 뚫려 있고 그곳으로 물이 지나가는 지형을 두 글자로 쓰세요.","answer":["동굴"],"explanation":["바위에 구멍이 있어요.","물이 지나가요.","동굴이에요."],"mis":"SC3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#3','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',1,'ox','auto','절벽은 가파른 모습의 지형이에요.',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C10","difficulty":1,"kind":"ox","stem":"절벽은 가파른 모습의 지형이에요.","answer":"O","reason_options":[{"t":"바위가 높고 가파르게 서 있기 때문에","correct":true},{"t":"모래가 넓게 펼쳐져 있기 때문에","mis":"SC3-2-u2-X23"}],"mis":"SC3-2-u2-X23","explanation":["절벽을 떠올려요.","높고 가팔라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#4','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',1,'mc','auto','고운 흙이나 모래가 넓게 펼쳐져 있는 지형은 무엇인가요?',ARRAY['SC3-2-u2-X23','SC3-2-u2-X24']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C10","difficulty":1,"kind":"mc","stem":"고운 흙이나 모래가 넓게 펼쳐져 있는 지형은 무엇인가요?","options":[{"t":"모래사장","correct":true},{"t":"절벽","mis":"SC3-2-u2-X23"},{"t":"동굴","mis":"SC3-2-u2-X23"},{"t":"사막","mis":"SC3-2-u2-X24"}],"explanation":["바닷가를 떠올려요.","모래가 펼쳐져 있어요.","모래사장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#5','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',2,'match','auto','지형과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"match","stem":"지형과 특징을 알맞게 이으세요.","pairs":[{"l":"절벽","r":"가파른 모습이에요"},{"l":"모래사장","r":"모래가 넓게 펼쳐져 있어요"},{"l":"갯벌","r":"진흙이 보이고 색이 어두워요"}],"mis":"SC3-2-u2-X23","explanation":["지형 사진을 떠올려요.","가파르면 절벽이에요.","모래는 모래사장, 진흙은 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#6','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C11',2,'mc','auto','「바위로 이루어진 지형인가요?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X25']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C11","difficulty":2,"kind":"mc","stem":"「바위로 이루어진 지형인가요?」로 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"절벽, 동굴","correct":true},{"t":"모래사장, 갯벌","mis":"SC3-2-u2-X25"},{"t":"절벽, 갯벌","mis":"SC3-2-u2-X25"},{"t":"동굴, 모래사장","mis":"SC3-2-u2-X25"}],"explanation":["단단한 바위를 찾아요.","모래와 진흙은 빼요.","절벽, 동굴이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#7','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',2,'mc','auto','바닷가에서 볼 수 있는 지형이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u2-X24']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"mc","stem":"바닷가에서 볼 수 있는 지형이 아닌 것은 무엇인가요?","options":[{"t":"사막","correct":true},{"t":"절벽","mis":"SC3-2-u2-X24"},{"t":"동굴","mis":"SC3-2-u2-X24"},{"t":"갯벌","mis":"SC3-2-u2-X24"}],"explanation":["바닷가를 떠올려요.","하나는 바닷가가 아니에요.","사막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#8','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',2,'blank','auto','「바닷가에서는 절벽, 동굴, 모래사장, (    ) 등 다양한 지형을 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X24']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"blank","stem":"「바닷가에서는 절벽, 동굴, 모래사장, (    ) 등 다양한 지형을 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"갯벌","correct":true},{"t":"사막","mis":"SC3-2-u2-X24"},{"t":"빙하","mis":"SC3-2-u2-X24"},{"t":"들판","mis":"SC3-2-u2-X24"}],"explanation":["바닷가 지형이에요.","진흙이 보여요.","갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#9','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C11',2,'ox','auto','찾은 지형 사진을 나눌 때 친구 사진에 놀리는 댓글을 달아도 돼요.',ARRAY['SC3-2-u2-X26']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C11","difficulty":2,"kind":"ox","stem":"찾은 지형 사진을 나눌 때 친구 사진에 놀리는 댓글을 달아도 돼요.","answer":"X","reason_options":[{"t":"친구의 생각과 사진을 존중해야 하기 때문에","correct":true},{"t":"재미있으면 무엇이든 써도 되기 때문에","mis":"SC3-2-u2-X26"}],"mis":"SC3-2-u2-X26","explanation":["함께 쓰는 게시판이에요.","존중해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_basic#10','sci',3,2,'u2','L05','g3_2_sci_u2_L05_basic','lesson_basic','SC3-2-u2-C10',3,'mc','auto','바닷가 지형 설명 카드 ㉡에 알맞은 지형은 무엇인가요?',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C10","difficulty":3,"kind":"mc","stem":"바닷가 지형 설명 카드 ㉡에 알맞은 지형은 무엇인가요?","options":[{"t":"동굴","correct":true},{"t":"절벽","mis":"SC3-2-u2-X23"},{"t":"모래사장","mis":"SC3-2-u2-X23"},{"t":"갯벌","mis":"SC3-2-u2-X23"}],"explanation":["㉡을 읽어요.","바위에 구멍이 있어요.","동굴이에요."],"asset":{"type":"passage","lines":["㉠ 바위가 높고 가파르며, 튀어나온 부분이 있어요.","㉡ 바위에 구멍이 있고, 구멍으로 물이 지나가요.","㉢ 고운 모래가 넓게 펼쳐져 있어요.","㉣ 진흙이 보이고 색이 어두우며 물이 고여 있어요."],"title":"바닷가 지형 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#1','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C10',2,'sa','auto','바위가 높고 가파르게 서 있는 지형을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"sa","stem":"바위가 높고 가파르게 서 있는 지형을 두 글자로 쓰세요.","answer":["절벽"],"explanation":["가파른 바위예요.","바닷가에서 봐요.","절벽이에요."],"mis":"SC3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#2','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C10',2,'mc','auto','바닷가 지형 설명 카드 ㉣에 알맞은 지형은 무엇인가요?',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"mc","stem":"바닷가 지형 설명 카드 ㉣에 알맞은 지형은 무엇인가요?","options":[{"t":"갯벌","correct":true},{"t":"모래사장","mis":"SC3-2-u2-X23"},{"t":"동굴","mis":"SC3-2-u2-X23"},{"t":"절벽","mis":"SC3-2-u2-X23"}],"explanation":["㉣을 읽어요.","진흙이 보여요.","갯벌이에요."],"asset":{"type":"passage","lines":["㉠ 바위가 높고 가파르며, 튀어나온 부분이 있어요.","㉡ 바위에 구멍이 있고, 구멍으로 물이 지나가요.","㉢ 고운 모래가 넓게 펼쳐져 있어요.","㉣ 진흙이 보이고 색이 어두우며 물이 고여 있어요."],"title":"바닷가 지형 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#3','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C10',3,'error','auto','바닷가 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X24','SC3-2-u2-X23']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C10","difficulty":3,"kind":"error","stem":"바닷가 지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「바닷가에서는 절벽, 동굴, 모래사장만 볼 수 있어.」","correct":true,"mis_target":"SC3-2-u2-X24"},{"t":"친구 가 — 「가파른 절벽을 볼 수 있어.」","mis":"SC3-2-u2-X23"},{"t":"친구 나 — 「바위에 구멍이 뚫린 동굴도 있어.」","mis":"SC3-2-u2-X23"}],"explanation":["바닷가 지형을 떠올려요.","갯벌도 있어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#4','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C11',3,'mc','auto','바닷가 지형 설명 카드를 「바위로 이루어진 지형」과 「모래나 흙으로 이루어진 지형」으로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u2-X25']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C11","difficulty":3,"kind":"mc","stem":"바닷가 지형 설명 카드를 「바위로 이루어진 지형」과 「모래나 흙으로 이루어진 지형」으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"바위 ㉠, ㉡ / 모래나 흙 ㉢, ㉣","correct":true},{"t":"바위 ㉠, ㉢ / 모래나 흙 ㉡, ㉣","mis":"SC3-2-u2-X25"},{"t":"바위 ㉡, ㉣ / 모래나 흙 ㉠, ㉢","mis":"SC3-2-u2-X25"},{"t":"바위 ㉠, ㉡, ㉢ / 모래나 흙 ㉣","mis":"SC3-2-u2-X25"}],"explanation":["㉠, ㉡은 바위예요.","㉢은 모래, ㉣은 진흙이에요.","㉠㉡ / ㉢㉣이에요."],"asset":{"type":"passage","lines":["㉠ 바위가 높고 가파르며, 튀어나온 부분이 있어요.","㉡ 바위에 구멍이 있고, 구멍으로 물이 지나가요.","㉢ 고운 모래가 넓게 펼쳐져 있어요.","㉣ 진흙이 보이고 색이 어두우며 물이 고여 있어요."],"title":"바닷가 지형 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#5','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C10',3,'mc','auto','절벽과 동굴의 공통점은 무엇인가요?',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C10","difficulty":3,"kind":"mc","stem":"절벽과 동굴의 공통점은 무엇인가요?","options":[{"t":"둘 다 바위로 이루어진 지형이다","correct":true},{"t":"둘 다 모래가 넓게 펼쳐져 있다","mis":"SC3-2-u2-X23"},{"t":"둘 다 진흙이 보인다","mis":"SC3-2-u2-X23"},{"t":"둘 다 바위에 구멍이 뚫려 있다","mis":"SC3-2-u2-X23"}],"explanation":["두 지형을 떠올려요.","구멍은 동굴만이에요.","둘 다 바위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#6','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C11',3,'match','auto','지형을 조사할 때 하는 일과 지킬 약속을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C11","difficulty":3,"kind":"match","stem":"지형을 조사할 때 하는 일과 지킬 약속을 알맞게 이으세요.","pairs":[{"l":"스마트 기기로 사진 찾기","r":"수업과 관계있는 것만 찾아요"},{"l":"사진을 게시판에 올리기","r":"지형의 특징을 함께 써요"},{"l":"친구 사진 보기","r":"친구 생각을 존중해요"}],"mis":"SC3-2-u2-X26","explanation":["찾을 때는 수업과 관계있게요.","올릴 때는 특징을 써요.","볼 때는 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#7','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C11',3,'mc','auto','여행하며 찍은 바닷가 사진에 네 가지 지형과 다른 모습의 바위가 있었어요. 알맞게 생각한 것은 무엇인가요?',ARRAY['SC3-2-u2-X24']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C11","difficulty":3,"kind":"mc","stem":"여행하며 찍은 바닷가 사진에 네 가지 지형과 다른 모습의 바위가 있었어요. 알맞게 생각한 것은 무엇인가요?","options":[{"t":"바닷가 지형은 네 가지 외에도 더 있으니 특징을 살펴 조사한다","correct":true},{"t":"네 가지가 아니니 바닷가 지형이 아니다","mis":"SC3-2-u2-X24"},{"t":"사진이 잘못 찍힌 것이다","mis":"SC3-2-u2-X24"},{"t":"사막에서 볼 수 있는 지형이다","mis":"SC3-2-u2-X24"}],"explanation":["지형이 네 가지뿐일까요?","더 있어요.","조사해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#8','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C10',4,'mc','auto','바닷가에서 「발이 푹푹 빠지는 어두운 색 땅에 게가 지나가고, 물이 군데군데 고여 있다」고 기록했어요. 이 지형과 그렇게 생각한 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X23','SC3-2-u2-X24']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C10","difficulty":4,"kind":"mc","stem":"바닷가에서 「발이 푹푹 빠지는 어두운 색 땅에 게가 지나가고, 물이 군데군데 고여 있다」고 기록했어요. 이 지형과 그렇게 생각한 까닭은 무엇인가요?","options":[{"t":"갯벌 — 진흙이 보이고 색이 어두우며 물이 고여 있어서","correct":true},{"t":"모래사장 — 모래가 넓게 펼쳐져 있어서","mis":"SC3-2-u2-X23"},{"t":"동굴 — 바위에 구멍이 있어서","mis":"SC3-2-u2-X23"},{"t":"사막 — 땅이 넓어서","mis":"SC3-2-u2-X24"}],"explanation":["어두운 색 땅이에요.","물이 고여 있어요.","갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#9','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C11',4,'mc','auto','바닷가 지형 사진을 친구들과 나누는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X26','SC3-2-u2-X24']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C11","difficulty":4,"kind":"mc","stem":"바닷가 지형 사진을 친구들과 나누는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사진에 지형의 이름과 특징을 쓰고, 친구 사진에는 잘한 점을 댓글로 단다","correct":true},{"t":"친구 사진이 별로라고 댓글을 단다","mis":"SC3-2-u2-X26"},{"t":"수업과 관계없는 재미있는 사진을 찾아 올린다","mis":"SC3-2-u2-X26"},{"t":"사막 사진도 바닷가 지형이라고 올린다","mis":"SC3-2-u2-X24"}],"explanation":["특징을 함께 써요.","친구를 존중해요.","잘한 점을 댓글로 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L05_challenge#10','sci',3,2,'u2','L05','g3_2_sci_u2_L05_challenge','lesson_challenge','SC3-2-u2-C10',4,'essay','teacher','바닷가 지형 설명 카드 ㉠~㉣의 지형 이름을 쓰고, 그 가운데 두 지형을 골라 공통점이나 차이점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C10","difficulty":4,"kind":"essay","stem":"바닷가 지형 설명 카드 ㉠~㉣의 지형 이름을 쓰고, 그 가운데 두 지형을 골라 공통점이나 차이점을 쓰세요.","answer_guide":{"answer":"예: ㉠은 절벽, ㉡은 동굴, ㉢은 모래사장, ㉣은 갯벌이다. 절벽과 동굴은 둘 다 바위로 이루어져 있지만, 동굴은 바위에 구멍이 뚫려 있고 절벽은 가파른 모습이다.","scoring_points":["네 지형의 이름을 바르게 썼는가","두 지형을 골랐는가","공통점이나 차이점을 특징으로 썼는가"]},"explanation":["이름을 써요.","두 지형을 골라요.","특징으로 견줘요."],"asset":{"type":"passage","lines":["㉠ 바위가 높고 가파르며, 튀어나온 부분이 있어요.","㉡ 바위에 구멍이 있고, 구멍으로 물이 지나가요.","㉢ 고운 모래가 넓게 펼쳐져 있어요.","㉣ 진흙이 보이고 색이 어두우며 물이 고여 있어요."],"title":"바닷가 지형 설명 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#1','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C12',1,'mc','auto','바닷물이 바다에서 육지 쪽으로 밀려 들어오는 것을 무엇이라고 하나요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X30']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C12","difficulty":1,"kind":"mc","stem":"바닷물이 바다에서 육지 쪽으로 밀려 들어오는 것을 무엇이라고 하나요?","options":[{"t":"밀물","correct":true},{"t":"썰물","mis":"SC3-2-u2-X27"},{"t":"파도","mis":"SC3-2-u2-X30"},{"t":"바람","mis":"SC3-2-u2-X27"}],"explanation":["밀려 들어와요.","이름이 닮았어요.","밀물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#2','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C12',1,'sa','auto','바닷물이 육지에서 바다 쪽으로 빠져나가는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C12","difficulty":1,"kind":"sa","stem":"바닷물이 육지에서 바다 쪽으로 빠져나가는 것을 두 글자로 쓰세요.","answer":["썰물"],"explanation":["빠져나가요.","밀물과 반대예요.","썰물이에요."],"mis":"SC3-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#3','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C12',1,'ox','auto','밀물 때 바닷물의 높이가 높아져요.',ARRAY['SC3-2-u2-X28']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C12","difficulty":1,"kind":"ox","stem":"밀물 때 바닷물의 높이가 높아져요.","answer":"O","reason_options":[{"t":"바닷물이 육지 쪽으로 밀려 들어오기 때문에","correct":true},{"t":"바닷물이 바다 쪽으로 빠져나가기 때문에","mis":"SC3-2-u2-X28"}],"mis":"SC3-2-u2-X28","explanation":["밀물을 떠올려요.","물이 들어와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#4','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C13',1,'mc','auto','걸어서 섬에 갈 수 있을 때는 언제인가요?',ARRAY['SC3-2-u2-X29','SC3-2-u2-X30','SC3-2-u2-X31']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C13","difficulty":1,"kind":"mc","stem":"걸어서 섬에 갈 수 있을 때는 언제인가요?","options":[{"t":"썰물로 바닷물의 높이가 낮아졌을 때","correct":true},{"t":"밀물로 바닷물의 높이가 높아졌을 때","mis":"SC3-2-u2-X29"},{"t":"파도가 크게 칠 때","mis":"SC3-2-u2-X30"},{"t":"언제든지","mis":"SC3-2-u2-X31"}],"explanation":["바닷길이 드러나야 해요.","물이 빠져나가요.","썰물 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#5','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C12',2,'match','auto','바닷물의 움직임과 높이를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C12","difficulty":2,"kind":"match","stem":"바닷물의 움직임과 높이를 알맞게 이으세요.","pairs":[{"l":"육지 쪽으로 밀려 들어와요","r":"높이가 높아져요"},{"l":"바다 쪽으로 빠져나가요","r":"높이가 낮아져요"},{"l":"시간이 지나요","r":"높이가 달라져요"}],"mis":"SC3-2-u2-X28","explanation":["들어오면 높아져요.","나가면 낮아져요.","시간에 따라 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#6','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C13',2,'mc','auto','밀물과 썰물 모형에서 모래사장의 표지판이 물에 잠겼어요. 이때는 언제인가요?',ARRAY['SC3-2-u2-X29','SC3-2-u2-X28']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"mc","stem":"밀물과 썰물 모형에서 모래사장의 표지판이 물에 잠겼어요. 이때는 언제인가요?","options":[{"t":"밀물 때","correct":true},{"t":"썰물 때","mis":"SC3-2-u2-X29"},{"t":"바닷물이 줄어들 때","mis":"SC3-2-u2-X28"},{"t":"바닷물이 빠져나간 뒤","mis":"SC3-2-u2-X29"}],"explanation":["표지판이 잠겼어요.","물이 높아졌어요.","밀물 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#7','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C13',2,'mc','auto','썰물 때 볼 수 있는 모습은 무엇인가요?',ARRAY['SC3-2-u2-X29']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"mc","stem":"썰물 때 볼 수 있는 모습은 무엇인가요?","options":[{"t":"바닷길이 드러난다","correct":true},{"t":"표지판이 물에 잠긴다","mis":"SC3-2-u2-X29"},{"t":"바닷길이 사라진다","mis":"SC3-2-u2-X29"},{"t":"바닷물이 많이 보인다","mis":"SC3-2-u2-X29"}],"explanation":["물이 빠져나가요.","땅이 보여요.","바닷길이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#8','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C13',2,'blank','auto','「바닷물의 높이는 (    )에 따라 달라져요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X31']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"blank","stem":"「바닷물의 높이는 (    )에 따라 달라져요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"시간","correct":true},{"t":"색깔","mis":"SC3-2-u2-X31"},{"t":"바닷물의 맛","mis":"SC3-2-u2-X31"},{"t":"모래의 양","mis":"SC3-2-u2-X31"}],"explanation":["모형을 떠올려요.","언제인지에 따라 달라요.","시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#9','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C13',2,'ox','auto','파도가 모래사장에 밀려왔다 쓸려 나가는 것은 밀물과 썰물이에요.',ARRAY['SC3-2-u2-X30']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"ox","stem":"파도가 모래사장에 밀려왔다 쓸려 나가는 것은 밀물과 썰물이에요.","answer":"X","reason_options":[{"t":"파도는 잠깐 일어나는 일이고, 밀물과 썰물은 일정 시간 동안 이어지기 때문에","correct":true},{"t":"바닷물이 들어왔다 나가는 것은 모두 같은 일이기 때문에","mis":"SC3-2-u2-X30"}],"mis":"SC3-2-u2-X30","explanation":["파도를 떠올려요.","잠깐 일어나요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_basic#10','sci',3,2,'u2','L06','g3_2_sci_u2_L06_basic','lesson_basic','SC3-2-u2-C12',3,'mc','auto','바닷가 관찰 기록에서 오후 3시는 밀물 때와 썰물 때 가운데 언제인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X31']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C12","difficulty":3,"kind":"mc","stem":"바닷가 관찰 기록에서 오후 3시는 밀물 때와 썰물 때 가운데 언제인가요?","options":[{"t":"썰물 때 — 표지판과 바닷길이 드러났으니까","correct":true},{"t":"밀물 때 — 바닷길이 드러났으니까","mis":"SC3-2-u2-X27"},{"t":"밀물 때 — 바닷물이 빠져나갔으니까","mis":"SC3-2-u2-X27"},{"t":"알 수 없다 — 바닷물 높이는 언제나 같으니까","mis":"SC3-2-u2-X31"}],"explanation":["오후 3시 줄을 읽어요.","드러났어요.","썰물 때예요."],"asset":{"type":"passage","lines":["오전 9시 — 모래사장의 표지판이 물에 잠겨 있어요.","오전 9시 — 섬으로 가는 바닷길이 보이지 않아요.","오후 3시 — 잠겨 있던 표지판이 드러났어요.","오후 3시 — 섬으로 가는 바닷길이 드러났어요."],"title":"바닷가 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#1','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C12',2,'sa','auto','바닷물이 육지 쪽으로 밀려 들어오는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C12","difficulty":2,"kind":"sa","stem":"바닷물이 육지 쪽으로 밀려 들어오는 것을 두 글자로 쓰세요.","answer":["밀물"],"explanation":["밀려 들어와요.","밀◯이에요.","밀물이에요."],"mis":"SC3-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#2','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C13',2,'mc','auto','바닷가 관찰 기록에서 오전 9시에 섬으로 걸어가기 어려운 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X29','SC3-2-u2-X30','SC3-2-u2-X31']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"mc","stem":"바닷가 관찰 기록에서 오전 9시에 섬으로 걸어가기 어려운 까닭은 무엇인가요?","options":[{"t":"밀물로 바닷물의 높이가 높아져 바닷길이 잠겼기 때문에","correct":true},{"t":"썰물로 바닷물이 빠져나갔기 때문에","mis":"SC3-2-u2-X29"},{"t":"파도가 쳤기 때문에","mis":"SC3-2-u2-X30"},{"t":"바닷길이 원래 없기 때문에","mis":"SC3-2-u2-X31"}],"explanation":["오전 9시 줄을 읽어요.","바닷길이 안 보여요.","밀물 때라 잠겼어요."],"asset":{"type":"passage","lines":["오전 9시 — 모래사장의 표지판이 물에 잠겨 있어요.","오전 9시 — 섬으로 가는 바닷길이 보이지 않아요.","오후 3시 — 잠겨 있던 표지판이 드러났어요.","오후 3시 — 섬으로 가는 바닷길이 드러났어요."],"title":"바닷가 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#3','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C13',3,'error','auto','밀물과 썰물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X30','SC3-2-u2-X29','SC3-2-u2-X28']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C13","difficulty":3,"kind":"error","stem":"밀물과 썰물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「파도가 한 번 밀려오면 그게 밀물이야.」","correct":true,"mis_target":"SC3-2-u2-X30"},{"t":"친구 가 — 「썰물 때 바닷길이 드러나.」","mis":"SC3-2-u2-X29"},{"t":"친구 다 — 「밀물 때 바닷물의 높이가 높아져.」","mis":"SC3-2-u2-X28"}],"explanation":["파도와 밀물은 달라요.","파도는 잠깐이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#4','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C12',3,'mc','auto','「(가) 바닷물이 육지 쪽으로 밀려 들어왔어요. (나) 바닷물이 바다 쪽으로 빠져나갔어요.」 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X30']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C12","difficulty":3,"kind":"mc","stem":"「(가) 바닷물이 육지 쪽으로 밀려 들어왔어요. (나) 바닷물이 바다 쪽으로 빠져나갔어요.」 알맞게 말한 것은 무엇인가요?","options":[{"t":"(가)는 밀물, (나)는 썰물이다","correct":true},{"t":"(가)는 썰물, (나)는 밀물이다","mis":"SC3-2-u2-X27"},{"t":"(가)와 (나) 모두 파도이다","mis":"SC3-2-u2-X30"},{"t":"(가)와 (나) 모두 밀물이다","mis":"SC3-2-u2-X27"}],"explanation":["들어오면 밀물이에요.","나가면 썰물이에요.","(가) 밀물, (나) 썰물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#5','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C12',3,'mc','auto','썰물 때를 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X28','SC3-2-u2-X31']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C12","difficulty":3,"kind":"mc","stem":"썰물 때를 알맞게 말한 것은 무엇인가요?","options":[{"t":"바닷물이 바다 쪽으로 빠져나가 높이가 낮아진다","correct":true},{"t":"바닷물이 육지 쪽으로 들어와 높이가 높아진다","mis":"SC3-2-u2-X27"},{"t":"바닷물이 빠져나가 높이가 높아진다","mis":"SC3-2-u2-X28"},{"t":"바닷물의 높이는 변하지 않는다","mis":"SC3-2-u2-X31"}],"explanation":["썰물은 빠져나가요.","높이가 낮아져요.","그게 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#6','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C13',3,'match','auto','바닷가 모습과 그때를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C13","difficulty":3,"kind":"match","stem":"바닷가 모습과 그때를 알맞게 이으세요.","pairs":[{"l":"표지판이 물에 잠겨요","r":"밀물 때"},{"l":"바닷길이 드러나요","r":"썰물 때"},{"l":"물이 잠깐 밀려왔다 쓸려 나가요","r":"파도가 칠 때"}],"mis":"SC3-2-u2-X29","explanation":["잠기면 밀물이에요.","드러나면 썰물이에요.","잠깐이면 파도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#7','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C13',3,'mc','auto','밀물과 썰물 모형에서 바닷물의 높이 변화가 헷갈릴 때 살펴보면 좋은 것은 무엇인가요?',ARRAY['SC3-2-u2-X31','SC3-2-u2-X30']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C13","difficulty":3,"kind":"mc","stem":"밀물과 썰물 모형에서 바닷물의 높이 변화가 헷갈릴 때 살펴보면 좋은 것은 무엇인가요?","options":[{"t":"모래사장의 표지판이 잠기는지 드러나는지","correct":true},{"t":"바닷물의 색깔","mis":"SC3-2-u2-X31"},{"t":"하늘의 구름","mis":"SC3-2-u2-X31"},{"t":"파도의 크기","mis":"SC3-2-u2-X30"}],"explanation":["높이를 알려 주는 것이에요.","모래사장에 있어요.","표지판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#8','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C13',4,'mc','auto','바닷가 관찰 기록을 보고 섬에 다녀오려는 계획으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X29','SC3-2-u2-X31','SC3-2-u2-X30']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C13","difficulty":4,"kind":"mc","stem":"바닷가 관찰 기록을 보고 섬에 다녀오려는 계획으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"바닷길이 드러난 썰물 때 건너가고, 바닷물이 다시 들어오기 전에 돌아온다","correct":true},{"t":"표지판이 잠긴 밀물 때 걸어서 건너간다","mis":"SC3-2-u2-X29"},{"t":"바닷물 높이는 그대로이니 아무 때나 건너간다","mis":"SC3-2-u2-X31"},{"t":"파도가 잠잠해지면 밀물 때라도 건너간다","mis":"SC3-2-u2-X30"}],"explanation":["바닷길이 드러나는 때예요.","다시 들어오기도 해요.","썰물 때 다녀와요."],"asset":{"type":"passage","lines":["오전 9시 — 모래사장의 표지판이 물에 잠겨 있어요.","오전 9시 — 섬으로 가는 바닷길이 보이지 않아요.","오후 3시 — 잠겨 있던 표지판이 드러났어요.","오후 3시 — 섬으로 가는 바닷길이 드러났어요."],"title":"바닷가 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#9','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C12',4,'mc','auto','「밀물 때 바닷물의 높이가 낮아져요.」를 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u2-X28','SC3-2-u2-X27','SC3-2-u2-X31']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C12","difficulty":4,"kind":"mc","stem":"「밀물 때 바닷물의 높이가 낮아져요.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"밀물 때 바닷물의 높이가 높아져요","correct":true},{"t":"썰물 때 바닷물의 높이가 높아져요","mis":"SC3-2-u2-X28"},{"t":"밀물 때 바닷물이 바다 쪽으로 빠져나가요","mis":"SC3-2-u2-X27"},{"t":"밀물 때와 썰물 때 높이는 같아요","mis":"SC3-2-u2-X31"}],"explanation":["밀물을 떠올려요.","물이 들어와요.","높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L06_challenge#10','sci',3,2,'u2','L06','g3_2_sci_u2_L06_challenge','lesson_challenge','SC3-2-u2-C12',4,'essay','teacher','바닷가 관찰 기록을 보고 오전 9시와 오후 3시가 각각 밀물 때인지 썰물 때인지 쓰고, 그렇게 생각한 까닭을 바닷물의 높이와 이어 쓰세요. 파도와 밀물·썰물이 어떻게 다른지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C12","difficulty":4,"kind":"essay","stem":"바닷가 관찰 기록을 보고 오전 9시와 오후 3시가 각각 밀물 때인지 썰물 때인지 쓰고, 그렇게 생각한 까닭을 바닷물의 높이와 이어 쓰세요. 파도와 밀물·썰물이 어떻게 다른지도 쓰세요.","answer_guide":{"answer":"예: 오전 9시는 밀물 때이다. 바닷물이 육지 쪽으로 밀려 들어와 높이가 높아져서 표지판과 바닷길이 잠겼다. 오후 3시는 썰물 때이다. 바닷물이 바다 쪽으로 빠져나가 높이가 낮아져서 표지판과 바닷길이 드러났다. 파도는 잠깐 밀려왔다 쓸려 나가지만 밀물과 썰물은 일정 시간 동안 이어진다.","scoring_points":["두 때를 바르게 썼는가","까닭을 바닷물의 높이와 이어 썼는가","파도와 밀물·썰물의 차이를 썼는가"]},"explanation":["두 때를 써요.","높이와 이어요.","파도와 견줘요."],"asset":{"type":"passage","lines":["오전 9시 — 모래사장의 표지판이 물에 잠겨 있어요.","오전 9시 — 섬으로 가는 바닷길이 보이지 않아요.","오후 3시 — 잠겨 있던 표지판이 드러났어요.","오후 3시 — 섬으로 가는 바닷길이 드러났어요."],"title":"바닷가 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#1','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C14',1,'mc','auto','밀물 때 바닷물에 잠기고 썰물 때 바닷물 밖으로 드러나는 땅은 무엇인가요?',ARRAY['SC3-2-u2-X32']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C14","difficulty":1,"kind":"mc","stem":"밀물 때 바닷물에 잠기고 썰물 때 바닷물 밖으로 드러나는 땅은 무엇인가요?","options":[{"t":"갯벌","correct":true},{"t":"모래사장","mis":"SC3-2-u2-X32"},{"t":"절벽","mis":"SC3-2-u2-X32"},{"t":"동굴","mis":"SC3-2-u2-X32"}],"explanation":["잠기고 드러나요.","게와 조개가 살아요.","갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#2','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C14',1,'sa','auto','우리나라 갯벌을 주로 볼 수 있는 곳은 서해안과 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C14","difficulty":1,"kind":"sa","stem":"우리나라 갯벌을 주로 볼 수 있는 곳은 서해안과 어디인가요? 세 글자로 쓰세요.","answer":["남해안"],"explanation":["동해안은 아니에요.","서해안과 함께예요.","남해안이에요."],"mis":"SC3-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#3','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C15',1,'ox','auto','갯벌은 다양한 생물이 살아가는 터전이 되어 줘요.',ARRAY['SC3-2-u2-X34']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C15","difficulty":1,"kind":"ox","stem":"갯벌은 다양한 생물이 살아가는 터전이 되어 줘요.","answer":"O","reason_options":[{"t":"조개, 게 등 많은 생물이 갯벌에서 살기 때문에","correct":true},{"t":"갯벌에는 생물이 살지 않기 때문에","mis":"SC3-2-u2-X34"}],"mis":"SC3-2-u2-X34","explanation":["갯벌 생물을 떠올려요.","많이 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#4','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C14',1,'mc','auto','갯벌에 사는 생물이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u2-X34']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C14","difficulty":1,"kind":"mc","stem":"갯벌에 사는 생물이 아닌 것은 무엇인가요?","options":[{"t":"북극곰","correct":true},{"t":"칠게","mis":"SC3-2-u2-X34"},{"t":"바지락","mis":"SC3-2-u2-X34"},{"t":"낙지","mis":"SC3-2-u2-X34"}],"explanation":["갯벌 생물을 떠올려요.","하나는 빙하에 살아요.","북극곰이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#5','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C15',2,'match','auto','갯벌에서 일어나는 일과 좋은 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C15","difficulty":2,"kind":"match","stem":"갯벌에서 일어나는 일과 좋은 점을 알맞게 이으세요.","pairs":[{"l":"찌꺼기를 걸러 내요","r":"바다가 깨끗해져요"},{"l":"게가 굴을 파요","r":"갯벌이 썩지 않아요"},{"l":"철새가 알을 낳아요","r":"새끼를 기르기 좋아요"}],"mis":"SC3-2-u2-X36","explanation":["갯벌 카드를 떠올려요.","굴로 공기가 드나들어요.","걸러 내면 깨끗해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#6','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C16',2,'mc','auto','갯벌을 지키기 위한 노력으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X37']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C16","difficulty":2,"kind":"mc","stem":"갯벌을 지키기 위한 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"갯벌 체험 때 생물을 함부로 잡지 않는다","correct":true},{"t":"조개를 보이는 대로 모두 캐 간다","mis":"SC3-2-u2-X37"},{"t":"갯벌에 쓰레기를 묻는다","mis":"SC3-2-u2-X37"},{"t":"철새를 쫓아낸다","mis":"SC3-2-u2-X37"}],"explanation":["갯벌을 지키는 행동이에요.","생물을 아껴요.","함부로 잡지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#7','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C14',2,'mc','auto','동해안에서 갯벌을 찾아보기 어려운 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X33']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C14","difficulty":2,"kind":"mc","stem":"동해안에서 갯벌을 찾아보기 어려운 까닭은 무엇인가요?","options":[{"t":"밀물과 썰물 때 바닷물의 높이 차가 작아서","correct":true},{"t":"바닷물이 더 짜서","mis":"SC3-2-u2-X33"},{"t":"날씨가 추워서","mis":"SC3-2-u2-X33"},{"t":"모래가 없어서","mis":"SC3-2-u2-X33"}],"explanation":["갯벌은 잠기고 드러나요.","높이 차가 커야 해요.","동해안은 높이 차가 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#8','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C15',2,'blank','auto','「갯벌은 (    )나 태풍의 피해를 줄여 줘요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X35']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C15","difficulty":2,"kind":"blank","stem":"「갯벌은 (    )나 태풍의 피해를 줄여 줘요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"홍수","correct":true},{"t":"가뭄","mis":"SC3-2-u2-X35"},{"t":"지진","mis":"SC3-2-u2-X35"},{"t":"산불","mis":"SC3-2-u2-X35"}],"explanation":["물과 관계있어요.","태풍과 함께 와요.","홍수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#9','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C16',2,'ox','auto','갯벌에 쓰레기를 조금씩 버리는 것은 괜찮아요.',ARRAY['SC3-2-u2-X37']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C16","difficulty":2,"kind":"ox","stem":"갯벌에 쓰레기를 조금씩 버리는 것은 괜찮아요.","answer":"X","reason_options":[{"t":"쓰레기는 갯벌과 갯벌에 사는 생물을 해치기 때문에","correct":true},{"t":"갯벌이 넓어서 쓰레기를 모두 걸러 주기 때문에","mis":"SC3-2-u2-X37"}],"mis":"SC3-2-u2-X37","explanation":["갯벌을 지키는 행동인가요?","쓰레기는 해쳐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_basic#10','sci',3,2,'u2','L07','g3_2_sci_u2_L07_basic','lesson_basic','SC3-2-u2-C15',3,'mc','auto','갯벌 조사 카드 ㉢처럼 게와 지렁이가 굴을 파면 갯벌에 어떤 좋은 점이 있나요?',ARRAY['SC3-2-u2-X36','SC3-2-u2-X35','SC3-2-u2-X33']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C15","difficulty":3,"kind":"mc","stem":"갯벌 조사 카드 ㉢처럼 게와 지렁이가 굴을 파면 갯벌에 어떤 좋은 점이 있나요?","options":[{"t":"갯벌이 썩지 않는다","correct":true},{"t":"갯벌이 바닷물에 잠기지 않는다","mis":"SC3-2-u2-X36"},{"t":"바닷물이 짜진다","mis":"SC3-2-u2-X35"},{"t":"갯벌이 동해안으로 옮겨 간다","mis":"SC3-2-u2-X33"}],"explanation":["㉢을 읽어요.","공기가 드나들어요.","썩지 않아요."],"asset":{"type":"passage","lines":["㉠ 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해요.","㉡ 철새와 물고기가 알을 낳고 새끼를 기르기 좋아요.","㉢ 게와 지렁이가 굴을 파서 신선한 공기가 드나들어요.","㉣ 홍수나 태풍의 피해를 줄여 줘요."],"title":"갯벌 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#1','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C16',2,'sa','auto','「소중한 갯벌을 잘 지키고 보살펴 ○○해야 해요.」 ○○에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C16","difficulty":2,"kind":"sa","stem":"「소중한 갯벌을 잘 지키고 보살펴 ○○해야 해요.」 ○○에 알맞은 말을 두 글자로 쓰세요.","answer":["보전","보호"],"explanation":["지키고 보살펴요.","보◯이에요.","보전이에요."],"mis":"SC3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#2','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C14',2,'mc','auto','우리나라 서해안과 남해안에 갯벌이 많은 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X33']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C14","difficulty":2,"kind":"mc","stem":"우리나라 서해안과 남해안에 갯벌이 많은 까닭은 무엇인가요?","options":[{"t":"밀물과 썰물 때 바닷물의 높이 차가 커서","correct":true},{"t":"바닷물이 더 짜서","mis":"SC3-2-u2-X33"},{"t":"모래가 더 많아서","mis":"SC3-2-u2-X33"},{"t":"날씨가 더 따뜻해서","mis":"SC3-2-u2-X33"}],"explanation":["동해안과 견줘요.","높이 차를 떠올려요.","높이 차가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#3','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C15',3,'error','auto','갯벌을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X35','SC3-2-u2-X34']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C15","difficulty":3,"kind":"error","stem":"갯벌을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「갯벌은 진흙투성이라 쓸모가 없어.」","correct":true,"mis_target":"SC3-2-u2-X35"},{"t":"친구 가 — 「갯벌은 육지에서 온 찌꺼기를 걸러 줘.」","mis":"SC3-2-u2-X35"},{"t":"친구 나 — 「칠게와 낙지가 갯벌에 살아.」","mis":"SC3-2-u2-X34"}],"explanation":["갯벌의 역할을 떠올려요.","많은 도움을 줘요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#4','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C15',3,'mc','auto','갯벌 조사 카드 가운데 생물과 관련 있는 이야기끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X36']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C15","difficulty":3,"kind":"mc","stem":"갯벌 조사 카드 가운데 생물과 관련 있는 이야기끼리 묶은 것은 무엇인가요?","options":[{"t":"㉡, ㉢","correct":true},{"t":"㉠, ㉣","mis":"SC3-2-u2-X36"},{"t":"㉠, ㉡","mis":"SC3-2-u2-X36"},{"t":"㉢, ㉣","mis":"SC3-2-u2-X36"}],"explanation":["생물이 나오는 카드예요.","철새와 게가 나와요.","㉡, ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해요.","㉡ 철새와 물고기가 알을 낳고 새끼를 기르기 좋아요.","㉢ 게와 지렁이가 굴을 파서 신선한 공기가 드나들어요.","㉣ 홍수나 태풍의 피해를 줄여 줘요."],"title":"갯벌 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#5','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C14',3,'mc','auto','갯벌을 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u2-X32']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C14","difficulty":3,"kind":"mc","stem":"갯벌을 바르게 설명한 것은 무엇인가요?","options":[{"t":"밀물 때는 바닷물에 잠기고 썰물 때는 드러나는 땅이다","correct":true},{"t":"언제나 바닷물에 잠겨 있는 땅이다","mis":"SC3-2-u2-X32"},{"t":"언제나 드러나 있는 모래 땅이다","mis":"SC3-2-u2-X32"},{"t":"바위에 구멍이 뚫린 지형이다","mis":"SC3-2-u2-X32"}],"explanation":["밀물과 썰물을 떠올려요.","잠기고 드러나요.","그게 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#6','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C14',3,'match','auto','갯벌에서 볼 수 있는 생물과 생김새를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C14","difficulty":3,"kind":"match","stem":"갯벌에서 볼 수 있는 생물과 생김새를 알맞게 이으세요.","pairs":[{"l":"칠게","r":"집게발이 있는 게"},{"l":"바지락","r":"단단한 껍데기가 있는 조개"},{"l":"알락꼬리마도요","r":"부리가 긴 새"}],"mis":"SC3-2-u2-X34","explanation":["게는 집게발이 있어요.","조개는 껍데기가 있어요.","새는 부리가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#7','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C16',3,'mc','auto','갯벌 체험 학습에서 지킬 약속끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X37']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C16","difficulty":3,"kind":"mc","stem":"갯벌 체험 학습에서 지킬 약속끼리 묶은 것은 무엇인가요?","options":[{"t":"쓰레기를 되가져가고, 생물을 함부로 잡지 않는다","correct":true},{"t":"쓰레기를 갯벌에 묻고, 조개를 모두 캔다","mis":"SC3-2-u2-X37"},{"t":"생물을 많이 잡아 집에서 기른다","mis":"SC3-2-u2-X37"},{"t":"철새가 보이면 가까이 가서 쫓는다","mis":"SC3-2-u2-X37"}],"explanation":["갯벌을 지켜요.","생물을 아껴요.","되가져가고 잡지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#8','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C16',4,'mc','auto','갯벌을 보전해야 하는 까닭을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X35','SC3-2-u2-X33','SC3-2-u2-X34']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C16","difficulty":4,"kind":"mc","stem":"갯벌을 보전해야 하는 까닭을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"갯벌은 생물의 터전이 되고 바다를 깨끗하게 하며 피해를 줄여 주는 소중한 땅이기 때문에","correct":true},{"t":"갯벌에 쓰레기를 묻을 수 있기 때문에","mis":"SC3-2-u2-X35"},{"t":"갯벌은 동해안에만 있어 귀하기 때문에","mis":"SC3-2-u2-X33"},{"t":"갯벌에는 생물이 없어 깨끗하기 때문에","mis":"SC3-2-u2-X34"}],"explanation":["갯벌의 역할을 떠올려요.","여러 가지 도움을 줘요.","소중한 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#9','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C15',4,'mc','auto','「갯벌이 사라지면 어떤 일이 생길까?」에 알맞은 생각은 무엇인가요?',ARRAY['SC3-2-u2-X35','SC3-2-u2-X36']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C15","difficulty":4,"kind":"mc","stem":"「갯벌이 사라지면 어떤 일이 생길까?」에 알맞은 생각은 무엇인가요?","options":[{"t":"육지에서 온 찌꺼기가 걸러지지 않아 바다가 더러워지고, 철새가 새끼를 기를 곳이 줄어든다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"SC3-2-u2-X35"},{"t":"바닷물이 덜 짜진다","mis":"SC3-2-u2-X35"},{"t":"홍수 피해가 줄어든다","mis":"SC3-2-u2-X36"}],"explanation":["갯벌이 하던 일을 떠올려요.","그 일을 못 해요.","바다와 철새가 힘들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L07_challenge#10','sci',3,2,'u2','L07','g3_2_sci_u2_L07_challenge','lesson_challenge','SC3-2-u2-C15',4,'essay','teacher','갯벌 조사 카드에서 두 가지를 골라 갯벌의 가치를 쓰고, 갯벌을 지키기 위해 내가 할 수 있는 일 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C15","difficulty":4,"kind":"essay","stem":"갯벌 조사 카드에서 두 가지를 골라 갯벌의 가치를 쓰고, 갯벌을 지키기 위해 내가 할 수 있는 일 두 가지를 쓰세요.","answer_guide":{"answer":"예: 갯벌은 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해 주고, 홍수나 태풍의 피해를 줄여 준다. 갯벌을 지키기 위해 갯벌에 쓰레기를 버리지 않고, 갯벌 체험을 할 때 생물을 함부로 잡지 않겠다.","scoring_points":["갯벌의 가치 두 가지를 썼는가","가치를 갯벌의 역할과 이어 썼는가","내가 할 수 있는 일 두 가지를 썼는가"]},"explanation":["카드를 골라요.","가치를 써요.","할 일을 써요."],"asset":{"type":"passage","lines":["㉠ 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해요.","㉡ 철새와 물고기가 알을 낳고 새끼를 기르기 좋아요.","㉢ 게와 지렁이가 굴을 파서 신선한 공기가 드나들어요.","㉣ 홍수나 태풍의 피해를 줄여 줘요."],"title":"갯벌 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#1','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',1,'mc','auto','갯벌 보전의 필요성을 여러 사람에게 알리려고 만드는 것은 무엇인가요?',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C17","difficulty":1,"kind":"mc","stem":"갯벌 보전의 필요성을 여러 사람에게 알리려고 만드는 것은 무엇인가요?","options":[{"t":"홍보 자료","correct":true},{"t":"실험 기록","mis":"SC3-2-u2-X39"},{"t":"관찰 일지","mis":"SC3-2-u2-X39"},{"t":"붙임딱지","mis":"SC3-2-u2-X39"}],"explanation":["알리려고 만들어요.","여러 사람이 봐요.","홍보 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#2','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',1,'sa','auto','뉴스에서 갯벌이 오염된 까닭이 된 사고는 무엇이 유출된 사고인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C17","difficulty":1,"kind":"sa","stem":"뉴스에서 갯벌이 오염된 까닭이 된 사고는 무엇이 유출된 사고인가요? 두 글자로 쓰세요.","answer":["기름"],"explanation":["뉴스를 떠올려요.","바다에 새어 나왔어요.","기름이에요."],"mis":"SC3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#3','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C16',1,'ox','auto','오염된 갯벌은 울타리로 막아 두면 괜찮아요.',ARRAY['SC3-2-u2-X38']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C16","difficulty":1,"kind":"ox","stem":"오염된 갯벌은 울타리로 막아 두면 괜찮아요.","answer":"X","reason_options":[{"t":"갯벌은 바닷물이 드나드는 곳이라 바다 전체를 오염시킬 수 있기 때문에","correct":true},{"t":"울타리가 있으면 오염 물질이 움직이지 못하기 때문에","mis":"SC3-2-u2-X38"}],"mis":"SC3-2-u2-X38","explanation":["갯벌은 잠기고 드러나요.","바닷물이 드나들어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#4','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',1,'mc','auto','홍보 자료에 꼭 담아야 할 내용은 무엇인가요?',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C17","difficulty":1,"kind":"mc","stem":"홍보 자료에 꼭 담아야 할 내용은 무엇인가요?","options":[{"t":"갯벌의 가치와 보전의 필요성","correct":true},{"t":"가장 화려한 꾸밈","mis":"SC3-2-u2-X39"},{"t":"우리 모둠 이름만","mis":"SC3-2-u2-X39"},{"t":"갯벌과 관계없는 그림","mis":"SC3-2-u2-X39"}],"explanation":["무엇을 알리나요?","갯벌이 소중한 까닭이에요.","가치와 필요성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#5','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',2,'match','auto','계획서 칸과 알맞은 예시를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"match","stem":"계획서 칸과 알맞은 예시를 이으세요.","pairs":[{"l":"문제 상황","r":"기름이 유출되어 갯벌이 오염돼요"},{"l":"역할 나누기","r":"자료 정리, 그림, 제작, 발표"},{"l":"보완할 점","r":"글씨를 진하게 고쳐요"}],"mis":"SC3-2-u2-X39","explanation":["계획서 칸을 떠올려요.","문제 상황은 뉴스예요.","역할과 보완할 점을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#6','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',2,'mc','auto','홍보 자료를 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"mc","stem":"홍보 자료를 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"계획하기 → 만들기 → 소통하기","correct":true},{"t":"만들기 → 계획하기 → 소통하기","mis":"SC3-2-u2-X39"},{"t":"소통하기 → 만들기 → 계획하기","mis":"SC3-2-u2-X39"},{"t":"계획 없이 만들기만 한다","mis":"SC3-2-u2-X39"}],"explanation":["먼저 계획해요.","그다음 만들어요.","마지막에 소통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#7','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',2,'mc','auto','다른 모둠의 발표를 들을 때 알맞은 태도는 무엇인가요?',ARRAY['SC3-2-u2-X40']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"mc","stem":"다른 모둠의 발표를 들을 때 알맞은 태도는 무엇인가요?","options":[{"t":"잘 듣고 잘한 점을 칭찬한다","correct":true},{"t":"비난하는 댓글을 단다","mis":"SC3-2-u2-X40"},{"t":"우리 모둠 것만 자랑한다","mis":"SC3-2-u2-X40"},{"t":"딴생각을 한다","mis":"SC3-2-u2-X40"}],"explanation":["듣는 사람의 약속이에요.","잘 들어요.","잘한 점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#8','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C17',2,'blank','auto','「다른 곳에서 가져온 자료는 (    )를 밝혀요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"blank","stem":"「다른 곳에서 가져온 자료는 (    )를 밝혀요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"출처","correct":true},{"t":"가격","mis":"SC3-2-u2-X39"},{"t":"색깔","mis":"SC3-2-u2-X39"},{"t":"무게","mis":"SC3-2-u2-X39"}],"explanation":["어디서 가져왔나요?","그곳을 밝혀요.","출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#9','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C16',2,'ox','auto','홍보 자료에 「갯벌을 지키기 위해 우리가 할 일」을 넣으면 좋아요.',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C16","difficulty":2,"kind":"ox","stem":"홍보 자료에 「갯벌을 지키기 위해 우리가 할 일」을 넣으면 좋아요.","answer":"O","reason_options":[{"t":"보는 사람이 갯벌을 지키는 행동을 할 수 있기 때문에","correct":true},{"t":"갯벌의 가치만 넣고 할 일은 넣지 않아야 하기 때문에","mis":"SC3-2-u2-X39"}],"mis":"SC3-2-u2-X39","explanation":["보는 사람을 떠올려요.","행동하게 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_basic#10','sci',3,2,'u2','L08','g3_2_sci_u2_L08_basic','lesson_basic','SC3-2-u2-C16',3,'mc','auto','오염된 갯벌에 울타리를 쳐도 바다 전체가 오염될 수 있는 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X38','SC3-2-u2-X32']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C16","difficulty":3,"kind":"mc","stem":"오염된 갯벌에 울타리를 쳐도 바다 전체가 오염될 수 있는 까닭은 무엇인가요?","options":[{"t":"갯벌은 밀물 때 잠기고 썰물 때 드러나 바닷물이 드나들기 때문에","correct":true},{"t":"울타리가 오염 물질을 만들기 때문에","mis":"SC3-2-u2-X38"},{"t":"갯벌은 바다와 떨어져 있기 때문에","mis":"SC3-2-u2-X32"},{"t":"바닷물은 갯벌에 들어오지 않기 때문에","mis":"SC3-2-u2-X38"}],"explanation":["갯벌의 뜻을 떠올려요.","바닷물이 드나들어요.","오염이 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#1','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',2,'sa','auto','모둠원이 자료 정리, 그림 그리기, 발표처럼 일을 나누어 맡는 것을 「○○ 나누기」라고 해요. ○○에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"sa","stem":"모둠원이 자료 정리, 그림 그리기, 발표처럼 일을 나누어 맡는 것을 「○○ 나누기」라고 해요. ○○에 알맞은 말을 두 글자로 쓰세요.","answer":["역할"],"explanation":["계획서 칸이에요.","맡은 일이에요.","역할이에요."],"mis":"SC3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#2','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C6',2,'mc','auto','무인도 탈출 문제에서 옳지 않은 설명끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X11','SC3-2-u2-X24','SC3-2-u2-X27']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C6","difficulty":2,"kind":"mc","stem":"무인도 탈출 문제에서 옳지 않은 설명끼리 묶은 것은 무엇인가요?","options":[{"t":"②, ④","correct":true},{"t":"①, ③","mis":"SC3-2-u2-X11"},{"t":"④, ⑤","mis":"SC3-2-u2-X24"},{"t":"②, ⑤","mis":"SC3-2-u2-X27"}],"explanation":["하나씩 따져요.","바다가 더 넓어요.","②, ④가 옳지 않아요."],"asset":{"type":"passage","lines":["① 지구를 둘러싸고 있는 공기를 대기라고 해요.","② 지구 표면에서 육지가 바다보다 넓어요.","③ 바닷물에는 소금이 녹아 있어 짠맛이 나요.","④ 바닷가에서 볼 수 있는 지형은 절벽과 동굴뿐이에요.","⑤ 썰물은 바닷물이 육지에서 바다 쪽으로 빠져나가는 거예요."],"title":"무인도 탈출 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#3','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',3,'error','auto','홍보 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C17","difficulty":3,"kind":"error","stem":"홍보 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「가장 화려하게 꾸미기만 하면 좋은 홍보 자료야.」","correct":true,"mis_target":"SC3-2-u2-X39"},{"t":"친구 가 — 「갯벌의 가치가 잘 드러나게 쓰자.」","mis":"SC3-2-u2-X39"},{"t":"친구 다 — 「가져온 사진은 출처를 밝히자.」","mis":"SC3-2-u2-X39"}],"explanation":["홍보 자료에서 중요한 것이에요.","가치와 필요성이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#4','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',3,'mc','auto','홍보 자료 계획서의 ㉠에 들어갈 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X39','SC3-2-u2-X38']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C17","difficulty":3,"kind":"mc","stem":"홍보 자료 계획서의 ㉠에 들어갈 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"갯벌이 하는 일과 갯벌에 사는 다양한 생물","correct":true},{"t":"모둠원이 좋아하는 놀이","mis":"SC3-2-u2-X39"},{"t":"반짝이 스티커를 붙일 곳","mis":"SC3-2-u2-X39"},{"t":"울타리만 치면 괜찮다는 말","mis":"SC3-2-u2-X38"}],"explanation":["넣고 싶은 내용이에요.","갯벌의 가치예요.","갯벌이 하는 일과 생물이에요."],"asset":{"type":"passage","lines":["문제 상황 — 기름이 유출되어 갯벌이 오염되고 있어요.","해결 방법 — 갯벌의 역할을 담은 홍보 자료를 만들어요.","역할 나누기 — 자료 정리, 그림 그리기, 제작, 발표","넣고 싶은 내용 — ㉠","보완할 점 — ㉡"],"title":"어느 모둠의 홍보 자료 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#5','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',3,'mc','auto','홍보 자료 계획서의 ㉡에 들어갈 보완할 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X40']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C17","difficulty":3,"kind":"mc","stem":"홍보 자료 계획서의 ㉡에 들어갈 보완할 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「내용이 잘 보이도록 글씨를 진하게 고치면 좋겠어요.」","correct":true},{"t":"「다 별로예요.」","mis":"SC3-2-u2-X40"},{"t":"「우리 모둠 것이 제일 좋아요.」","mis":"SC3-2-u2-X40"},{"t":"「그냥 처음부터 다시 해요.」","mis":"SC3-2-u2-X40"}],"explanation":["보완할 점이에요.","고칠 방법이 있어요.","글씨를 진하게 고쳐요."],"asset":{"type":"passage","lines":["문제 상황 — 기름이 유출되어 갯벌이 오염되고 있어요.","해결 방법 — 갯벌의 역할을 담은 홍보 자료를 만들어요.","역할 나누기 — 자료 정리, 그림 그리기, 제작, 발표","넣고 싶은 내용 — ㉠","보완할 점 — ㉡"],"title":"어느 모둠의 홍보 자료 계획서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#6','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',3,'match','auto','홍보 자료 만들기 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C17","difficulty":3,"kind":"match","stem":"홍보 자료 만들기 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"계획해요","r":"제목과 내용을 정해요"},{"l":"만들어요","r":"그림을 그리고 꾸며요"},{"l":"소통해요","r":"다른 모둠의 잘한 점을 말해요"}],"mis":"SC3-2-u2-X39","explanation":["계획은 먼저예요.","만들 때 그려요.","소통은 함께 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#7','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C10',3,'mc','auto','무인도 탈출 문제 ④를 옳게 고친 것은 무엇인가요?',ARRAY['SC3-2-u2-X24','SC3-2-u2-X22']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C10","difficulty":3,"kind":"mc","stem":"무인도 탈출 문제 ④를 옳게 고친 것은 무엇인가요?","options":[{"t":"바닷가에서는 절벽, 동굴, 모래사장, 갯벌 등 다양한 지형을 볼 수 있어요","correct":true},{"t":"바닷가에서 볼 수 있는 지형은 모래사장뿐이에요","mis":"SC3-2-u2-X24"},{"t":"바닷가에서는 사막을 볼 수 있어요","mis":"SC3-2-u2-X24"},{"t":"바닷가에서는 지형을 볼 수 없어요","mis":"SC3-2-u2-X22"}],"explanation":["④를 읽어요.","지형이 더 있어요.","다양한 지형이에요."],"asset":{"type":"passage","lines":["① 지구를 둘러싸고 있는 공기를 대기라고 해요.","② 지구 표면에서 육지가 바다보다 넓어요.","③ 바닷물에는 소금이 녹아 있어 짠맛이 나요.","④ 바닷가에서 볼 수 있는 지형은 절벽과 동굴뿐이에요.","⑤ 썰물은 바닷물이 육지에서 바다 쪽으로 빠져나가는 거예요."],"title":"무인도 탈출 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#8','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',4,'mc','auto','홍보 자료를 본 사람이 갯벌 지키기에 함께하게 하려면 무엇을 함께 넣으면 가장 좋을까요?',ARRAY['SC3-2-u2-X39','SC3-2-u2-X38','SC3-2-u2-X40']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C17","difficulty":4,"kind":"mc","stem":"홍보 자료를 본 사람이 갯벌 지키기에 함께하게 하려면 무엇을 함께 넣으면 가장 좋을까요?","options":[{"t":"갯벌의 가치와 함께, 쓰레기 버리지 않기처럼 우리가 할 수 있는 일","correct":true},{"t":"갯벌과 관계없는 재미있는 그림","mis":"SC3-2-u2-X39"},{"t":"「울타리만 치면 돼요」라는 말","mis":"SC3-2-u2-X38"},{"t":"다른 모둠 자료를 흉보는 말","mis":"SC3-2-u2-X40"}],"explanation":["보는 사람이 움직여야 해요.","할 일을 알려요.","가치와 할 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#9','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C16',4,'mc','auto','기름 유출 사고로 오염된 갯벌을 두고 가장 알맞게 생각한 것은 무엇인가요?',ARRAY['SC3-2-u2-X38','SC3-2-u2-X35','SC3-2-u2-X37']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C16","difficulty":4,"kind":"mc","stem":"기름 유출 사고로 오염된 갯벌을 두고 가장 알맞게 생각한 것은 무엇인가요?","options":[{"t":"바닷물이 드나들며 오염이 퍼질 수 있으니 갯벌이 오염되지 않도록 지키고 알려야 한다","correct":true},{"t":"울타리로 막아 두면 오염이 저절로 사라진다","mis":"SC3-2-u2-X38"},{"t":"갯벌은 쓸모없으니 그냥 둔다","mis":"SC3-2-u2-X35"},{"t":"생물을 모두 잡아 옮기면 된다","mis":"SC3-2-u2-X37"}],"explanation":["바닷물이 드나들어요.","오염이 퍼져요.","지키고 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L08_challenge#10','sci',3,2,'u2','L08','g3_2_sci_u2_L08_challenge','lesson_challenge','SC3-2-u2-C17',4,'essay','teacher','기름 유출로 갯벌이 오염된 상황에서 갯벌 홍보 자료를 만든다면, 제목과 꼭 넣을 내용 두 가지를 쓰고, 그 내용을 넣는 까닭을 갯벌의 가치와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C17","difficulty":4,"kind":"essay","stem":"기름 유출로 갯벌이 오염된 상황에서 갯벌 홍보 자료를 만든다면, 제목과 꼭 넣을 내용 두 가지를 쓰고, 그 내용을 넣는 까닭을 갯벌의 가치와 이어 쓰세요.","answer_guide":{"answer":"예: 제목은 「우리의 보물, 갯벌을 지켜 주세요」이다. 갯벌이 바다를 깨끗하게 하고 생물의 터전이 된다는 것과, 쓰레기를 버리지 않고 생물을 함부로 잡지 말자는 우리가 할 일을 넣겠다. 갯벌은 많은 생물이 사는 소중한 땅이고 바닷물이 드나들어 오염이 바다 전체로 퍼질 수 있으므로, 사람들이 가치를 알고 함께 지키게 하려는 것이다.","scoring_points":["제목을 썼는가","꼭 넣을 내용 두 가지를 썼는가","까닭을 갯벌의 가치와 이어 썼는가"]},"explanation":["제목을 정해요.","내용 두 가지를 써요.","가치와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#1','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C19',1,'mc','auto','소금을 얻으려고 바닷물을 끌어 들여 논처럼 만든 곳은 어디인가요?',ARRAY['SC3-2-u2-X43']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C19","difficulty":1,"kind":"mc","stem":"소금을 얻으려고 바닷물을 끌어 들여 논처럼 만든 곳은 어디인가요?","options":[{"t":"염전","correct":true},{"t":"갯벌","mis":"SC3-2-u2-X43"},{"t":"절벽","mis":"SC3-2-u2-X43"},{"t":"호수","mis":"SC3-2-u2-X43"}],"explanation":["논처럼 만들어요.","소금을 얻어요.","염전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#2','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C18',1,'sa','auto','김, 미역, 다시마처럼 바다에서 자라는 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C18","difficulty":1,"kind":"sa","stem":"김, 미역, 다시마처럼 바다에서 자라는 것을 세 글자로 쓰세요.","answer":["해조류"],"explanation":["바다에서 자라요.","해◯◯예요.","해조류예요."],"mis":"SC3-2-u2-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#3','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C18',1,'ox','auto','바다에서 얻는 자원은 물고기뿐이에요.',ARRAY['SC3-2-u2-X41']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C18","difficulty":1,"kind":"ox","stem":"바다에서 얻는 자원은 물고기뿐이에요.","answer":"X","reason_options":[{"t":"바다에서 해조류, 소금, 전기, 마실 수 있는 물도 얻기 때문에","correct":true},{"t":"바다에는 물고기 말고는 쓸 것이 없기 때문에","mis":"SC3-2-u2-X41"}],"mis":"SC3-2-u2-X41","explanation":["바다 자원을 떠올려요.","여러 가지예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#4','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C19',1,'mc','auto','바닷물의 움직임으로 만들 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X43']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C19","difficulty":1,"kind":"mc","stem":"바닷물의 움직임으로 만들 수 있는 것은 무엇인가요?","options":[{"t":"전기","correct":true},{"t":"설탕","mis":"SC3-2-u2-X43"},{"t":"모래","mis":"SC3-2-u2-X43"},{"t":"구름","mis":"SC3-2-u2-X43"}],"explanation":["파도의 힘을 떠올려요.","에너지예요.","전기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#5','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C19',2,'match','auto','자원과 얻는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"match","stem":"자원과 얻는 방법을 알맞게 이으세요.","pairs":[{"l":"소금","r":"바닷물을 햇빛에 두어요"},{"l":"전기","r":"파도가 치는 힘을 이용해요"},{"l":"마실 수 있는 물","r":"바닷물을 쓸 수 있는 물로 바꾸는 기술"}],"mis":"SC3-2-u2-X43","explanation":["소금은 햇빛이에요.","전기는 파도의 힘이에요.","마실 물은 기술이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#6','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C18',2,'mc','auto','해조류가 아닌 것은 무엇인가요?',ARRAY['SC3-2-u2-X42']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C18","difficulty":2,"kind":"mc","stem":"해조류가 아닌 것은 무엇인가요?","options":[{"t":"조개","correct":true},{"t":"김","mis":"SC3-2-u2-X42"},{"t":"미역","mis":"SC3-2-u2-X42"},{"t":"다시마","mis":"SC3-2-u2-X42"}],"explanation":["바다에서 자라는 풀 같은 것이에요.","하나는 껍데기가 있어요.","조개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#7','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C19',2,'mc','auto','바다에서 얻는 전기의 좋은 점은 무엇인가요?',ARRAY['SC3-2-u2-X44']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"mc","stem":"바다에서 얻는 전기의 좋은 점은 무엇인가요?","options":[{"t":"환경 오염 걱정이 없는 친환경 에너지이다","correct":true},{"t":"밤에만 만들 수 있다","mis":"SC3-2-u2-X44"},{"t":"바닷물을 더 짜게 만든다","mis":"SC3-2-u2-X44"},{"t":"물고기를 늘려 준다","mis":"SC3-2-u2-X44"}],"explanation":["어떤 에너지였나요?","환경을 지켜요.","친환경 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#8','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C19',2,'blank','auto','「우리나라 염전은 (    )에서 많이 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"blank","stem":"「우리나라 염전은 (    )에서 많이 볼 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"서해안","correct":true},{"t":"동해안","mis":"SC3-2-u2-X43"},{"t":"높은 산","mis":"SC3-2-u2-X43"},{"t":"사막","mis":"SC3-2-u2-X43"}],"explanation":["갯벌이 많은 곳을 떠올려요.","서쪽 바닷가예요.","서해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#9','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C19',2,'ox','auto','바닷물을 마실 수 있는 물로 바꾸는 기술은 물 부족 문제를 해결하는 데 도움을 줄 수 있어요.',ARRAY['SC3-2-u2-X44']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"ox","stem":"바닷물을 마실 수 있는 물로 바꾸는 기술은 물 부족 문제를 해결하는 데 도움을 줄 수 있어요.","answer":"O","reason_options":[{"t":"우리가 쓸 수 있는 육지의 물은 적기 때문에","correct":true},{"t":"물이 부족한 곳은 어디에도 없기 때문에","mis":"SC3-2-u2-X44"}],"mis":"SC3-2-u2-X44","explanation":["육지의 물을 떠올려요.","적었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_basic#10','sci',3,2,'u2','L09','g3_2_sci_u2_L09_basic','lesson_basic','SC3-2-u2-C18',3,'mc','auto','바다 자원 카드에서 바다 생물에서 얻는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X41','SC3-2-u2-X42']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C18","difficulty":3,"kind":"mc","stem":"바다 자원 카드에서 바다 생물에서 얻는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉢, ㉣","mis":"SC3-2-u2-X41"},{"t":"㉠, ㉢","mis":"SC3-2-u2-X41"},{"t":"㉡, ㉣","mis":"SC3-2-u2-X42"}],"explanation":["살아 있는 것을 찾아요.","게, 조개, 김, 미역이에요.","㉠, ㉡이에요."],"asset":{"type":"passage","lines":["㉠ 게와 조개","㉡ 김, 미역, 다시마","㉢ 햇빛에 둔 바닷물에서 얻은 소금","㉣ 파도의 힘으로 만든 전기"],"title":"바다 자원 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#1','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C19',2,'sa','auto','바닷물을 끌어 들여 햇빛에 두고 소금을 얻는 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"sa","stem":"바닷물을 끌어 들여 햇빛에 두고 소금을 얻는 곳을 두 글자로 쓰세요.","answer":["염전"],"explanation":["논처럼 생겼어요.","염◯이에요.","염전이에요."],"mis":"SC3-2-u2-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#2','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C18',2,'mc','auto','해조류의 쓰임으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X42','SC3-2-u2-X43']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C18","difficulty":2,"kind":"mc","stem":"해조류의 쓰임으로 알맞은 것은 무엇인가요?","options":[{"t":"먹을거리뿐 아니라 화장품이나 건강식품의 재료로도 쓰인다","correct":true},{"t":"먹을 수만 있고 다른 데에는 쓰지 않는다","mis":"SC3-2-u2-X42"},{"t":"전기를 만드는 데에만 쓰인다","mis":"SC3-2-u2-X42"},{"t":"소금을 만드는 데에만 쓰인다","mis":"SC3-2-u2-X43"}],"explanation":["김과 미역을 떠올려요.","다른 쓰임도 있어요.","화장품 재료로도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#3','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C18',3,'error','auto','바다 자원을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X41','SC3-2-u2-X43','SC3-2-u2-X44']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C18","difficulty":3,"kind":"error","stem":"바다 자원을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「바다에서 얻는 건 물고기 같은 먹을거리뿐이야.」","correct":true,"mis_target":"SC3-2-u2-X41"},{"t":"친구 나 — 「밀물과 썰물의 차이로 전기를 만들 수 있어.」","mis":"SC3-2-u2-X43"},{"t":"친구 다 — 「바닷물로 마실 수 있는 물을 만들 수 있어.」","mis":"SC3-2-u2-X44"}],"explanation":["바다 자원을 떠올려요.","전기와 소금도 있어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#4','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C19',3,'mc','auto','바다 자원 카드에서 바닷물의 움직임을 이용한 것은 무엇인가요?',ARRAY['SC3-2-u2-X43']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C19","difficulty":3,"kind":"mc","stem":"바다 자원 카드에서 바닷물의 움직임을 이용한 것은 무엇인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SC3-2-u2-X43"},{"t":"㉡","mis":"SC3-2-u2-X43"},{"t":"㉢","mis":"SC3-2-u2-X43"}],"explanation":["움직임이에요.","파도의 힘이에요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 게와 조개","㉡ 김, 미역, 다시마","㉢ 햇빛에 둔 바닷물에서 얻은 소금","㉣ 파도의 힘으로 만든 전기"],"title":"바다 자원 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#5','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C19',3,'mc','auto','밀물과 썰물의 차이를 이용해 얻을 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X43','SC3-2-u2-X42','SC3-2-u2-X41']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C19","difficulty":3,"kind":"mc","stem":"밀물과 썰물의 차이를 이용해 얻을 수 있는 것은 무엇인가요?","options":[{"t":"전기","correct":true},{"t":"소금","mis":"SC3-2-u2-X43"},{"t":"김","mis":"SC3-2-u2-X42"},{"t":"조개","mis":"SC3-2-u2-X41"}],"explanation":["바닷물의 높이가 바뀌어요.","움직임을 이용해요.","전기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#6','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C18',3,'match','auto','바다 자원과 알맞은 무리를 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C18","difficulty":3,"kind":"match","stem":"바다 자원과 알맞은 무리를 이으세요.","pairs":[{"l":"미역","r":"해조류"},{"l":"바지락","r":"조개"},{"l":"파도의 힘","r":"전기"}],"mis":"SC3-2-u2-X42","explanation":["미역은 바다에서 자라요.","바지락은 껍데기가 있어요.","파도의 힘은 전기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#7','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C19',3,'mc','auto','바다를 연구하는 사람으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X44']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C19","difficulty":3,"kind":"mc","stem":"바다를 연구하는 사람으로 알맞은 것은 무엇인가요?","options":[{"t":"해양 연구원","correct":true},{"t":"제빵사","mis":"SC3-2-u2-X44"},{"t":"미용사","mis":"SC3-2-u2-X44"},{"t":"택배 기사","mis":"SC3-2-u2-X44"}],"explanation":["바다를 연구해요.","해양이 바다예요.","해양 연구원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#8','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C19',4,'mc','auto','물이 부족한 섬마을에 가장 도움이 될 바다 자원 이용 방법은 무엇인가요?',ARRAY['SC3-2-u2-X21','SC3-2-u2-X43','SC3-2-u2-X42']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C19","difficulty":4,"kind":"mc","stem":"물이 부족한 섬마을에 가장 도움이 될 바다 자원 이용 방법은 무엇인가요?","options":[{"t":"바닷물을 마실 수 있는 물로 바꾸는 기술을 쓴다","correct":true},{"t":"바닷물을 그대로 마신다","mis":"SC3-2-u2-X21"},{"t":"염전을 더 만든다","mis":"SC3-2-u2-X43"},{"t":"해조류를 더 많이 기른다","mis":"SC3-2-u2-X42"}],"explanation":["물이 부족해요.","바닷물은 그대로 못 마셔요.","바꾸는 기술을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#9','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C18',4,'mc','auto','「바다는 아낌없이 주는 바다예요.」라고 말할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X41']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C18","difficulty":4,"kind":"mc","stem":"「바다는 아낌없이 주는 바다예요.」라고 말할 수 있는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"먹을거리, 해조류, 소금, 마실 수 있는 물, 전기까지 살아가는 데 필요한 자원을 많이 주기 때문에","correct":true},{"t":"물고기만 아주 많이 주기 때문에","mis":"SC3-2-u2-X41"},{"t":"바닷물이 짜서 아무 데도 쓸 수 없기 때문에","mis":"SC3-2-u2-X41"},{"t":"전기만 만들어 주기 때문에","mis":"SC3-2-u2-X41"}],"explanation":["바다 자원을 모두 떠올려요.","여러 가지예요.","많은 자원을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_L09_challenge#10','sci',3,2,'u2','L09','g3_2_sci_u2_L09_challenge','lesson_challenge','SC3-2-u2-C19',4,'essay','teacher','바다에서 얻을 수 있는 자원 세 가지를 쓰고, 그 가운데 하나를 골라 얻는 방법과 우리 생활에 주는 도움을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C19","difficulty":4,"kind":"essay","stem":"바다에서 얻을 수 있는 자원 세 가지를 쓰고, 그 가운데 하나를 골라 얻는 방법과 우리 생활에 주는 도움을 쓰세요.","answer_guide":{"answer":"예: 바다에서는 김 같은 해조류, 소금, 전기를 얻을 수 있다. 소금은 바닷물을 염전에 끌어 들여 햇빛에 두면 얻을 수 있다. 소금은 음식의 간을 맞추는 데 쓰여 우리 생활에 도움을 준다.","scoring_points":["바다 자원 세 가지를 썼는가","하나를 골라 얻는 방법을 썼는가","생활에 주는 도움을 썼는가"]},"explanation":["자원을 떠올려요.","얻는 방법을 써요.","도움을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#1','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C3',1,'mc','auto','물결반 일지 ①에서 바람개비가 빙글빙글 돈 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X07','SC3-2-u2-X05']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C3","difficulty":1,"kind":"mc","stem":"물결반 일지 ①에서 바람개비가 빙글빙글 돈 까닭은 무엇인가요?","options":[{"t":"바람을 받았기 때문에","correct":true},{"t":"물이 흘렀기 때문에","mis":"SC3-2-u2-X07"},{"t":"모래가 날렸기 때문에","mis":"SC3-2-u2-X07"},{"t":"공기가 없었기 때문에","mis":"SC3-2-u2-X05"}],"explanation":["바람개비를 떠올려요.","바람이 불어요.","바람을 받았어요."],"asset":{"type":"passage","lines":["바닷가 언덕에서 바람개비가 빙글빙글 돌고 있었다.","하늘에는 연과 패러글라이딩을 하는 사람이 보였다.","선생님 — 「공기는 보이지 않지만 어디에나 있어요.」"],"title":"물결반 일지 ① 버스 창밖"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#2','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C6',1,'mc','auto','물결반 일지 ②에서 두 모둠 모두 더 많이 붙인 붙임쪽지는 무엇인가요?',ARRAY['SC3-2-u2-X13']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C6","difficulty":1,"kind":"mc","stem":"물결반 일지 ②에서 두 모둠 모두 더 많이 붙인 붙임쪽지는 무엇인가요?","options":[{"t":"바다 붙임쪽지","correct":true},{"t":"육지 붙임쪽지","mis":"SC3-2-u2-X13"},{"t":"두 붙임쪽지가 같다","mis":"SC3-2-u2-X13"},{"t":"알 수 없다","mis":"SC3-2-u2-X13"}],"explanation":["두 줄을 읽어요.","바다 쪽이 많아요.","바다 붙임쪽지예요."],"asset":{"type":"passage","lines":["1모둠 — 육지 붙임쪽지 20장 · 바다 붙임쪽지 50장","2모둠 — 육지 붙임쪽지 24장 · 바다 붙임쪽지 46장","덧붙임 — 바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙였다."],"title":"물결반 일지 ② 지구본 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#3','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C7',1,'mc','auto','육지의 물이 아닌 것은 무엇인가요?',ARRAY['SC3-2-u2-X14']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C7","difficulty":1,"kind":"mc","stem":"육지의 물이 아닌 것은 무엇인가요?","options":[{"t":"바닷물","correct":true},{"t":"강물","mis":"SC3-2-u2-X14"},{"t":"호수의 물","mis":"SC3-2-u2-X14"},{"t":"계곡의 물","mis":"SC3-2-u2-X14"}],"explanation":["육지에 있는 물을 떠올려요.","하나는 바다에 있어요.","바닷물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#4','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C8',1,'mc','auto','물결반 일지 ③의 약속에서 증발 접시를 옮길 때 쓰는 것은 무엇인가요?',ARRAY['SC3-2-u2-X16']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C8","difficulty":1,"kind":"mc","stem":"물결반 일지 ③의 약속에서 증발 접시를 옮길 때 쓰는 것은 무엇인가요?","options":[{"t":"집게","correct":true},{"t":"맨손","mis":"SC3-2-u2-X16"},{"t":"비닐봉지","mis":"SC3-2-u2-X16"},{"t":"종이","mis":"SC3-2-u2-X16"}],"explanation":["약속 줄을 읽어요.","접시가 뜨거워요.","집게예요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#5','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C10',1,'mc','auto','물결반 일지 ④의 ㉢에 알맞은 지형은 무엇인가요?',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C10","difficulty":1,"kind":"mc","stem":"물결반 일지 ④의 ㉢에 알맞은 지형은 무엇인가요?","options":[{"t":"모래사장","correct":true},{"t":"절벽","mis":"SC3-2-u2-X23"},{"t":"동굴","mis":"SC3-2-u2-X23"},{"t":"갯벌","mis":"SC3-2-u2-X23"}],"explanation":["㉢을 읽어요.","모래가 펼쳐져 있어요.","모래사장이에요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#6','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C12',1,'mc','auto','물결반 일지 ⑤에서 오후 4시는 언제인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X30','SC3-2-u2-X31']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C12","difficulty":1,"kind":"mc","stem":"물결반 일지 ⑤에서 오후 4시는 언제인가요?","options":[{"t":"밀물 때","correct":true},{"t":"썰물 때","mis":"SC3-2-u2-X27"},{"t":"파도가 멈춘 때","mis":"SC3-2-u2-X30"},{"t":"바닷물 높이가 그대로인 때","mis":"SC3-2-u2-X31"}],"explanation":["오후 4시 줄을 읽어요.","바닷물이 밀려 들어왔어요.","밀물 때예요."],"asset":{"type":"passage","lines":["오전 10시 — 바닷길이 드러나 표지판 아래 모래가 보였다.","오후 4시 — 바닷물이 밀려 들어와 바닷길과 표지판이 잠겼다.","덧붙임 — 그사이 파도는 여러 번 밀려왔다 쓸려 나갔다."],"title":"물결반 일지 ⑤ 섬 바닷길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#7','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C14',1,'mc','auto','물결반 일지 ⑥에서 본 생물 가운데 새는 무엇인가요?',ARRAY['SC3-2-u2-X34']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C14","difficulty":1,"kind":"mc","stem":"물결반 일지 ⑥에서 본 생물 가운데 새는 무엇인가요?","options":[{"t":"알락꼬리마도요","correct":true},{"t":"칠게","mis":"SC3-2-u2-X34"},{"t":"바지락","mis":"SC3-2-u2-X34"},{"t":"낙지","mis":"SC3-2-u2-X34"}],"explanation":["본 생물을 읽어요.","날개가 있어요.","알락꼬리마도요예요."],"asset":{"type":"passage","lines":["본 생물 — 칠게, 바지락, 낙지, 알락꼬리마도요","게가 판 굴이 여기저기 있었다.","친구 가 — 바지락을 보이는 대로 모두 캐서 집에 가져가려 했다.","친구 나 — 가져온 쓰레기를 모두 봉투에 담아 왔다."],"title":"물결반 일지 ⑥ 갯벌 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
