INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#10','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C3',2,'mc','auto','물결반 일지 ①에서 공기를 느낄 수 있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X06','SC3-2-u2-X05']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"mc","stem":"물결반 일지 ①에서 공기를 느낄 수 있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"바람개비, 연, 패러글라이딩","correct":true},{"t":"바람개비만","mis":"SC3-2-u2-X06"},{"t":"연만","mis":"SC3-2-u2-X06"},{"t":"아무것도 없다","mis":"SC3-2-u2-X05"}],"explanation":["일지를 읽어요.","모두 공기와 관계있어요.","셋 다예요."],"asset":{"type":"passage","lines":["바닷가 언덕에서 바람개비가 빙글빙글 돌고 있었다.","하늘에는 연과 패러글라이딩을 하는 사람이 보였다.","선생님 — 「공기는 보이지 않지만 어디에나 있어요.」"],"title":"물결반 일지 ① 버스 창밖"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#11','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C6',2,'mc','auto','물결반 일지 ②에서 두 모둠의 개수가 다른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X12']::text[],false,'{"seq":11,"concept":"SC3-2-u2-C6","difficulty":2,"kind":"mc","stem":"물결반 일지 ②에서 두 모둠의 개수가 다른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"칸을 나누고 붙이는 방법이 모둠마다 조금씩 달라서","correct":true},{"t":"한 모둠이 실험을 잘못해서","mis":"SC3-2-u2-X12"},{"t":"지구본마다 바다가 달라서","mis":"SC3-2-u2-X12"},{"t":"붙임쪽지 색깔이 달라서","mis":"SC3-2-u2-X12"}],"explanation":["개수는 달라도 괜찮아요.","붙이는 방법이 조금씩 달라요.","그래서 달라요."],"asset":{"type":"passage","lines":["1모둠 — 육지 붙임쪽지 20장 · 바다 붙임쪽지 50장","2모둠 — 육지 붙임쪽지 24장 · 바다 붙임쪽지 46장","덧붙임 — 바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙였다."],"title":"물결반 일지 ② 지구본 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#12','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C9',2,'mc','auto','물결반 일지 ③에서 남은 물질이 있었던 물은 어느 것인가요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X17']::text[],false,'{"seq":12,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"mc","stem":"물결반 일지 ③에서 남은 물질이 있었던 물은 어느 것인가요?","options":[{"t":"㉯ 바닷물","correct":true},{"t":"㉮ 마을 냇물","mis":"SC3-2-u2-X18"},{"t":"㉮와 ㉯ 모두","mis":"SC3-2-u2-X18"},{"t":"알 수 없다","mis":"SC3-2-u2-X17"}],"explanation":["결과를 읽어요.","하얀 물질이 남았어요.","㉯ 바닷물이에요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#13','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C11',2,'mc','auto','물결반 일지 ④에서 바위로 이루어진 지형끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u2-X25']::text[],false,'{"seq":13,"concept":"SC3-2-u2-C11","difficulty":2,"kind":"mc","stem":"물결반 일지 ④에서 바위로 이루어진 지형끼리 묶은 것은 무엇인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉢, ㉣","mis":"SC3-2-u2-X25"},{"t":"㉠, ㉣","mis":"SC3-2-u2-X25"},{"t":"㉡, ㉢","mis":"SC3-2-u2-X25"}],"explanation":["바위를 찾아요.","㉠, ㉡이 바위예요.","㉠, ㉡이에요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#14','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C13',2,'mc','auto','물결반 일지 ⑤에서 오전 10시에 바닷길이 드러난 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X30','SC3-2-u2-X31']::text[],false,'{"seq":14,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"mc","stem":"물결반 일지 ⑤에서 오전 10시에 바닷길이 드러난 까닭은 무엇인가요?","options":[{"t":"썰물로 바닷물이 빠져나가 높이가 낮아졌기 때문에","correct":true},{"t":"밀물로 바닷물이 밀려 들어왔기 때문에","mis":"SC3-2-u2-X27"},{"t":"파도가 멈췄기 때문에","mis":"SC3-2-u2-X30"},{"t":"바닷물 높이는 늘 같기 때문에","mis":"SC3-2-u2-X31"}],"explanation":["오전 10시 줄을 읽어요.","길이 드러났어요.","썰물 때예요."],"asset":{"type":"passage","lines":["오전 10시 — 바닷길이 드러나 표지판 아래 모래가 보였다.","오후 4시 — 바닷물이 밀려 들어와 바닷길과 표지판이 잠겼다.","덧붙임 — 그사이 파도는 여러 번 밀려왔다 쓸려 나갔다."],"title":"물결반 일지 ⑤ 섬 바닷길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#15','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C16',2,'mc','auto','물결반 일지 ⑥에서 갯벌을 지키는 행동을 한 친구는 누구인가요?',ARRAY['SC3-2-u2-X37']::text[],false,'{"seq":15,"concept":"SC3-2-u2-C16","difficulty":2,"kind":"mc","stem":"물결반 일지 ⑥에서 갯벌을 지키는 행동을 한 친구는 누구인가요?","options":[{"t":"친구 나","correct":true},{"t":"친구 가","mis":"SC3-2-u2-X37"},{"t":"두 친구 모두","mis":"SC3-2-u2-X37"},{"t":"아무도 없다","mis":"SC3-2-u2-X37"}],"explanation":["두 친구를 견줘요.","쓰레기를 담아 왔어요.","친구 나예요."],"asset":{"type":"passage","lines":["본 생물 — 칠게, 바지락, 낙지, 알락꼬리마도요","게가 판 굴이 여기저기 있었다.","친구 가 — 바지락을 보이는 대로 모두 캐서 집에 가져가려 했다.","친구 나 — 가져온 쓰레기를 모두 봉투에 담아 왔다."],"title":"물결반 일지 ⑥ 갯벌 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#16','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C17',2,'mc','auto','물결반 일지 ⑦의 친구 의견이 좋은 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X40','SC3-2-u2-X39']::text[],false,'{"seq":16,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"mc","stem":"물결반 일지 ⑦의 친구 의견이 좋은 까닭은 무엇인가요?","options":[{"t":"잘한 점을 먼저 말하고, 보완할 점을 고칠 방법과 함께 말했기 때문에","correct":true},{"t":"잘못된 점만 말했기 때문에","mis":"SC3-2-u2-X40"},{"t":"자기 모둠 자랑을 했기 때문에","mis":"SC3-2-u2-X40"},{"t":"꾸밈이 화려하다고만 했기 때문에","mis":"SC3-2-u2-X39"}],"explanation":["「생생해」가 있어요.","「출처를 밝히면」이 있어요.","고칠 방법이 있어요."],"asset":{"type":"passage","lines":["제목 — 「갯벌은 살아 있어요!」","내용 — 갯벌이 바다를 깨끗하게 해요 · 생물의 터전이에요","내용 — 쓰레기를 버리지 말아요","친구 의견 — 「생물 그림이 생생해. 사진 출처를 밝히면 더 좋겠어.」"],"title":"물결반 일지 ⑦ 홍보 포스터 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#17','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C2',3,'mc','auto','두 그림을 견주어 다른 그림을 찾을 때 가장 알맞은 방법은 무엇인가요?',ARRAY['SC3-2-u2-X04','SC3-2-u2-X03']::text[],false,'{"seq":17,"concept":"SC3-2-u2-C2","difficulty":3,"kind":"mc","stem":"두 그림을 견주어 다른 그림을 찾을 때 가장 알맞은 방법은 무엇인가요?","options":[{"t":"장소를 하나씩 정해 (가)와 (나)를 견주고, 찾으면 장소를 말해 준다","correct":true},{"t":"한눈에 훑어보고 생각나는 대로 외친다","mis":"SC3-2-u2-X04"},{"t":"(가)만 자세히 보고 (나)는 보지 않는다","mis":"SC3-2-u2-X03"},{"t":"친구가 찾은 것을 가린다","mis":"SC3-2-u2-X04"}],"explanation":["장소마다 견줘요.","두 그림을 다 봐요.","찾으면 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#18','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C6',3,'mc','auto','물결반 일지 ②의 결과를 바르게 읽은 것은 무엇인가요?',ARRAY['SC3-2-u2-X13','SC3-2-u2-X12']::text[],false,'{"seq":18,"concept":"SC3-2-u2-C6","difficulty":3,"kind":"mc","stem":"물결반 일지 ②의 결과를 바르게 읽은 것은 무엇인가요?","options":[{"t":"개수는 모둠마다 다르지만 두 모둠 모두 바다가 육지보다 넓다는 같은 결과를 얻었다","correct":true},{"t":"2모둠은 육지가 더 많아 육지가 넓다","mis":"SC3-2-u2-X13"},{"t":"개수가 달라서 아무것도 알 수 없다","mis":"SC3-2-u2-X12"},{"t":"1모둠만 바르게 붙였다","mis":"SC3-2-u2-X12"}],"explanation":["두 모둠을 견줘요.","바다가 모두 많아요.","결과는 같아요."],"asset":{"type":"passage","lines":["1모둠 — 육지 붙임쪽지 20장 · 바다 붙임쪽지 50장","2모둠 — 육지 붙임쪽지 24장 · 바다 붙임쪽지 46장","덧붙임 — 바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙였다."],"title":"물결반 일지 ② 지구본 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#19','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C9',3,'mc','auto','물결반 일지 ③의 결과로 알 수 있는 바닷물의 특징은 무엇인가요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X20']::text[],false,'{"seq":19,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"mc","stem":"물결반 일지 ③의 결과로 알 수 있는 바닷물의 특징은 무엇인가요?","options":[{"t":"소금 같은 물질이 녹아 있어 가열하면 남는 물질이 있다","correct":true},{"t":"바닷물에는 아무것도 녹아 있지 않다","mis":"SC3-2-u2-X18"},{"t":"냇물에도 바닷물과 같은 물질이 많다","mis":"SC3-2-u2-X18"},{"t":"바닷물을 가열하면 모래가 남는다","mis":"SC3-2-u2-X20"}],"explanation":["㉯의 결과를 봐요.","하얀 물질이 남았어요.","소금이 녹아 있어요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#20','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C10',3,'mc','auto','물결반 일지 ④의 ㉠과 ㉡의 공통점과 차이점을 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X25','SC3-2-u2-X23']::text[],false,'{"seq":20,"concept":"SC3-2-u2-C10","difficulty":3,"kind":"mc","stem":"물결반 일지 ④의 ㉠과 ㉡의 공통점과 차이점을 바르게 말한 것은 무엇인가요?","options":[{"t":"둘 다 바위로 이루어져 있지만, ㉡에는 구멍이 뚫려 있다","correct":true},{"t":"둘 다 모래로 되어 있지만, ㉠은 진흙이다","mis":"SC3-2-u2-X25"},{"t":"둘 다 구멍이 뚫려 있다","mis":"SC3-2-u2-X23"},{"t":"공통점이 하나도 없다","mis":"SC3-2-u2-X25"}],"explanation":["㉠, ㉡을 읽어요.","둘 다 바위예요.","구멍은 ㉡만이에요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#21','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C13',3,'mc','auto','물결반 일지 ⑤를 보고 섬에 다녀올 때 가장 알맞은 때는 언제인가요?',ARRAY['SC3-2-u2-X29','SC3-2-u2-X30','SC3-2-u2-X31']::text[],false,'{"seq":21,"concept":"SC3-2-u2-C13","difficulty":3,"kind":"mc","stem":"물결반 일지 ⑤를 보고 섬에 다녀올 때 가장 알맞은 때는 언제인가요?","options":[{"t":"바닷길이 드러난 오전 10시 무렵","correct":true},{"t":"바닷길이 잠긴 오후 4시 무렵","mis":"SC3-2-u2-X29"},{"t":"파도가 칠 때면 언제든","mis":"SC3-2-u2-X30"},{"t":"바닷물 높이는 같으니 아무 때나","mis":"SC3-2-u2-X31"}],"explanation":["바닷길이 있어야 해요.","드러난 때예요.","오전 10시 무렵이에요."],"asset":{"type":"passage","lines":["오전 10시 — 바닷길이 드러나 표지판 아래 모래가 보였다.","오후 4시 — 바닷물이 밀려 들어와 바닷길과 표지판이 잠겼다.","덧붙임 — 그사이 파도는 여러 번 밀려왔다 쓸려 나갔다."],"title":"물결반 일지 ⑤ 섬 바닷길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#22','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C16',3,'mc','auto','물결반 일지 ⑥의 친구 가에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X37']::text[],false,'{"seq":22,"concept":"SC3-2-u2-C16","difficulty":3,"kind":"mc","stem":"물결반 일지 ⑥의 친구 가에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「생물을 함부로 잡으면 갯벌의 생물이 줄어들어. 살펴보고 놓아주자.」","correct":true},{"t":"「더 많이 캐 가자.」","mis":"SC3-2-u2-X37"},{"t":"「갯벌에는 생물이 많으니 괜찮아.」","mis":"SC3-2-u2-X37"},{"t":"「쓰레기도 같이 묻고 가자.」","mis":"SC3-2-u2-X37"}],"explanation":["친구 가의 행동을 봐요.","생물을 아껴요.","놓아주자고 해요."],"asset":{"type":"passage","lines":["본 생물 — 칠게, 바지락, 낙지, 알락꼬리마도요","게가 판 굴이 여기저기 있었다.","친구 가 — 바지락을 보이는 대로 모두 캐서 집에 가져가려 했다.","친구 나 — 가져온 쓰레기를 모두 봉투에 담아 왔다."],"title":"물결반 일지 ⑥ 갯벌 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#23','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C19',4,'mc','auto','물결반 일지 ①의 바람개비와 ⑧의 바닷가 시설을 견주어 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X43','SC3-2-u2-X05']::text[],false,'{"seq":23,"concept":"SC3-2-u2-C19","difficulty":4,"kind":"mc","stem":"물결반 일지 ①의 바람개비와 ⑧의 바닷가 시설을 견주어 알맞게 말한 것은 무엇인가요?","options":[{"t":"바람개비는 공기의 움직임으로 돌고, 바닷가 시설은 바닷물의 움직임으로 전기를 만든다","correct":true},{"t":"둘 다 햇빛으로 움직인다","mis":"SC3-2-u2-X43"},{"t":"바닷가 시설은 소금으로 전기를 만든다","mis":"SC3-2-u2-X43"},{"t":"바람개비는 공기가 없어서 돈다","mis":"SC3-2-u2-X05"}],"explanation":["①은 공기예요.","⑧은 바닷물이에요.","둘 다 움직임을 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#24','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C6',4,'essay','teacher','물결반 일지 ②를 보고 지구 표면에서 육지와 바다 가운데 어느 곳이 더 넓은지 쓰고, 그 근거와 육지·바다에서 볼 수 있는 모습을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u2-C6","difficulty":4,"kind":"essay","stem":"물결반 일지 ②를 보고 지구 표면에서 육지와 바다 가운데 어느 곳이 더 넓은지 쓰고, 그 근거와 육지·바다에서 볼 수 있는 모습을 쓰세요.","answer_guide":{"answer":"예: 지구 표면에서는 바다가 육지보다 넓다. 1모둠과 2모둠 모두 바다 붙임쪽지가 육지 붙임쪽지보다 훨씬 많았기 때문이다. 육지에서는 산, 들, 강, 사막 같은 다양한 모습을 볼 수 있고, 바다는 물로 덮여 있다.","scoring_points":["바다가 더 넓다고 썼는가","붙임쪽지 결과를 근거로 들었는가","육지와 바다의 모습을 썼는가"]},"explanation":["넓은 곳을 써요.","붙임쪽지를 근거로 들어요.","모습을 써요."],"asset":{"type":"passage","lines":["1모둠 — 육지 붙임쪽지 20장 · 바다 붙임쪽지 50장","2모둠 — 육지 붙임쪽지 24장 · 바다 붙임쪽지 46장","덧붙임 — 바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙였다."],"title":"물결반 일지 ② 지구본 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_a#25','sci',3,2,'u2','','g3_2_sci_u2_review_a','unit_review','SC3-2-u2-C16',4,'essay','teacher','물결반 일지 ⑥을 보고 친구 가와 친구 나의 행동을 갯벌 보전과 이어 평가하고, 갯벌을 보전해야 하는 까닭을 갯벌의 역할 두 가지와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u2-C16","difficulty":4,"kind":"essay","stem":"물결반 일지 ⑥을 보고 친구 가와 친구 나의 행동을 갯벌 보전과 이어 평가하고, 갯벌을 보전해야 하는 까닭을 갯벌의 역할 두 가지와 함께 쓰세요.","answer_guide":{"answer":"예: 친구 가처럼 바지락을 보이는 대로 모두 캐 가면 갯벌의 생물이 줄어들어 갯벌을 해친다. 친구 나처럼 쓰레기를 되가져가면 갯벌을 깨끗하게 지킬 수 있다. 갯벌은 다양한 생물의 터전이 되고, 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해 주므로 잘 보전해야 한다.","scoring_points":["두 친구의 행동을 바르게 평가했는가","평가를 갯벌 보전과 이어 썼는가","갯벌의 역할 두 가지를 까닭으로 썼는가"]},"explanation":["두 친구를 견줘요.","보전과 이어요.","역할을 써요."],"asset":{"type":"passage","lines":["본 생물 — 칠게, 바지락, 낙지, 알락꼬리마도요","게가 판 굴이 여기저기 있었다.","친구 가 — 바지락을 보이는 대로 모두 캐서 집에 가져가려 했다.","친구 나 — 가져온 쓰레기를 모두 봉투에 담아 왔다."],"title":"물결반 일지 ⑥ 갯벌 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#1','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C4',1,'sa','auto','지구를 둘러싸고 있는 공기를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u2-C4","difficulty":1,"kind":"sa","stem":"지구를 둘러싸고 있는 공기를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["대기"],"explanation":["지구 주위의 공기예요.","대◯예요.","대기예요."],"mis":"SC3-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#2','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C5',1,'sa','auto','땅으로 이루어진 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u2-C5","difficulty":1,"kind":"sa","stem":"땅으로 이루어진 곳을 두 글자로 쓰세요.","answer":["육지"],"explanation":["땅이에요.","산과 들이 있어요.","육지예요."],"mis":"SC3-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#3','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C9',1,'sa','auto','바닷물에서 짠맛이 나게 하는 물질을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-2-u2-C9","difficulty":1,"kind":"sa","stem":"바닷물에서 짠맛이 나게 하는 물질을 두 글자로 쓰세요.","answer":["소금"],"explanation":["짠맛이에요.","하얀 물질이에요.","소금이에요."],"mis":"SC3-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#4','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C8',1,'sa','auto','두 물을 가열할 때 눈을 지키려고 쓰는 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-2-u2-C8","difficulty":1,"kind":"sa","stem":"두 물을 가열할 때 눈을 지키려고 쓰는 것을 세 글자로 쓰세요.","answer":["보안경"],"explanation":["눈에 써요.","보◯◯이에요.","보안경이에요."],"mis":"SC3-2-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
