INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#6','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C12',1,'sa','auto','밀물과 반대로 바닷물이 바다 쪽으로 빠져나가는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u2-C12","difficulty":1,"kind":"sa","stem":"밀물과 반대로 바닷물이 바다 쪽으로 빠져나가는 것을 두 글자로 쓰세요.","answer":["썰물"],"explanation":["빠져나가요.","밀물과 반대예요.","썰물이에요."],"mis":"SC3-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#7','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C14',1,'sa','auto','밀물 때 잠기고 썰물 때 드러나는 땅을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC3-2-u2-C14","difficulty":1,"kind":"sa","stem":"밀물 때 잠기고 썰물 때 드러나는 땅을 두 글자로 쓰세요.","answer":["갯벌"],"explanation":["잠기고 드러나요.","게가 살아요.","갯벌이에요."],"mis":"SC3-2-u2-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#8','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C18',1,'sa','auto','물결반 일지 ⑧의 시장에서 파는 김, 미역, 다시마를 통틀어 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC3-2-u2-C18","difficulty":1,"kind":"sa","stem":"물결반 일지 ⑧의 시장에서 파는 김, 미역, 다시마를 통틀어 세 글자로 쓰세요.","answer":["해조류"],"explanation":["바다에서 자라요.","해◯◯예요.","해조류예요."],"asset":{"type":"passage","lines":["염전 — 바닷물을 끌어 들여 햇빛에 두고 소금을 얻어요.","시장 — 게, 조개와 김, 미역, 다시마를 팔아요.","바닷가 시설 — 바닷물의 움직임으로 전기를 만들어요."],"title":"물결반 일지 ⑧ 바다 마을 안내판"},"mis":"SC3-2-u2-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#9','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C1',2,'match','auto','장소와 그곳의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC3-2-u2-C1","difficulty":2,"kind":"match","stem":"장소와 그곳의 모습을 알맞게 이으세요.","pairs":[{"l":"빙하","r":"얼음 위의 북극곰"},{"l":"사막","r":"모래 언덕"},{"l":"호수","r":"넓게 고여 있는 물"}],"mis":"SC3-2-u2-X02","explanation":["장소를 떠올려요.","얼음은 빙하예요.","모래 언덕은 사막, 고인 물은 호수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#10','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C3',2,'match','auto','경험과 공기를 느낀 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"match","stem":"경험과 공기를 느낀 방법을 알맞게 이으세요.","pairs":[{"l":"돛단배 타기","r":"바람을 받아 나아가요"},{"l":"풍선 불기","r":"숨을 불어 넣어요"},{"l":"부채질","r":"바람을 일으켜요"}],"mis":"SC3-2-u2-X07","explanation":["돛은 바람을 받아요.","풍선은 숨이에요.","부채는 바람을 일으켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#11','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C7',2,'match','auto','물이 있는 곳과 알맞은 설명을 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC3-2-u2-C7","difficulty":2,"kind":"match","stem":"물이 있는 곳과 알맞은 설명을 이으세요.","pairs":[{"l":"강","r":"육지의 물이 있는 곳"},{"l":"바다","r":"바닷물이 있는 곳"},{"l":"들","r":"땅으로 이루어진 곳"}],"mis":"SC3-2-u2-X14","explanation":["강은 육지에 있어요.","바다에는 바닷물이에요.","들은 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#12','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C9',2,'match','auto','두 물을 가열한 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"match","stem":"두 물을 가열한 결과를 알맞게 이으세요.","pairs":[{"l":"마을 냇물","r":"남은 물질이 없어요"},{"l":"바닷물","r":"하얀 물질이 남아요"},{"l":"남은 하얀 물질","r":"대부분 소금이에요"}],"mis":"SC3-2-u2-X18","explanation":["냇물은 남은 것이 없어요.","바닷물은 남아요.","남은 것은 소금이에요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#13','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C10',2,'match','auto','물결반 일지 ④의 안내판과 지형 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"match","stem":"물결반 일지 ④의 안내판과 지형 이름을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"절벽"},{"l":"㉡","r":"동굴"},{"l":"㉣","r":"갯벌"}],"mis":"SC3-2-u2-X23","explanation":["가파르면 절벽이에요.","구멍이면 동굴이에요.","진흙이면 갯벌이에요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
