INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#15','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C14',2,'match','auto','갯벌에 대한 질문과 답을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC3-2-u2-C14","difficulty":2,"kind":"match","stem":"갯벌에 대한 질문과 답을 알맞게 이으세요.","pairs":[{"l":"갯벌이 많은 곳","r":"서해안과 남해안"},{"l":"갯벌이 드러나는 때","r":"썰물 때"},{"l":"갯벌에 사는 조개","r":"바지락"}],"mis":"SC3-2-u2-X33","explanation":["갯벌이 많은 곳은 서쪽과 남쪽이에요.","썰물 때 드러나요.","조개는 바지락이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#16','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C19',2,'match','auto','물결반 일지 ⑧의 장소와 얻는 자원을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"match","stem":"물결반 일지 ⑧의 장소와 얻는 자원을 알맞게 이으세요.","pairs":[{"l":"염전","r":"소금"},{"l":"시장","r":"김과 미역"},{"l":"바닷가 시설","r":"전기"}],"mis":"SC3-2-u2-X43","explanation":["염전은 소금이에요.","시장은 해조류예요.","시설은 전기예요."],"asset":{"type":"passage","lines":["염전 — 바닷물을 끌어 들여 햇빛에 두고 소금을 얻어요.","시장 — 게, 조개와 김, 미역, 다시마를 팔아요.","바닷가 시설 — 바닷물의 움직임으로 전기를 만들어요."],"title":"물결반 일지 ⑧ 바다 마을 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#17','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C1',3,'mc','auto','「사막, 북극의 빙하, 고래가 사는 바다, 진흙이 펼쳐진 갯벌」을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X01','SC3-2-u2-X10']::text[],false,'{"seq":17,"concept":"SC3-2-u2-C1","difficulty":3,"kind":"mc","stem":"「사막, 북극의 빙하, 고래가 사는 바다, 진흙이 펼쳐진 갯벌」을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"지구의 육지와 바다에는 다양한 모습이 있다","correct":true},{"t":"지구에는 바다 한 가지 모습만 있다","mis":"SC3-2-u2-X01"},{"t":"모두 지구 밖의 모습이다","mis":"SC3-2-u2-X01"},{"t":"모두 육지의 모습이다","mis":"SC3-2-u2-X10"}],"explanation":["네 가지를 떠올려요.","모두 달라요.","다양한 모습이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#18','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C7',3,'mc','auto','지구의 물을 육지의 물과 바닷물로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u2-X14']::text[],false,'{"seq":18,"concept":"SC3-2-u2-C7","difficulty":3,"kind":"mc","stem":"지구의 물을 육지의 물과 바닷물로 바르게 나눈 것은 무엇인가요?","options":[{"t":"육지의 물 — 강, 호수, 계곡, 빙하 / 바닷물 — 바다","correct":true},{"t":"육지의 물 — 바다, 강 / 바닷물 — 호수","mis":"SC3-2-u2-X14"},{"t":"육지의 물 — 계곡 / 바닷물 — 강, 호수, 빙하","mis":"SC3-2-u2-X14"},{"t":"육지의 물 — 바다 / 바닷물 — 강, 호수","mis":"SC3-2-u2-X14"}],"explanation":["육지에 있는 물을 떠올려요.","바다에는 바닷물이에요.","그렇게 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#19','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C8',3,'mc','auto','두 물을 가열할 때 같은 양씩 담아 같은 방법으로 가열하는 까닭은 무엇인가요?',ARRAY['SC3-2-u2-X17','SC3-2-u2-X16']::text[],false,'{"seq":19,"concept":"SC3-2-u2-C8","difficulty":3,"kind":"mc","stem":"두 물을 가열할 때 같은 양씩 담아 같은 방법으로 가열하는 까닭은 무엇인가요?","options":[{"t":"남는 물질을 바르게 견주기 위해서","correct":true},{"t":"빨리 끝내기 위해서","mis":"SC3-2-u2-X17"},{"t":"맛을 보기 위해서","mis":"SC3-2-u2-X16"},{"t":"한 접시만 가열하려고","mis":"SC3-2-u2-X17"}],"explanation":["두 물을 견줘요.","조건이 같아야 해요.","바르게 견주려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#20','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C11',3,'mc','auto','바닷가 지형을 조사하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X26','SC3-2-u2-X24']::text[],false,'{"seq":20,"concept":"SC3-2-u2-C11","difficulty":3,"kind":"mc","stem":"바닷가 지형을 조사하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"스마트 기기로 바닷가 지형 사진을 찾아 특징을 정리한다","correct":true},{"t":"수업과 관계없는 동영상을 본다","mis":"SC3-2-u2-X26"},{"t":"사막 사진을 찾아 바닷가 지형으로 올린다","mis":"SC3-2-u2-X24"},{"t":"친구 사진을 몰래 지운다","mis":"SC3-2-u2-X26"}],"explanation":["조사 방법이에요.","사진을 찾아요.","특징을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#21','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C14',3,'mc','auto','바닷물의 높이가 바뀌지 않는다면 갯벌은 어떻게 될까요?',ARRAY['SC3-2-u2-X32','SC3-2-u2-X33']::text[],false,'{"seq":21,"concept":"SC3-2-u2-C14","difficulty":3,"kind":"mc","stem":"바닷물의 높이가 바뀌지 않는다면 갯벌은 어떻게 될까요?","options":[{"t":"바닷물에 잠겼다 드러났다 하지 않으니 갯벌이 생기기 어렵다","correct":true},{"t":"갯벌이 더 넓어진다","mis":"SC3-2-u2-X32"},{"t":"갯벌과는 아무 상관이 없다","mis":"SC3-2-u2-X32"},{"t":"갯벌이 동해안에 많아진다","mis":"SC3-2-u2-X33"}],"explanation":["갯벌의 뜻을 떠올려요.","잠기고 드러나요.","생기기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#22','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C15',3,'mc','auto','물결반 일지 ⑥에서 게가 판 굴이 갯벌에 주는 도움은 무엇인가요?',ARRAY['SC3-2-u2-X36','SC3-2-u2-X35']::text[],false,'{"seq":22,"concept":"SC3-2-u2-C15","difficulty":3,"kind":"mc","stem":"물결반 일지 ⑥에서 게가 판 굴이 갯벌에 주는 도움은 무엇인가요?","options":[{"t":"신선한 공기가 드나들어 갯벌이 썩지 않게 한다","correct":true},{"t":"갯벌이 바닷물에 잠기지 않게 한다","mis":"SC3-2-u2-X36"},{"t":"바닷물을 짜게 만든다","mis":"SC3-2-u2-X35"},{"t":"철새를 쫓아낸다","mis":"SC3-2-u2-X36"}],"explanation":["굴을 떠올려요.","공기가 드나들어요.","썩지 않아요."],"asset":{"type":"passage","lines":["본 생물 — 칠게, 바지락, 낙지, 알락꼬리마도요","게가 판 굴이 여기저기 있었다.","친구 가 — 바지락을 보이는 대로 모두 캐서 집에 가져가려 했다.","친구 나 — 가져온 쓰레기를 모두 봉투에 담아 왔다."],"title":"물결반 일지 ⑥ 갯벌 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#23','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C9',4,'mc','auto','물결반 일지 ③과 ⑧을 함께 보고 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X18','SC3-2-u2-X16','SC3-2-u2-X20']::text[],false,'{"seq":23,"concept":"SC3-2-u2-C9","difficulty":4,"kind":"mc","stem":"물결반 일지 ③과 ⑧을 함께 보고 알맞게 말한 것은 무엇인가요?","options":[{"t":"바닷물에는 소금이 녹아 있어, 염전에서 바닷물을 햇빛에 두면 소금을 얻을 수 있다","correct":true},{"t":"냇물을 염전에 두어도 소금을 많이 얻는다","mis":"SC3-2-u2-X18"},{"t":"소금은 바닷물을 맛보아 얻는다","mis":"SC3-2-u2-X16"},{"t":"염전의 소금은 모래에서 나온다","mis":"SC3-2-u2-X20"}],"explanation":["③은 가열이에요.","⑧은 염전이에요.","둘 다 바닷물의 소금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#24','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C9',4,'essay','teacher','물결반 일지 ③을 보고 두 물을 구별한 방법과 결과를 쓰고, 바닷물을 그대로 마시거나 농사에 쓰기 어려운 까닭을 쓰세요. 실험에서 지킨 안전 약속도 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u2-C9","difficulty":4,"kind":"essay","stem":"물결반 일지 ③을 보고 두 물을 구별한 방법과 결과를 쓰고, 바닷물을 그대로 마시거나 농사에 쓰기 어려운 까닭을 쓰세요. 실험에서 지킨 안전 약속도 하나 쓰세요.","answer_guide":{"answer":"예: 냇물과 바닷물을 증발 접시에 담아 물이 없어질 때까지 가열했다. 냇물은 남은 물질이 없었고, 바닷물은 하얗고 거칠거칠한 물질이 남았다. 남은 물질의 대부분은 소금이라 바닷물은 짜서 마시거나 농사에 쓰기 어렵다. 실험할 때 실험 재료를 맛보지 않았다.","scoring_points":["구별한 방법과 결과를 썼는가","바닷물을 쓰기 어려운 까닭을 소금과 이어 썼는가","안전 약속을 썼는가"]},"explanation":["방법을 써요.","까닭을 써요.","약속을 써요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_b#25','sci',3,2,'u2','','g3_2_sci_u2_review_b','unit_review','SC3-2-u2-C17',4,'essay','teacher','물결반 일지 ⑦의 포스터에 대해 잘한 점 하나를 갯벌의 가치와 이어 쓰고, 보완할 점 하나를 더 좋은 방법과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u2-C17","difficulty":4,"kind":"essay","stem":"물결반 일지 ⑦의 포스터에 대해 잘한 점 하나를 갯벌의 가치와 이어 쓰고, 보완할 점 하나를 더 좋은 방법과 함께 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 갯벌이 바다를 깨끗하게 하고 생물의 터전이라는 가치를 담아, 보는 사람이 갯벌이 소중하다는 것을 알 수 있다. 보완할 점 — 가져온 사진의 출처를 밝히고, 생물을 함부로 잡지 말자는 내용을 더 넣으면 좋겠다.","scoring_points":["잘한 점을 썼는가","잘한 점을 갯벌의 가치와 이어 썼는가","보완할 점을 더 좋은 방법과 함께 썼는가"]},"explanation":["잘한 점부터 써요.","가치와 이어요.","고칠 방법을 써요."],"asset":{"type":"passage","lines":["제목 — 「갯벌은 살아 있어요!」","내용 — 갯벌이 바다를 깨끗하게 해요 · 생물의 터전이에요","내용 — 쓰레기를 버리지 말아요","친구 의견 — 「생물 그림이 생생해. 사진 출처를 밝히면 더 좋겠어.」"],"title":"물결반 일지 ⑦ 홍보 포스터 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#1','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C3',1,'ox','auto','물결반 일지 ①의 선생님 말씀처럼 공기는 보이지 않지만 어디에나 있어요.',ARRAY['SC3-2-u2-X06']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C3","difficulty":1,"kind":"ox","stem":"물결반 일지 ①의 선생님 말씀처럼 공기는 보이지 않지만 어디에나 있어요.","answer":"O","reason_options":[{"t":"바람개비가 돌고 연이 뜨는 것으로 공기를 느낄 수 있기 때문에","correct":true},{"t":"공기는 언덕 위에만 있기 때문에","mis":"SC3-2-u2-X06"}],"mis":"SC3-2-u2-X06","explanation":["일지를 읽어요.","공기를 느꼈어요.","그래서 O예요."],"asset":{"type":"passage","lines":["바닷가 언덕에서 바람개비가 빙글빙글 돌고 있었다.","하늘에는 연과 패러글라이딩을 하는 사람이 보였다.","선생님 — 「공기는 보이지 않지만 어디에나 있어요.」"],"title":"물결반 일지 ① 버스 창밖"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#2','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C6',1,'ox','auto','물결반 일지 ②를 보면 바다가 육지보다 넓어요.',ARRAY['SC3-2-u2-X11']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C6","difficulty":1,"kind":"ox","stem":"물결반 일지 ②를 보면 바다가 육지보다 넓어요.","answer":"O","reason_options":[{"t":"두 모둠 모두 바다 붙임쪽지가 더 많기 때문에","correct":true},{"t":"육지에 산과 들이 많기 때문에","mis":"SC3-2-u2-X11"}],"mis":"SC3-2-u2-X11","explanation":["붙임쪽지 수를 봐요.","바다가 많아요.","그래서 O예요."],"asset":{"type":"passage","lines":["1모둠 — 육지 붙임쪽지 20장 · 바다 붙임쪽지 50장","2모둠 — 육지 붙임쪽지 24장 · 바다 붙임쪽지 46장","덧붙임 — 바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙였다."],"title":"물결반 일지 ② 지구본 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#3','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C9',1,'ox','auto','바닷물은 사람이 그대로 마시기에 알맞아요.',ARRAY['SC3-2-u2-X21']::text[],false,'{"seq":3,"concept":"SC3-2-u2-C9","difficulty":1,"kind":"ox","stem":"바닷물은 사람이 그대로 마시기에 알맞아요.","answer":"X","reason_options":[{"t":"바닷물에는 소금이 많이 녹아 있기 때문에","correct":true},{"t":"바닷물은 아주 많기 때문에","mis":"SC3-2-u2-X21"}],"mis":"SC3-2-u2-X21","explanation":["바닷물을 떠올려요.","소금이 많아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#4','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C8',1,'ox','auto','물결반 일지 ③처럼 실험 재료는 맛보지 않아요.',ARRAY['SC3-2-u2-X16']::text[],false,'{"seq":4,"concept":"SC3-2-u2-C8","difficulty":1,"kind":"ox","stem":"물결반 일지 ③처럼 실험 재료는 맛보지 않아요.","answer":"O","reason_options":[{"t":"실험 재료를 맛보는 것은 위험하기 때문에","correct":true},{"t":"맛을 보아야 정확하기 때문에","mis":"SC3-2-u2-X16"}],"mis":"SC3-2-u2-X16","explanation":["약속을 읽어요.","맛보지 않아요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#5','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C10',1,'ox','auto','물결반 일지 ④의 ㉡은 동굴이에요.',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":5,"concept":"SC3-2-u2-C10","difficulty":1,"kind":"ox","stem":"물결반 일지 ④의 ㉡은 동굴이에요.","answer":"O","reason_options":[{"t":"바위에 구멍이 뚫려 물이 드나들기 때문에","correct":true},{"t":"모래가 넓게 펼쳐져 있기 때문에","mis":"SC3-2-u2-X23"}],"mis":"SC3-2-u2-X23","explanation":["㉡을 읽어요.","구멍이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#6','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C12',1,'ox','auto','썰물 때 바닷물의 높이가 낮아져요.',ARRAY['SC3-2-u2-X28']::text[],false,'{"seq":6,"concept":"SC3-2-u2-C12","difficulty":1,"kind":"ox","stem":"썰물 때 바닷물의 높이가 낮아져요.","answer":"O","reason_options":[{"t":"바닷물이 바다 쪽으로 빠져나가기 때문에","correct":true},{"t":"바닷물이 육지 쪽으로 밀려 들어오기 때문에","mis":"SC3-2-u2-X28"}],"mis":"SC3-2-u2-X28","explanation":["썰물을 떠올려요.","물이 나가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#7','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C15',1,'ox','auto','갯벌은 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해요.',ARRAY['SC3-2-u2-X35']::text[],false,'{"seq":7,"concept":"SC3-2-u2-C15","difficulty":1,"kind":"ox","stem":"갯벌은 육지에서 온 찌꺼기를 걸러 바다를 깨끗하게 해요.","answer":"O","reason_options":[{"t":"갯벌과 갯벌에 사는 생물이 오염 물질을 분해해 주기 때문에","correct":true},{"t":"갯벌은 쓰레기를 모아 두는 곳이기 때문에","mis":"SC3-2-u2-X35"}],"mis":"SC3-2-u2-X35","explanation":["갯벌의 역할이에요.","걸러 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#8','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C19',1,'ox','auto','바닷물의 움직임으로 전기를 만들 수 있어요.',ARRAY['SC3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SC3-2-u2-C19","difficulty":1,"kind":"ox","stem":"바닷물의 움직임으로 전기를 만들 수 있어요.","answer":"O","reason_options":[{"t":"파도의 힘이나 밀물과 썰물의 차이를 이용하기 때문에","correct":true},{"t":"바닷물은 움직이지 않기 때문에","mis":"SC3-2-u2-X43"}],"mis":"SC3-2-u2-X43","explanation":["파도를 떠올려요.","힘이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#9','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C2',2,'error','auto','다른 그림 찾기를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"error","stem":"다른 그림 찾기를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「찾은 건 비밀이야. 혼자만 알고 있을래.」","correct":true,"mis_target":"SC3-2-u2-X04"},{"t":"친구 가 — 「강 쪽에서 하나 찾았어.」","mis":"SC3-2-u2-X04"},{"t":"친구 나 — 「너는 바다 쪽, 나는 사막 쪽을 찾을게.」","mis":"SC3-2-u2-X04"}],"explanation":["함께하는 놀이예요.","찾으면 알려 줘요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#10','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C4',2,'error','auto','대기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X08','SC3-2-u2-X09']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C4","difficulty":2,"kind":"error","stem":"대기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「대기는 하늘에 떠 있는 구름이야.」","correct":true,"mis_target":"SC3-2-u2-X08"},{"t":"친구 가 — 「대기는 지구를 둘러싸고 있어.」","mis":"SC3-2-u2-X08"},{"t":"친구 다 — 「대기가 없으면 숨을 쉴 수 없어.」","mis":"SC3-2-u2-X09"}],"explanation":["대기의 뜻을 떠올려요.","공기예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#11','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C5',2,'error','auto','육지와 바다를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X10']::text[],false,'{"seq":11,"concept":"SC3-2-u2-C5","difficulty":2,"kind":"error","stem":"육지와 바다를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「계곡은 물이 있으니 바다야.」","correct":true,"mis_target":"SC3-2-u2-X10"},{"t":"친구 나 — 「사막은 육지에서 볼 수 있어.」","mis":"SC3-2-u2-X10"},{"t":"친구 다 — 「바다는 물로 덮여 있는 곳이야.」","mis":"SC3-2-u2-X10"}],"explanation":["계곡은 어디에 있나요?","육지예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#12','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C8',2,'error','auto','가열 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X16','SC3-2-u2-X17']::text[],false,'{"seq":12,"concept":"SC3-2-u2-C8","difficulty":2,"kind":"error","stem":"가열 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「전원을 끄면 핫플레이트를 바로 만져도 돼.」","correct":true,"mis_target":"SC3-2-u2-X16"},{"t":"친구 가 — 「끓임쪽을 넣으면 물이 갑자기 끓어오르지 않아.」","mis":"SC3-2-u2-X17"},{"t":"친구 나 — 「면장갑을 끼고 실험해.」","mis":"SC3-2-u2-X16"}],"explanation":["핫플레이트를 떠올려요.","끈 뒤에도 뜨거워요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#13','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C11',2,'error','auto','지형 사진을 게시판에 올리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X26','SC3-2-u2-X24']::text[],false,'{"seq":13,"concept":"SC3-2-u2-C11","difficulty":2,"kind":"error","stem":"지형 사진을 게시판에 올리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「친구 사진이 이상하다고 댓글을 달자.」","correct":true,"mis_target":"SC3-2-u2-X26"},{"t":"친구 가 — 「사진에 지형 이름과 특징을 함께 쓰자.」","mis":"SC3-2-u2-X26"},{"t":"친구 다 — 「네 가지 말고 다른 지형도 찾아보자.」","mis":"SC3-2-u2-X24"}],"explanation":["게시판 약속이에요.","존중해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#14','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C13',2,'error','auto','물결반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X30','SC3-2-u2-X28','SC3-2-u2-X31']::text[],false,'{"seq":14,"concept":"SC3-2-u2-C13","difficulty":2,"kind":"error","stem":"물결반 일지 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「파도가 여러 번 밀려왔으니 밀물과 썰물도 여러 번 바뀌었어.」","correct":true,"mis_target":"SC3-2-u2-X30"},{"t":"친구 가 — 「오후 4시에는 바닷물의 높이가 높아졌어.」","mis":"SC3-2-u2-X28"},{"t":"친구 나 — 「바닷물의 높이는 시간에 따라 달라져.」","mis":"SC3-2-u2-X31"}],"explanation":["파도와 밀물은 달라요.","파도는 잠깐이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["오전 10시 — 바닷길이 드러나 표지판 아래 모래가 보였다.","오후 4시 — 바닷물이 밀려 들어와 바닷길과 표지판이 잠겼다.","덧붙임 — 그사이 파도는 여러 번 밀려왔다 쓸려 나갔다."],"title":"물결반 일지 ⑤ 섬 바닷길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#15','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C16',2,'error','auto','갯벌 체험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X37','SC3-2-u2-X36']::text[],false,'{"seq":15,"concept":"SC3-2-u2-C16","difficulty":2,"kind":"error","stem":"갯벌 체험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「바지락이 많으니 보이는 대로 모두 캐 가도 돼.」","correct":true,"mis_target":"SC3-2-u2-X37"},{"t":"친구 나 — 「쓰레기는 봉투에 담아 와.」","mis":"SC3-2-u2-X37"},{"t":"친구 다 — 「게가 판 굴은 갯벌에 공기가 드나들게 해.」","mis":"SC3-2-u2-X36"}],"explanation":["생물을 아껴요.","함부로 잡지 않아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#16','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C17',2,'error','auto','물결반 일지 ⑦의 포스터를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X39']::text[],false,'{"seq":16,"concept":"SC3-2-u2-C17","difficulty":2,"kind":"error","stem":"물결반 일지 ⑦의 포스터를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「가져온 사진의 출처는 안 밝혀도 돼.」","correct":true,"mis_target":"SC3-2-u2-X39"},{"t":"친구 가 — 「갯벌의 가치가 잘 드러나.」","mis":"SC3-2-u2-X39"},{"t":"친구 나 — 「우리가 할 일도 들어 있어 좋아.」","mis":"SC3-2-u2-X39"}],"explanation":["가져온 자료예요.","출처를 밝혀요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["제목 — 「갯벌은 살아 있어요!」","내용 — 갯벌이 바다를 깨끗하게 해요 · 생물의 터전이에요","내용 — 쓰레기를 버리지 말아요","친구 의견 — 「생물 그림이 생생해. 사진 출처를 밝히면 더 좋겠어.」"],"title":"물결반 일지 ⑦ 홍보 포스터 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#17','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C1',3,'error','auto','지구의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X02']::text[],false,'{"seq":17,"concept":"SC3-2-u2-C1","difficulty":3,"kind":"error","stem":"지구의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「빙하에서는 게와 짱뚱어를 쉽게 볼 수 있어.」","correct":true,"mis_target":"SC3-2-u2-X02"},{"t":"친구 가 — 「사막에서는 모래 언덕을 볼 수 있어.」","mis":"SC3-2-u2-X02"},{"t":"친구 다 — 「갯벌에는 진흙이 펼쳐져 있어.」","mis":"SC3-2-u2-X02"}],"explanation":["장소와 모습을 이어요.","게는 갯벌에 살아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#18','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C6',3,'error','auto','물결반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X11','SC3-2-u2-X13','SC3-2-u2-X12']::text[],false,'{"seq":18,"concept":"SC3-2-u2-C6","difficulty":3,"kind":"error","stem":"물결반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「육지에 볼 것이 더 많으니 육지가 넓은 게 맞아.」","correct":true,"mis_target":"SC3-2-u2-X11"},{"t":"친구 나 — 「바다 붙임쪽지가 많을수록 바다가 넓은 거야.」","mis":"SC3-2-u2-X13"},{"t":"친구 다 — 「모둠마다 개수가 달라도 괜찮아.」","mis":"SC3-2-u2-X12"}],"explanation":["모습의 수와 넓이는 달라요.","바다가 넓어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["1모둠 — 육지 붙임쪽지 20장 · 바다 붙임쪽지 50장","2모둠 — 육지 붙임쪽지 24장 · 바다 붙임쪽지 46장","덧붙임 — 바다가 절반이 넘는 칸에는 바다 붙임쪽지를 붙였다."],"title":"물결반 일지 ② 지구본 붙임쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#19','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C9',3,'error','auto','바닷물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X21','SC3-2-u2-X18','SC3-2-u2-X19']::text[],false,'{"seq":19,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"error","stem":"바닷물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「바닷물은 짜지만 농사짓는 데 그대로 써도 돼.」","correct":true,"mis_target":"SC3-2-u2-X21"},{"t":"친구 가 — 「바닷물을 가열하면 하얀 물질이 남아.」","mis":"SC3-2-u2-X18"},{"t":"친구 다 — 「남은 물질은 냄새가 나지 않아.」","mis":"SC3-2-u2-X19"}],"explanation":["농사를 떠올려요.","소금이 많아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#20','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C10',3,'error','auto','물결반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X23']::text[],false,'{"seq":20,"concept":"SC3-2-u2-C10","difficulty":3,"kind":"error","stem":"물결반 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉣은 진흙이 있으니 모래사장이야.」","correct":true,"mis_target":"SC3-2-u2-X23"},{"t":"친구 가 — 「㉢은 모래사장이야.」","mis":"SC3-2-u2-X23"},{"t":"친구 나 — 「㉠은 가파른 절벽이야.」","mis":"SC3-2-u2-X23"}],"explanation":["진흙이 보이는 지형이에요.","갯벌이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#21','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C12',3,'error','auto','바닷물의 높이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X29','SC3-2-u2-X32']::text[],false,'{"seq":21,"concept":"SC3-2-u2-C12","difficulty":3,"kind":"error","stem":"바닷물의 높이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「썰물 때 바닷물이 육지 쪽으로 들어와 높이가 높아져.」","correct":true,"mis_target":"SC3-2-u2-X27"},{"t":"친구 나 — 「밀물 때 표지판이 물에 잠겨.」","mis":"SC3-2-u2-X29"},{"t":"친구 다 — 「썰물 때 갯벌이 드러나.」","mis":"SC3-2-u2-X32"}],"explanation":["썰물을 떠올려요.","빠져나가요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#22','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C17',3,'error','auto','물결반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u2-X39','SC3-2-u2-X40']::text[],false,'{"seq":22,"concept":"SC3-2-u2-C17","difficulty":3,"kind":"error","stem":"물결반 일지 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「포스터에서 갯벌의 가치는 빼고 그림만 크게 넣자.」","correct":true,"mis_target":"SC3-2-u2-X39"},{"t":"친구 가 — 「쓰레기를 버리지 말자는 내용이 좋아.」","mis":"SC3-2-u2-X39"},{"t":"친구 다 — 「출처를 밝히자는 의견을 받아들이자.」","mis":"SC3-2-u2-X40"}],"explanation":["홍보 자료에서 중요한 것이에요.","가치가 드러나야 해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["제목 — 「갯벌은 살아 있어요!」","내용 — 갯벌이 바다를 깨끗하게 해요 · 생물의 터전이에요","내용 — 쓰레기를 버리지 말아요","친구 의견 — 「생물 그림이 생생해. 사진 출처를 밝히면 더 좋겠어.」"],"title":"물결반 일지 ⑦ 홍보 포스터 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#23','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C13',4,'mc','auto','물결반 일지 ⑤와 ⑥을 함께 떠올려 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u2-X29','SC3-2-u2-X30','SC3-2-u2-X32']::text[],false,'{"seq":23,"concept":"SC3-2-u2-C13","difficulty":4,"kind":"mc","stem":"물결반 일지 ⑤와 ⑥을 함께 떠올려 알맞게 말한 것은 무엇인가요?","options":[{"t":"썰물 때 바닷물이 빠져나가면 갯벌이 드러나 갯벌 체험을 할 수 있다","correct":true},{"t":"밀물 때 갯벌이 드러나 체험하기 좋다","mis":"SC3-2-u2-X29"},{"t":"파도가 칠 때마다 갯벌이 생긴다","mis":"SC3-2-u2-X30"},{"t":"갯벌은 바닷물의 높이와 관계없다","mis":"SC3-2-u2-X32"}],"explanation":["⑤는 바닷물 높이예요.","⑥은 갯벌 체험이에요.","썰물 때 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#24','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C12',4,'essay','teacher','물결반 일지 ⑤를 보고 오전 10시와 오후 4시의 바닷물 높이를 밀물·썰물과 이어 설명하고, 파도와 밀물·썰물이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u2-C12","difficulty":4,"kind":"essay","stem":"물결반 일지 ⑤를 보고 오전 10시와 오후 4시의 바닷물 높이를 밀물·썰물과 이어 설명하고, 파도와 밀물·썰물이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 오전 10시는 바닷물이 바다 쪽으로 빠져나간 썰물 때라 높이가 낮아져 바닷길이 드러났다. 오후 4시는 바닷물이 육지 쪽으로 밀려 들어온 밀물 때라 높이가 높아져 바닷길과 표지판이 잠겼다. 파도는 잠깐 밀려왔다 쓸려 나가지만, 밀물과 썰물은 일정 시간 동안 이어진다.","scoring_points":["두 때를 밀물·썰물로 바르게 썼는가","바닷물의 높이와 이어 설명했는가","파도와의 차이를 썼는가"]},"explanation":["두 때를 나눠요.","높이와 이어요.","파도와 견줘요."],"asset":{"type":"passage","lines":["오전 10시 — 바닷길이 드러나 표지판 아래 모래가 보였다.","오후 4시 — 바닷물이 밀려 들어와 바닷길과 표지판이 잠겼다.","덧붙임 — 그사이 파도는 여러 번 밀려왔다 쓸려 나갔다."],"title":"물결반 일지 ⑤ 섬 바닷길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_c#25','sci',3,2,'u2','','g3_2_sci_u2_review_c','unit_review','SC3-2-u2-C18',4,'essay','teacher','물결반 일지 ⑧을 보고 바다에서 얻는 자원을 세 가지 이상 쓰고, 그 가운데 하나가 우리 생활에 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u2-C18","difficulty":4,"kind":"essay","stem":"물결반 일지 ⑧을 보고 바다에서 얻는 자원을 세 가지 이상 쓰고, 그 가운데 하나가 우리 생활에 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 바다에서는 소금, 게와 조개, 김·미역·다시마 같은 해조류, 전기를 얻는다. 바닷물의 움직임으로 만든 전기는 환경 오염 걱정이 없는 친환경 에너지라 우리가 전기를 쓰면서도 환경을 지키는 데 도움이 된다.","scoring_points":["바다 자원을 세 가지 이상 썼는가","하나를 골랐는가","생활에 주는 도움을 썼는가"]},"explanation":["자원을 찾아요.","하나를 골라요.","도움을 써요."],"asset":{"type":"passage","lines":["염전 — 바닷물을 끌어 들여 햇빛에 두고 소금을 얻어요.","시장 — 게, 조개와 김, 미역, 다시마를 팔아요.","바닷가 시설 — 바닷물의 움직임으로 전기를 만들어요."],"title":"물결반 일지 ⑧ 바다 마을 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#1','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C4',1,'mc','auto','지구에 대기가 없으면 우리가 할 수 없게 되는 것은 무엇인가요?',ARRAY['SC3-2-u2-X09']::text[],false,'{"seq":1,"concept":"SC3-2-u2-C4","difficulty":1,"kind":"mc","stem":"지구에 대기가 없으면 우리가 할 수 없게 되는 것은 무엇인가요?","options":[{"t":"숨 쉬기","correct":true},{"t":"잠자기","mis":"SC3-2-u2-X09"},{"t":"책 읽기","mis":"SC3-2-u2-X09"},{"t":"그림 그리기","mis":"SC3-2-u2-X09"}],"explanation":["공기가 필요한 일이에요.","코와 입으로 해요.","숨 쉬기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#2','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C5',1,'mc','auto','물로 덮여 있는 곳은 무엇인가요?',ARRAY['SC3-2-u2-X10']::text[],false,'{"seq":2,"concept":"SC3-2-u2-C5","difficulty":1,"kind":"mc","stem":"물로 덮여 있는 곳은 무엇인가요?","options":[{"t":"바다","correct":true},{"t":"산","mis":"SC3-2-u2-X10"},{"t":"들","mis":"SC3-2-u2-X10"},{"t":"사막","mis":"SC3-2-u2-X10"}],"explanation":["물로 덮여 있어요.","고래가 살아요.","바다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
