INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#9','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C2',2,'mc','auto','다른 그림 찾기의 목적으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X04','SC3-2-u2-X01']::text[],false,'{"seq":9,"concept":"SC3-2-u2-C2","difficulty":2,"kind":"mc","stem":"다른 그림 찾기의 목적으로 알맞은 것은 무엇인가요?","options":[{"t":"지구의 다양한 모습을 함께 살펴보는 것","correct":true},{"t":"가장 빨리 찾아 일등 하는 것","mis":"SC3-2-u2-X04"},{"t":"친구보다 많이 찾아 자랑하는 것","mis":"SC3-2-u2-X04"},{"t":"그림 속에서 달을 찾는 것","mis":"SC3-2-u2-X01"}],"explanation":["놀이의 목적이에요.","지구를 살펴봐요.","함께 살펴보는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#10','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C3',2,'mc','auto','공기를 느낄 수 있는 경험과 거리가 먼 것은 무엇인가요?',ARRAY['SC3-2-u2-X07']::text[],false,'{"seq":10,"concept":"SC3-2-u2-C3","difficulty":2,"kind":"mc","stem":"공기를 느낄 수 있는 경험과 거리가 먼 것은 무엇인가요?","options":[{"t":"어항 속 물을 들여다본다","correct":true},{"t":"숨을 쉰다","mis":"SC3-2-u2-X07"},{"t":"풍선을 분다","mis":"SC3-2-u2-X07"},{"t":"연을 날린다","mis":"SC3-2-u2-X07"}],"explanation":["바람이나 숨을 찾아요.","하나는 물이에요.","어항 속 물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#11','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C6',2,'mc','auto','붙임쪽지를 바르게 붙인 친구는 누구인가요?',ARRAY['SC3-2-u2-X12']::text[],false,'{"seq":11,"concept":"SC3-2-u2-C6","difficulty":2,"kind":"mc","stem":"붙임쪽지를 바르게 붙인 친구는 누구인가요?","options":[{"t":"붙임쪽지가 겹치지 않게, 더 많이 차지한 쪽을 따라 붙인 친구","correct":true},{"t":"붙임쪽지를 겹겹이 붙인 친구","mis":"SC3-2-u2-X12"},{"t":"육지가 조금이라도 있으면 육지로 붙인 친구","mis":"SC3-2-u2-X12"},{"t":"아무 칸에나 바다 붙임쪽지를 붙인 친구","mis":"SC3-2-u2-X12"}],"explanation":["겹치지 않아요.","절반이 넘는 쪽이에요.","그 친구가 바르게 붙였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#12','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C9',2,'mc','auto','바닷물을 가열하고 남은 물질을 관찰한 결과로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X19']::text[],false,'{"seq":12,"concept":"SC3-2-u2-C9","difficulty":2,"kind":"mc","stem":"바닷물을 가열하고 남은 물질을 관찰한 결과로 알맞은 것은 무엇인가요?","options":[{"t":"하얗고 거칠거칠하며 냄새가 나지 않는다","correct":true},{"t":"검고 매끈하며 냄새가 난다","mis":"SC3-2-u2-X19"},{"t":"투명하고 말랑하다","mis":"SC3-2-u2-X19"},{"t":"파랗고 달콤한 냄새가 난다","mis":"SC3-2-u2-X19"}],"explanation":["색깔, 느낌, 냄새예요.","하얗고 거칠거칠해요.","냄새는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#13','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C10',2,'mc','auto','모래사장과 갯벌의 차이로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X25','SC3-2-u2-X23']::text[],false,'{"seq":13,"concept":"SC3-2-u2-C10","difficulty":2,"kind":"mc","stem":"모래사장과 갯벌의 차이로 알맞은 것은 무엇인가요?","options":[{"t":"모래사장은 모래가 펼쳐져 있고, 갯벌은 진흙이 보이고 색이 어둡다","correct":true},{"t":"모래사장은 바위로, 갯벌은 모래로 되어 있다","mis":"SC3-2-u2-X25"},{"t":"둘 다 바위에 구멍이 있다","mis":"SC3-2-u2-X23"},{"t":"모래사장은 가파르고 갯벌은 구멍이 있다","mis":"SC3-2-u2-X23"}],"explanation":["두 지형을 떠올려요.","모래와 진흙이에요.","그게 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#14','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C12',2,'mc','auto','밀물을 바르게 설명한 것은 무엇인가요?',ARRAY['SC3-2-u2-X27','SC3-2-u2-X30','SC3-2-u2-X28']::text[],false,'{"seq":14,"concept":"SC3-2-u2-C12","difficulty":2,"kind":"mc","stem":"밀물을 바르게 설명한 것은 무엇인가요?","options":[{"t":"바닷물이 바다에서 육지 쪽으로 밀려 들어오는 것","correct":true},{"t":"바닷물이 육지에서 바다 쪽으로 빠져나가는 것","mis":"SC3-2-u2-X27"},{"t":"파도가 한 번 밀려오는 것","mis":"SC3-2-u2-X30"},{"t":"바닷물의 높이가 낮아지는 것","mis":"SC3-2-u2-X28"}],"explanation":["밀려 들어와요.","육지 쪽이에요.","그게 밀물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#15','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C14',2,'mc','auto','물결반 일지 ⑥에서 게가 판 굴이 여기저기 있는 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u2-X34','SC3-2-u2-X32','SC3-2-u2-X35']::text[],false,'{"seq":15,"concept":"SC3-2-u2-C14","difficulty":2,"kind":"mc","stem":"물결반 일지 ⑥에서 게가 판 굴이 여기저기 있는 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"갯벌에 생물이 많이 살고 있다","correct":true},{"t":"갯벌에는 생물이 살지 않는다","mis":"SC3-2-u2-X34"},{"t":"갯벌은 언제나 바닷물에 잠겨 있다","mis":"SC3-2-u2-X32"},{"t":"갯벌은 오염된 땅이다","mis":"SC3-2-u2-X35"}],"explanation":["굴을 판 것은 게예요.","생물이 살아요.","생물이 많아요."],"asset":{"type":"passage","lines":["본 생물 — 칠게, 바지락, 낙지, 알락꼬리마도요","게가 판 굴이 여기저기 있었다.","친구 가 — 바지락을 보이는 대로 모두 캐서 집에 가져가려 했다.","친구 나 — 가져온 쓰레기를 모두 봉투에 담아 왔다."],"title":"물결반 일지 ⑥ 갯벌 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#16','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C19',2,'mc','auto','바다에서 얻는 전기를 만드는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X43','SC3-2-u2-X42']::text[],false,'{"seq":16,"concept":"SC3-2-u2-C19","difficulty":2,"kind":"mc","stem":"바다에서 얻는 전기를 만드는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"파도가 치는 힘이나 밀물과 썰물의 차이를 이용한다","correct":true},{"t":"바닷물을 햇빛에 둔다","mis":"SC3-2-u2-X43"},{"t":"미역을 말린다","mis":"SC3-2-u2-X42"},{"t":"갯벌에 굴을 판다","mis":"SC3-2-u2-X43"}],"explanation":["바닷물의 움직임이에요.","파도와 밀물·썰물이에요.","그 힘을 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#17','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C2',3,'ox','auto','다른 그림 찾기에서 친구가 찾은 곳이 나와 달라도 존중해요.',ARRAY['SC3-2-u2-X04']::text[],false,'{"seq":17,"concept":"SC3-2-u2-C2","difficulty":3,"kind":"ox","stem":"다른 그림 찾기에서 친구가 찾은 곳이 나와 달라도 존중해요.","answer":"O","reason_options":[{"t":"함께 지구의 모습을 살펴보는 놀이이기 때문에","correct":true},{"t":"내가 찾은 것만 정답이기 때문에","mis":"SC3-2-u2-X04"}],"mis":"SC3-2-u2-X04","explanation":["함께하는 놀이예요.","생각이 다를 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#18','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C7',3,'ox','auto','우리가 쓸 수 있는 육지의 물은 적어서 아껴 써야 해요.',ARRAY['SC3-2-u2-X15']::text[],false,'{"seq":18,"concept":"SC3-2-u2-C7","difficulty":3,"kind":"ox","stem":"우리가 쓸 수 있는 육지의 물은 적어서 아껴 써야 해요.","answer":"O","reason_options":[{"t":"지구의 물은 대부분 바닷물이기 때문에","correct":true},{"t":"지구의 물은 대부분 육지의 물이기 때문에","mis":"SC3-2-u2-X15"}],"mis":"SC3-2-u2-X15","explanation":["지구의 물을 떠올려요.","대부분 바닷물이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#19','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C9',3,'ox','auto','물결반 일지 ③의 ㉮ 냇물을 가열해도 소금이 남아요.',ARRAY['SC3-2-u2-X18']::text[],false,'{"seq":19,"concept":"SC3-2-u2-C9","difficulty":3,"kind":"ox","stem":"물결반 일지 ③의 ㉮ 냇물을 가열해도 소금이 남아요.","answer":"X","reason_options":[{"t":"냇물 같은 육지의 물은 가열하면 남는 물질이 없기 때문에","correct":true},{"t":"모든 물에는 소금이 녹아 있기 때문에","mis":"SC3-2-u2-X18"}],"mis":"SC3-2-u2-X18","explanation":["㉮의 결과를 읽어요.","남은 것이 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 마을 냇물 — 가열했더니 남은 물질이 없었다.","㉯ 바닷물 — 가열했더니 하얗고 거칠거칠한 물질이 남았다.","약속 — 맛보지 않기 · 보안경과 면장갑 쓰기 · 접시는 집게로 옮기기"],"title":"물결반 일지 ③ 두 물 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#20','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C13',3,'ox','auto','물결반 일지 ⑤에서 파도가 여러 번 밀려왔다 쓸려 나간 것은 밀물과 썰물이 아니에요.',ARRAY['SC3-2-u2-X30']::text[],false,'{"seq":20,"concept":"SC3-2-u2-C13","difficulty":3,"kind":"ox","stem":"물결반 일지 ⑤에서 파도가 여러 번 밀려왔다 쓸려 나간 것은 밀물과 썰물이 아니에요.","answer":"O","reason_options":[{"t":"파도는 잠깐 일어나는 일이고 밀물과 썰물은 일정 시간 동안 이어지기 때문에","correct":true},{"t":"파도와 밀물은 같은 일이기 때문에","mis":"SC3-2-u2-X30"}],"mis":"SC3-2-u2-X30","explanation":["파도를 떠올려요.","잠깐이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["오전 10시 — 바닷길이 드러나 표지판 아래 모래가 보였다.","오후 4시 — 바닷물이 밀려 들어와 바닷길과 표지판이 잠겼다.","덧붙임 — 그사이 파도는 여러 번 밀려왔다 쓸려 나갔다."],"title":"물결반 일지 ⑤ 섬 바닷길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#21','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C14',3,'ox','auto','동해안은 밀물과 썰물 때 바닷물의 높이 차가 작아 갯벌을 찾아보기 어려워요.',ARRAY['SC3-2-u2-X33']::text[],false,'{"seq":21,"concept":"SC3-2-u2-C14","difficulty":3,"kind":"ox","stem":"동해안은 밀물과 썰물 때 바닷물의 높이 차가 작아 갯벌을 찾아보기 어려워요.","answer":"O","reason_options":[{"t":"갯벌은 높이 차가 큰 곳에 잘 생기기 때문에","correct":true},{"t":"동해안은 바닷물이 더 짜기 때문에","mis":"SC3-2-u2-X33"}],"mis":"SC3-2-u2-X33","explanation":["갯벌이 많은 곳을 떠올려요.","높이 차가 커요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#22','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C16',3,'ox','auto','오염된 갯벌에 울타리를 치면 바다는 오염되지 않아요.',ARRAY['SC3-2-u2-X38']::text[],false,'{"seq":22,"concept":"SC3-2-u2-C16","difficulty":3,"kind":"ox","stem":"오염된 갯벌에 울타리를 치면 바다는 오염되지 않아요.","answer":"X","reason_options":[{"t":"갯벌은 바닷물이 드나드는 곳이라 오염이 바다로 퍼질 수 있기 때문에","correct":true},{"t":"울타리가 바닷물을 막아 주기 때문에","mis":"SC3-2-u2-X38"}],"mis":"SC3-2-u2-X38","explanation":["갯벌을 떠올려요.","바닷물이 드나들어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#23','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C17',4,'mc','auto','물결반 일지 ⑥과 ⑦을 바탕으로 갯벌 홍보 포스터에 넣을 문구로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u2-X37','SC3-2-u2-X38','SC3-2-u2-X40']::text[],false,'{"seq":23,"concept":"SC3-2-u2-C17","difficulty":4,"kind":"mc","stem":"물결반 일지 ⑥과 ⑦을 바탕으로 갯벌 홍보 포스터에 넣을 문구로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「갯벌은 칠게, 바지락의 집이에요. 생물을 함부로 잡지 말고 쓰레기는 되가져가요!」","correct":true},{"t":"「갯벌 조개는 많으니 마음껏 캐 가세요!」","mis":"SC3-2-u2-X37"},{"t":"「울타리만 치면 갯벌은 안전해요!」","mis":"SC3-2-u2-X38"},{"t":"「우리 포스터가 제일 멋져요!」","mis":"SC3-2-u2-X40"}],"explanation":["가치를 담아요.","할 일도 담아요.","그 문구가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#24','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C10',4,'essay','teacher','물결반 일지 ④의 지형 네 가지 이름을 쓰고, 바위로 이루어진 지형과 모래나 흙으로 이루어진 지형으로 나누어 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u2-C10","difficulty":4,"kind":"essay","stem":"물결반 일지 ④의 지형 네 가지 이름을 쓰고, 바위로 이루어진 지형과 모래나 흙으로 이루어진 지형으로 나누어 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉠은 절벽, ㉡은 동굴, ㉢은 모래사장, ㉣은 갯벌이다. 절벽과 동굴은 가파르거나 구멍이 뚫린 단단한 바위로 이루어진 지형이고, 모래사장과 갯벌은 고운 모래나 진흙으로 이루어진 지형이다.","scoring_points":["네 지형의 이름을 바르게 썼는가","두 무리로 바르게 나누었는가","나눈 까닭을 특징으로 썼는가"]},"explanation":["이름을 써요.","두 무리로 나눠요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 높고 가파른 바위 언덕","㉡ 바위에 구멍이 뚫려 물이 드나드는 곳","㉢ 고운 모래가 넓게 펼쳐진 곳","㉣ 어두운 진흙에 물이 고여 있는 곳"],"title":"물결반 일지 ④ 바닷가 지형 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u2_review_d#25','sci',3,2,'u2','','g3_2_sci_u2_review_d','unit_review','SC3-2-u2-C4',4,'essay','teacher','「지구와 바다」 단원에서 배운 것을 바탕으로, 대기·바다·갯벌이 우리에게 주는 도움을 하나씩 쓰고, 우리가 지구와 바다를 위해 할 수 있는 일을 한 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u2-C4","difficulty":4,"kind":"essay","stem":"「지구와 바다」 단원에서 배운 것을 바탕으로, 대기·바다·갯벌이 우리에게 주는 도움을 하나씩 쓰고, 우리가 지구와 바다를 위해 할 수 있는 일을 한 가지 쓰세요.","answer_guide":{"answer":"예: 대기는 지구를 둘러싸고 있어 우리가 숨을 쉴 수 있게 한다. 바다는 소금, 해조류, 전기 같은 많은 자원을 준다. 갯벌은 생물의 터전이 되고 바다를 깨끗하게 한다. 우리는 바닷가나 갯벌에 쓰레기를 버리지 않고, 육지의 물을 아껴 쓸 수 있다.","scoring_points":["대기·바다·갯벌의 도움을 하나씩 썼는가","배운 내용과 맞게 썼는가","할 수 있는 일을 썼는가"]},"explanation":["셋을 떠올려요.","도움을 하나씩 써요.","할 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
